            ['heading' => 'Common errors', 'body' => 'Do not maximize floor area while ignoring stormwater, access, public realm, or future operations, and do not treat a single compliance check as proof that the whole site strategy is sound.'],
        ],
    ],
];

$questions = [];
$add = static function (array $spec) use (&$questions, $taxonomy, $batchDate): void {
    foreach (['concept', 'depth', 'context', 'stem', 'answer', 'wrong', 'explanation', 'scenario'] as $required) {
        if (!array_key_exists($required, $spec)) throw new RuntimeException('Question spec missing ' . $required);
    }
    $concept = (string)$spec['concept'];
    if (!isset($taxonomy[$concept])) throw new RuntimeException('Unknown Architecture concept: ' . $concept);
    $depth = (int)$spec['depth'];
    if (!in_array($depth, [2, 3, 4], true)) throw new RuntimeException('Invalid new Architecture depth: ' . $depth);
    $context = (string)$spec['context'];
    if (!in_array($context, ['NEUTRAL', 'PROFESSIONAL', 'REGULATORY'], true)) throw new RuntimeException('Invalid Architecture context: ' . $context);
    $wrong = array_values(array_map('strval', (array)$spec['wrong']));
    if (count(array_unique(array_merge([(string)$spec['answer']], $wrong))) !== 4) throw new RuntimeException('Choices are not distinct: ' . $spec['stem']);
    $t = $taxonomy[$concept];
    $numeric = (bool)($spec['numeric'] ?? false);
    $formula = (string)($spec['formula_family'] ?? ($numeric ? 'architecture-dimension-or-quantity' : 'qualitative-design-reasoning'));
    if ($numeric && $formula === '') throw new RuntimeException('Numerical item missing formula family.');
    $questions[] = [
        'taxonomy' => ['board_id' => 'architecture', 'subject_id' => $t['subject_id'], 'domain_id' => $t['domain_id'], 'topic_id' => $t['topic_id'], 'concept_id' => $concept],
        'board' => 'architecture', 'status' => 'active', 'source' => 'batch619-source-first',
        'createdAt' => $batchDate, 'updatedAt' => $batchDate,
        'difficulty' => $depth >= 4 ? 'hard' : ($depth === 3 ? 'medium' : 'easy'),
        'question' => (string)$spec['stem'], 'choices' => [], 'answer' => (string)$spec['answer'], '__wrong' => $wrong,
        'explanation' => (string)$spec['explanation'], 'subject' => $t['subject_id'], 'domain' => $t['domain_id'], 'topic' => $t['topic_id'], 'concept' => $concept,
        'numeric' => $numeric, 'multistep' => $depth >= 4, 'cognitive_intent' => $depth >= 4 ? 'analyze' : ($depth === 3 ? 'apply' : 'understand'),
        'source_sensitivity' => $context === 'REGULATORY' ? 'REGULATORY' : 'STABLE', 'content_blocks' => [],
        'unit_sensitive' => $numeric, 'table_dependent' => false, 'data_interpretation' => in_array((string)$spec['scenario'], ['comparison', 'diagnosis', 'parameter sensitivity', 'failure/error identification'], true),
        'long_scenario' => $depth >= 4 || $context !== 'NEUTRAL', 'professional_judgment' => $context === 'PROFESSIONAL', 'context_dependent' => $context !== 'NEUTRAL', 'context_necessary' => $context !== 'NEUTRAL',
        'passage_dependent' => false, 'passage_necessary' => false, 'technical_reasoning' => $concept === 'architecture-technical-integration', 'figure_dependent' => false,
        'site_plan_spatial' => $concept === 'architecture-spatial-integration', 'timesUsed' => 0, 'timesCorrect' => 0, 'timesIncorrect' => 0, 'bookmarks' => 0, 'reports' => 0, 'helpfulExplanation' => 0, 'notHelpfulExplanation' => 0,
        '__concept' => $concept, '__depth' => $depth, '__context' => $context, '__material' => (string)($spec['material'] ?? $t['materials'][0]), '__sources' => array_values(array_unique($t['sources'])),
        '__formula_family' => $formula, '__variable_pattern' => (string)($spec['variable_pattern'] ?? 'stated inputs and target decision'), '__target_variable' => (string)($spec['target_variable'] ?? 'design decision'),
        '__scenario' => (string)$spec['scenario'], '__prerequisite' => (string)($spec['prerequisite'] ?? 'PREREQUISITE_FREE'), '__numeric' => $numeric, '__high_risk' => (bool)($spec['high_risk'] ?? ($context === 'REGULATORY')),
        '__misconceptions' => array_values(array_map('strval', (array)($spec['misconceptions'] ?? []))), '__verification' => $numeric ? ['status' => 'RECOMPUTED', 'formula_family' => $formula, 'variable_pattern' => (string)($spec['variable_pattern'] ?? 'stated inputs and target decision'), 'target_variable' => (string)($spec['target_variable'] ?? 'design decision'), 'reasoning_steps' => substr_count((string)$spec['explanation'], ';') + 1, 'independent_check' => 'Recomputed from the stated formula, units, assumptions, substitution, rounding, and answer choice.'] : null,
    ];
};

$Q = static function (string $concept, int $depth, string $context, string $stem, string $answer, array $wrong, string $explanation, string $scenario, string $prerequisite = 'PREREQUISITE_FREE', bool $numeric = false, string $formula = 'qualitative-design-reasoning', string $target = 'design decision', bool $highRisk = false, array $misconceptions = [], ?string $material = null) use (&$add): void {
    // Authoring entries may carry a fourth review distractor; production MCQ
    // schema is four choices total, so retain the first three deterministic
    // distractors after the independently authored answer.
    if (count($wrong) === 4) $wrong = array_slice($wrong, 0, 3);
    // A question cannot require its own primary competency.  These entries
    // are intentionally treated as ordinary in-concept solving, not as a
    // fabricated prerequisite edge.
    if ($prerequisite === 'REQUIRED:' . $concept) $prerequisite = 'PREREQUISITE_FREE';
    // Ordinary arithmetic/unit handling is an assumed foundation unless the
    // question explicitly requires another represented competency.
    if ($numeric && $prerequisite === 'PREREQUISITE_FREE') $prerequisite = 'ASSUMED_FOUNDATION';
    $add(compact('concept', 'depth', 'context', 'stem', 'answer', 'wrong', 'explanation', 'scenario', 'prerequisite', 'numeric', 'formula', 'target', 'highRisk', 'misconceptions', 'material') + ['formula_family' => $formula, 'target_variable' => $target, 'high_risk' => $highRisk]);
};

$candidates = [];

// History and theory: 32 questions.  The cohort tests precedent operations,
// climate/culture, and conservation decisions rather than style-name recall.
$Q($cHistory, 3, 'NEUTRAL', 'A museum entrance must make a new public route legible without copying the historic facade. Which design move best transfers the precedent?', 'Align the new route with the historic approach hierarchy while expressing the intervention in compatible contemporary detail.', ['Repeat every historic ornament at a larger scale.', 'Hide the new entrance so visitors cannot distinguish the sequence.', 'Move the entrance to the least visible edge regardless of circulation.', 'Use symmetry alone without checking arrival, threshold, or program.'], 'The transferable precedent is the spatial hierarchy of approach and threshold, not literal ornament. A contemporary detail can remain compatible when the established sequence remains legible.', 'design decision', 'PREREQUISITE_FREE', false, 'precedent-spatial-operation', 'precedent operation', false, ['ornament mistaken for spatial order']);
$Q($cHistory, 3, 'NEUTRAL', 'A plan has a repeated bay module, but one bay contains the main hall and the others contain support rooms. Which concept explains the difference in emphasis?', 'Hierarchy within a repeated rhythm.', ['Random variation without an organizing system.', 'Uniformity that makes all spaces equivalent.', 'A material specification with no spatial consequence.', 'A site setback that determines interior use.'], 'Repetition supplies rhythm, while the larger hall establishes hierarchy by size, position, or access. The two ideas can operate together.', 'concept interpretation', 'PREREQUISITE_FREE', false, 'rhythm-and-hierarchy', 'spatial hierarchy', false, ['rhythm treated as equality']);
$Q($cHistory, 4, 'NEUTRAL', 'A design team analyzes a courtyard precedent before adapting it to a dense urban site. Which evidence is most important before deciding whether the courtyard operation transfers?', 'The relationship among climate, circulation, privacy, light, and the surrounding building mass.', ['Only the courtyard’s decorative paving pattern.', 'The historical period label without site or use information.', 'The exact original furniture layout.', 'The number of columns regardless of their structural or spatial role.'], 'A courtyard is an environmental and spatial relationship. Its usefulness depends on how enclosure, movement, light, privacy, and climate worked together in the precedent and the new site.', 'analysis of precedent', 'REQUIRED:architecture-spatial-integration', false, 'precedent-contextual-analysis', 'transferable operation', false, ['surface feature substituted for performance']);
$Q($cHistory, 3, 'NEUTRAL', 'Which observation is strongest evidence that an axis is functioning as an organizing device?', 'Approach, entry, and principal space align so movement and visual emphasis reinforce one another.', ['Every wall has the same thickness.', 'The building uses a single exterior color.', 'The furniture is arranged alphabetically.', 'A decorative motif appears on unrelated surfaces.'], 'An axis is demonstrated by relationships among approach, movement, and emphasis. Color or isolated decoration does not establish spatial order.', 'evidence interpretation', 'PREREQUISITE_FREE', false, 'axis-evidence', 'axis function', false, ['graphic feature mistaken for axis']);
$Q($cHistory, 3, 'NEUTRAL', 'A tropical vernacular building uses a raised floor, deep eaves, and permeable wall panels. Which combined environmental problem do these features most directly address?', 'Rain exposure, ground moisture, solar gain, and natural air movement.', ['Only acoustic isolation from all outdoor sound.', 'Snow drifting and freeze-thaw expansion.', 'A need to eliminate all daylight.', 'A requirement to make every room mechanically conditioned.'], 'The features work together against rainfall and ground moisture while shading and ventilating occupied space. They should be interpreted in their climate rather than copied universally.', 'climate interpretation', 'PREREQUISITE_FREE', false, 'vernacular-climate-response', 'combined climate response', false, ['single-feature reasoning']);
$Q($cHistory, 4, 'NEUTRAL', 'A historic settlement uses narrow shaded streets and inward-facing courtyards. A proposed hot-humid redevelopment replaces them with exposed wide plazas. What should the designer investigate first?', 'Whether the new geometry changes shade, air movement, thermal exposure, social use, and stormwater behavior.', ['Whether the new plazas use a fashionable paving color.', 'Whether a historical label can be assigned to the redevelopment.', 'Whether every courtyard can be removed without documenting use.', 'Whether a wider space is always more accessible.'], 'Settlement form is a combined environmental and social response. The redevelopment must test consequences for shade, ventilation, use, and water rather than equating openness with improvement.', 'site and settlement analysis', 'REQUIRED:architecture-spatial-integration', false, 'settlement-form-performance', 'settlement consequence', false, ['wide equals better']);
$Q($cHistory, 3, 'NEUTRAL', 'Which statement best distinguishes a vernacular adaptation from a decorative regional image?', 'The adaptation connects form and material practice to local climate, resources, labor, and social use.', ['The adaptation is defined only by a roof silhouette.', 'The image is valid whenever a local motif is painted on a new facade.', 'Both are identical because any regional reference is functional.', 'A vernacular response cannot change when users or climate data change.'], 'Vernacular reasoning concerns accumulated relationships among environment, material, construction, and culture. A motif alone does not establish that performance logic.', 'concept interpretation', 'PREREQUISITE_FREE', false, 'vernacular-versus-image', 'vernacular evidence', false, ['motif mistaken for adaptation']);
$Q($cHistory, 4, 'PROFESSIONAL', 'A historic school requires accessible entry, improved egress, and new services. Which first step best supports a defensible conservation design?', 'Document significance, existing fabric, condition, user needs, and regulatory constraints before comparing interventions.', ['Demolish the most visible wing before documenting it.', 'Choose the cheapest intervention before understanding significance.', 'Freeze the building even if access and safety are inadequate.', 'Select a contemporary style first and fit the evidence afterward.'], 'Documentation establishes what is significant, what is failing, and what the users and current requirements demand. It makes compatibility and trade-offs reviewable.', 'conservation decision', 'REQUIRED:architecture-professional-judgment', false, 'conservation-documentation', 'intervention basis', true, ['freeze-or-demolish false choice']);
$Q($cHistory, 4, 'PROFESSIONAL', 'A proposed addition touches a character-defining stair hall but the project record does not establish its significance. What is the most responsible next action?', 'Pause the irreversible detail and investigate the hall’s history, fabric, condition, and role before selecting the connection.', ['Proceed because the addition is visually modern.', 'Remove the hall so the new program is simpler.', 'Assume every historic space has equal significance.', 'Hide the connection inside the hall without recording it.'], 'An unresolved significance question controls the acceptability of an irreversible intervention. Research and documentation precede the design choice.', 'conservation decision', 'REQUIRED:architecture-professional-judgment', false, 'significance-before-intervention', 'irreversibility', true, ['modern equals compatible']);
$Q($cHistory, 3, 'NEUTRAL', 'A facade has a regular bay rhythm but one entrance bay is wider and more deeply recessed. What does the exception most likely do?', 'It marks the entrance as a hierarchical event within the overall rhythm.', ['It proves that the facade has no order.', 'It removes the need to understand circulation.', 'It turns every bay into an identical service zone.', 'It establishes a site drainage gradient.'], 'An intentional exception can reinforce hierarchy while preserving a larger rhythm. The entrance is read through the relationship between the repeated field and the emphasized bay.', 'precedent interpretation', 'PREREQUISITE_FREE', false, 'hierarchical-exception', 'entrance hierarchy', false, ['exception treated as disorder']);
$Q($cHistory, 3, 'NEUTRAL', 'A design uses a datum line to align window heads across rooms with different floor uses. What is the datum doing?', 'Providing a continuous reference that relates otherwise different elements.', ['Replacing all structural analysis.', 'Guaranteeing identical room functions.', 'Eliminating the need for a circulation path.', 'Serving only as a decorative color band.'], 'A datum is an ordering reference. It can coordinate elements without making their functions or structural roles identical.', 'concept interpretation', 'PREREQUISITE_FREE', false, 'datum-as-reference', 'datum function', false, ['datum confused with decoration']);
$Q($cHistory, 4, 'NEUTRAL', 'Two adaptive-reuse schemes retain the same facade. Scheme A preserves the original public-to-private sequence; Scheme B keeps the facade but reverses that sequence. Which judgment is better supported?', 'Scheme A retains more of the building’s spatial character even though both schemes preserve the facade.', ['Scheme B is automatically better because the facade is unchanged.', 'Both are equivalent because interiors never carry significance.', 'Scheme A fails because new uses cannot occupy old rooms.', 'Neither can be assessed without copying the historic finishes.'], 'Character can include spatial organization and movement, not only the exterior surface. Retaining the sequence is stronger evidence of compatible reuse.', 'adaptive reuse comparison', 'REQUIRED:architecture-spatial-integration', false, 'spatial-character-retention', 'character-defining organization', false, ['facade-only preservation']);
$Q($cHistory, 3, 'NEUTRAL', 'A climate-responsive precedent places service spaces on the hotter west edge and occupied rooms toward a shaded court. What principle is being used?', 'Program placement is helping buffer occupied spaces from a difficult solar exposure.', ['The west edge is chosen only for visual symmetry.', 'Service spaces have no environmental effect.', 'The court is irrelevant because climate never affects planning.', 'All rooms must receive identical solar exposure.'], 'Program zoning can be an environmental strategy. The buffer works only if the mass, openings, and actual climate support the stated relationship.', 'climate-responsive planning', 'PREREQUISITE_FREE', false, 'program-as-environmental-buffer', 'thermal zoning', false, ['zoning treated as only functional']);
$Q($cHistory, 4, 'NEUTRAL', 'A coastal settlement’s traditional roof is being considered for a new inland building with different rainfall and wind. Which approach is most defensible?', 'Retain the roof’s underlying water-shedding and assembly logic only after testing it against the inland climate and construction conditions.', ['Copy the roof exactly because tradition makes it universally correct.', 'Reject every traditional principle because the site is different.', 'Choose the roof solely from its silhouette.', 'Use the original material without checking availability or durability.'], 'Transfer requires performance and constructability evidence. A traditional principle may remain useful, but its dimensions, materials, and details must respond to the new conditions.', 'climate transfer', 'PREREQUISITE_FREE', false, 'traditional-form-transfer', 'climate adaptation', false, ['tradition as universal rule']);
$Q($cHistory, 3, 'NEUTRAL', 'A monument’s significance depends on its structural hall, entry sequence, and relationship to a public square. Which documentation set best captures that significance?', 'Measured drawings, photographs, condition notes, historical research, and a record of spatial and urban relationships.', ['Only a color palette and facade elevation.', 'Only the current owner’s preferred furniture plan.', 'A list of replacement products with no existing-condition record.', 'A new rendering that hides later alterations.'], 'Significance is physical, spatial, historical, and contextual. A mixed record permits later decisions to distinguish evidence from assumption.', 'documentation planning', 'PREREQUISITE_FREE', false, 'multi-layer-documentation', 'significance record', false, ['facade-only documentation']);
$Q($cHistory, 4, 'PROFESSIONAL', 'A client wants an adaptive-reuse lobby to look “original,” but the historic entry was altered and no reliable drawing survives. What should the architect recommend?', 'Preserve documented character, identify uncertainty, and make necessary new work compatible without inventing undocumented historic detail.', ['Fabricate an exact original entry from memory.', 'Erase all evidence of later changes.', 'Use unrelated ornament to make the lobby appear old.', 'Refuse any accessibility or life-safety improvement.'], 'Conservation decisions should be evidence-based. Compatible new work can support use while avoiding a false claim about undocumented fabric.', 'professional conservation judgment', 'REQUIRED:architecture-professional-judgment', false, 'undocumented-reconstruction', 'evidence and authenticity', true, ['false historical certainty']);
$Q($cHistory, 3, 'NEUTRAL', 'Which intervention best illustrates reversibility in an existing building?', 'A freestanding, independently supported partition that can be removed with limited damage to significant fabric.', ['Cutting away a character-defining stair to insert a fixed lift.', 'Embedding new anchors through a decorated historic wall.', 'Replacing all original windows before condition assessment.', 'Covering significant material permanently with unrecorded finishes.'], 'A freestanding partition can be removed while leaving the existing fabric substantially intact. Reversibility is a practical risk-control principle, not a guarantee of zero impact.', 'conservation strategy', 'PREREQUISITE_FREE', false, 'reversibility', 'reversible intervention', false, ['reversibility confused with invisibility']);
$Q($cHistory, 3, 'NEUTRAL', 'A historic courtyard is retained, but a new roof blocks its daylight and natural ventilation. What does this reveal?', 'Preserving a named feature is insufficient if the intervention destroys its environmental and spatial function.', ['Courtyards matter only as decorative voids.', 'Any roof is compatible because the courtyard still exists.', 'Environmental performance is unrelated to heritage.', 'The new roof is automatically reversible and therefore harmless.'], 'The courtyard’s significance can include light, air, movement, and social use. The intervention must be evaluated as a change to those relationships.', 'adaptive reuse diagnosis', 'REQUIRED:architecture-spatial-integration', false, 'feature-versus-function', 'courtyard performance', false, ['feature retained but function lost']);
$Q($cHistory, 3, 'NEUTRAL', 'Which analysis best supports identifying a character-defining element?', 'Relate the element to documented history, design intent, spatial experience, material evidence, and the building’s use.', ['Count how often the element appears in unrelated buildings.', 'Choose the most expensive element automatically.', 'Select whichever element is easiest to photograph.', 'Treat all later repairs as equally original.'], 'Character is a reasoned conclusion from historical and physical evidence, not a value assigned only by cost, visibility, or convenience.', 'conservation analysis', 'PREREQUISITE_FREE', false, 'character-defining-analysis', 'significance test', false, ['visibility as sole criterion']);
$Q($cHistory, 4, 'NEUTRAL', 'A new library references a historic arcade but the site has a different pedestrian edge and hotter afternoon sun. Which design process is strongest?', 'Extract the arcade’s spatial and climatic functions, then re-test them against the new edge, users, and solar conditions.', ['Copy the arcade dimensions without site analysis.', 'Use the arcade only as a facade appliqué.', 'Reject the reference because no precedent can transfer.', 'Optimize the image before checking shade and movement.'], 'Precedent becomes useful when its underlying operations are re-evaluated under new site and program conditions.', 'precedent synthesis', 'REQUIRED:architecture-spatial-integration', false, 'precedent-retesting', 'contextual transfer', false, ['literal copying']);
$Q($cHistory, 3, 'NEUTRAL', 'A settlement plan places a market at a shaded junction of several pedestrian routes. Which inference is most defensible?', 'The location may combine movement, exchange, climate relief, and public visibility; those relationships should be tested against evidence.', ['The market must be placed there only because the plan is symmetrical.', 'Shade proves that no social or access analysis is needed.', 'A junction has no effect on public use.', 'The plan can be understood from the market roof style alone.'], 'A public node often combines spatial, environmental, and social roles. The inference remains a hypothesis until routes, users, and climate evidence support it.', 'settlement reading', 'PREREQUISITE_FREE', false, 'public-node-multiple-roles', 'settlement node', false, ['single-cause interpretation']);
$Q($cHistory, 4, 'PROFESSIONAL', 'A conservation report contains conflicting dates for an addition, but the proposed work would remove its roof framing. What is the best response?', 'Resolve or explicitly bracket the uncertainty before an irreversible intervention and record the evidence supporting the decision.', ['Choose the older date because it sounds more historic.', 'Remove the framing and update the report afterward.', 'Ignore the conflict because the addition is not the main facade.', 'Use a generic historic detail to conceal the uncertainty.'], 'Conflicting evidence matters when it changes significance or treatment. The decision should be delayed or bounded until the uncertainty is responsibly handled.', 'professional evidence review', 'REQUIRED:architecture-professional-judgment', false, 'uncertainty-before-removal', 'irreversible work', true, ['uncertainty ignored']);
$Q($cHistory, 3, 'NEUTRAL', 'In a sequence of compressed and expanded rooms, the expanded room occurs at the end of the approach and receives the most light. What ordering effect is created?', 'Compression and release reinforce a spatial climax.', ['A purely random sequence with no experiential structure.', 'A uniform rhythm with no change in emphasis.', 'A structural calculation independent of movement.', 'A site boundary with no interior consequence.'], 'Changing scale and light along a route can create anticipation and release, making the final space a climax in the spatial sequence.', 'spatial sequence', 'PREREQUISITE_FREE', false, 'compression-release', 'spatial climax', false, ['sequence reduced to room count']);
$Q($cHistory, 3, 'NEUTRAL', 'A vernacular wall uses locally available material in a thick assembly with small openings. Which additional evidence is needed before calling it thermally appropriate?', 'The local temperature range, solar exposure, ventilation pattern, occupancy, and the wall’s actual heat and moisture behavior.', ['Only the material’s color.', 'A style label for the settlement.', 'The owner’s preferred furniture arrangement.', 'The fact that the wall is thick in photographs.'], 'Thickness and local material suggest a strategy but do not prove performance. Climate, exposure, operation, and moisture evidence complete the interpretation.', 'environmental evidence', 'PREREQUISITE_FREE', false, 'vernacular-performance-evidence', 'thermal appropriateness', false, ['visual thickness as proof']);
$Q($cHistory, 4, 'NEUTRAL', 'A reuse option preserves a historic theater volume but inserts a low ceiling that hides the original balcony relationship. Which concern is most important?', 'The insertion may remove a character-defining spatial relationship even though the outer shell remains.', ['Only the new ceiling color matters.', 'The shell guarantees all significance is retained.', 'A low ceiling always improves heritage value.', 'The balcony relationship cannot be significant because it is interior.'], 'The volume and visual relationship among stage, audience, balcony, and approach can be part of the theater’s character. Interior change requires the same evidence-based assessment.', 'interior heritage analysis', 'REQUIRED:architecture-spatial-integration', false, 'interior-spatial-significance', 'historic volume', false, ['shell-only preservation']);
$Q($cHistory, 3, 'NEUTRAL', 'Which statement best describes proportion in architectural analysis?', 'A relational comparison among dimensions that helps explain order, scale, and emphasis.', ['A guarantee that all dimensions are equal.', 'A decorative finish applied after planning.', 'A building code threshold by definition.', 'A synonym for structural safety.'], 'Proportion concerns relationships among dimensions and their perceptual or organizational effect. It does not by itself prove code compliance or structural capacity.', 'concept definition', 'PREREQUISITE_FREE', false, 'proportion-as-relation', 'proportion', false, ['proportion equated with equality']);
$Q($cHistory, 4, 'PROFESSIONAL', 'A historic civic building can gain a new service core either in a secondary wing or through the principal ceremonial hall. Which option is generally better supported by conservation reasoning?', 'Place the service core in the secondary wing if it satisfies access, safety, and technical requirements with less impact on significant space.', ['Always place services in the most significant room.', 'Choose solely by which option is closest to the property line.', 'Reject any new service because historic buildings cannot change.', 'Select the option with the most visible new equipment.'], 'The secondary wing is preferable when it reduces impact on character-defining space while still meeting performance and access needs. The judgment remains conditional on evidence and coordination.', 'adaptive reuse option comparison', 'REQUIRED:architecture-professional-judgment', false, 'secondary-space-servicing', 'service-core placement', true, ['historic change prohibited']);
$Q($cHistory, 3, 'NEUTRAL', 'A plan’s main circulation route bends around a planted court but remains visually connected to the entrance. What can the bend accomplish?', 'It can slow movement and frame the court while preserving orientation through visual connection.', ['It necessarily destroys all wayfinding.', 'It proves that the route is inaccessible.', 'It has no relationship to spatial experience.', 'It makes every adjacent room equally public.'], 'Circulation can be choreographed by compression, release, view, and pace. The route still needs independent accessibility and egress checks.', 'circulation interpretation', 'PREREQUISITE_FREE', false, 'bent-route-framing', 'movement and view', false, ['bend equated with disorientation']);
$Q($cHistory, 4, 'NEUTRAL', 'A climate tradition uses a shaded transitional porch between outdoors and an occupied room. Which design lesson is most transferable?', 'A thermal and social threshold can moderate exposure while supporting arrival and interaction.', ['A porch is useful only as a decorative frame.', 'The exact original column profile must be copied.', 'A threshold should be removed to maximize direct entry.', 'The porch eliminates the need to study local climate.'], 'The porch mediates climate, movement, and social transition. Its dimensions and details still need to be re-tested for the new site and users.', 'vernacular threshold', 'PREREQUISITE_FREE', false, 'threshold-mediation', 'transitional space', false, ['threshold reduced to ornament']);
$Q($cHistory, 3, 'NEUTRAL', 'A conservation team finds that a later infill wall is poorly built but separates a public route from a service yard. What should guide its treatment?', 'Its physical condition, historical significance, spatial role, and replacement consequences should be assessed together.', ['Remove it solely because it is later.', 'Retain it solely because it is old.', 'Replace it without checking the route or service function.', 'Judge it only by whether it appears in an early photograph.'], 'Age alone is not the treatment criterion. The wall’s evidence, current role, condition, and the consequences of change must be balanced.', 'conservation treatment', 'PREREQUISITE_FREE', false, 'later-fabric-balanced-assessment', 'treatment decision', false, ['age as sole criterion']);
$Q($cHistory, 4, 'PROFESSIONAL', 'A client asks for a “historic-looking” new wing that would obscure a documented public view to the original building. Which response is strongest?', 'Explain the view’s significance, test less harmful massing, and document the client decision if a conflict remains.', ['Accept the request because historic-looking work is always compatible.', 'Reject the project without explaining the affected significance.', 'Hide the view impact in the presentation drawings.', 'Copy the original wing exactly regardless of site capacity.'], 'The architect should communicate the significance and consequences, explore alternatives, and retain a traceable decision. Appearance alone does not resolve the conflict.', 'professional conservation communication', 'REQUIRED:architecture-professional-judgment', false, 'view-significance-conflict', 'public-interest communication', true, ['appearance over consequence']);
$Q($cHistory, 3, 'NEUTRAL', 'A building’s structure, circulation, daylight, and material expression all follow the same organizing grid. What does the grid provide?', 'A shared ordering system that coordinates multiple architectural layers.', ['Only a decorative pattern independent of use.', 'A guarantee that every room has the same function.', 'A substitute for climate analysis.', 'An automatic code approval.'], 'A grid can coordinate structure, movement, light, and expression when those relationships are actually present. It is not automatically functional merely because it is drawn.', 'integrated ordering', 'PREREQUISITE_FREE', false, 'multi-layer-grid', 'integrated order', false, ['grid as decoration']);
$Q($cHistory, 4, 'NEUTRAL', 'A proposed reconstruction is based on one undated photograph that omits the rear elevation. Which conclusion is most defensible?', 'The photograph supports limited visual evidence, but it cannot justify undocumented details or a complete reconstruction.', ['The photograph proves every original condition.', 'The missing rear elevation can be invented from the front.', 'The project should erase all later fabric.', 'The image is useless because it is incomplete.'], 'Partial evidence can inform a bounded decision, but uncertainty should remain visible and prevent false precision.', 'evidence limits', 'PREREQUISITE_FREE', false, 'partial-record-limits', 'documentation uncertainty', false, ['incomplete evidence overextended']);
$Q($cHistory, 3, 'NEUTRAL', 'Why can a material choice be historically meaningful beyond its visual color?', 'It can reveal local resources, craft, construction sequence, maintenance practice, and environmental response.', ['Materials matter only as surface decoration.', 'Color alone identifies every construction process.', 'Material history is unrelated to social use.', 'A material cannot be interpreted without a style label.'], 'Material carries technical, cultural, economic, and environmental evidence. Visual appearance is one part of that reading.', 'material interpretation', 'PREREQUISITE_FREE', false, 'material-as-evidence', 'material meaning', false, ['color-only material reading']);
$Q($cHistory, 4, 'PROFESSIONAL', 'An adaptive-reuse concept meets the client program but removes the only original accessible-to-public threshold. Which review question should come first?', 'Whether an alternative can meet the program while retaining or interpreting the threshold’s character and public role.', ['Whether the replacement threshold can be made visually fashionable.', 'Whether all public access can be moved to a service door.', 'Whether the threshold can be demolished before documentation.', 'Whether the client prefers a different historic style.'], 'The threshold may carry spatial, social, and heritage significance. A professional review should investigate alternatives before accepting its loss.', 'adaptive reuse judgment', 'REQUIRED:architecture-professional-judgment', false, 'public-threshold-retention', 'program versus significance', true, ['program treated as sole criterion']);
$Q($cHistory, 3, 'NEUTRAL', 'A plan places a low, shaded edge beside a noisy street and quieter rooms deeper in the block. Which reading is best supported?', 'The plan uses spatial depth and buffering to separate different environmental conditions.', ['The arrangement is random because rooms are not on one axis.', 'The noisy edge proves the inner rooms need no ventilation.', 'All spaces should face the street for equal exposure.', 'Noise has no relationship to zoning.'], 'Zoning can mediate noise, exposure, privacy, and access. The design still needs acoustic and ventilation checks, but the relationship is a defensible hypothesis.', 'environmental zoning', 'PREREQUISITE_FREE', false, 'noise-buffer-zoning', 'environmental buffer', false, ['single-axis planning']);
$Q($cHistory, 4, 'NEUTRAL', 'A new intervention preserves a historic wall but cuts through its base for an uncoordinated drain. What principle has been violated?', 'Significant fabric and the water-management consequences of the intervention were not coordinated.', ['The wall is preserved because most of it remains.', 'Drainage is unrelated to conservation.', 'Any new penetration is reversible by definition.', 'Historic fabric can be changed without recording it.'], 'Preservation includes physical performance and compatible detailing. An uncontrolled penetration can damage fabric even when the visible wall remains.', 'conservation and building performance', 'REQUIRED:architecture-technical-integration', false, 'historic-fabric-moisture', 'fabric and drainage', false, ['preservation as visual only']);
$Q($cHistory, 3, 'NEUTRAL', 'Which question most directly tests whether a precedent is being understood rather than copied?', 'Which spatial, environmental, or social relationship produced the precedent’s effect, and does the new project reproduce that relationship?', ['Which ornament can be duplicated most quickly?', 'Which image looks most similar from a distance?', 'Which historic label can be printed on the concept board?', 'Which detail can be added without changing the plan?'], 'Understanding asks what relationship generated the effect and whether it remains valid under new conditions. Similar appearance alone is not enough.', 'precedent evaluation', 'PREREQUISITE_FREE', false, 'precedent-understanding-test', 'underlying relationship', false, ['visual similarity as proof']);

// Planning and practice: 50 questions.  These emphasize scope, coordination,
// evidence, public responsibility, accessibility, and controlled change.
$Q($cPractice, 3, 'PROFESSIONAL', 'A client asks the architect to begin a service outside the agreed scope because “it will only take one sketch.” What is the best first action?', 'Clarify the requested service, its consequences, and the required authorization before performing it.', ['Perform it informally and document it only if a dispute occurs.', 'Assign it to any available person without checking competence.', 'Refuse every future service regardless of authorization.', 'Treat the request as approved because it came from the client.'], 'A small-looking task can change responsibility, fee, coordination, and risk. Scope and authorization should be clarified before action.', 'scope decision', 'PREREQUISITE_FREE', false, 'scope-authorization', 'scope clarification', false, ['client request equals authorization']);
$Q($cPractice, 4, 'PROFESSIONAL', 'A consultant’s recommendation conflicts with an architectural access route shown in the current plan. Which coordination response is strongest?', 'Record the conflict, verify the current information, bring the responsible disciplines together, and issue an authorized resolution.', ['Move the access route silently to match the recommendation.', 'Follow whichever drawing was opened first.', 'Ask the contractor to choose in the field without a record.', 'Delete the consultant’s note from the project file.'], 'The conflict involves current information, accessibility, responsibility, and downstream work. Controlled coordination is safer than an undocumented unilateral change.', 'consultant coordination', 'REQUIRED:architecture-technical-integration', false, 'coordination-conflict', 'interface resolution', true, ['first-document rule']);
$Q($cPractice, 3, 'REGULATORY', 'A proposed accessible route is shown on a concept plan, but the current project dimensions and the applicable BP 344 version are not identified. What should the architect do?', 'Confirm the current applicable requirement and verify the route dimensions before treating the concept as compliant.', ['Declare compliance because an arrow indicates movement.', 'Use a remembered dimension from an unrelated project.', 'Delete the route so no compliance question remains.', 'Assume the newest online image is the governing approval.'], 'Accessibility is a regulatory design constraint. The route must be checked against the current applicable official requirement and project information, not a symbol or memory.', 'regulatory verification', 'REQUIRED:architecture-spatial-integration', false, 'regulatory-version-check', 'accessibility verification', true, ['diagram equals compliance']);
$Q($cPractice, 4, 'PROFESSIONAL', 'During design development, the owner changes the lobby program and the change affects structure, fire separation, utilities, and cost. What is the most defensible workflow?', 'Document the changed brief, coordinate affected disciplines, evaluate consequences, obtain authorization, and update the controlled documents.', ['Revise only the lobby plan and let other disciplines discover the change.', 'Proceed with construction and resolve the consequences later.', 'Accept the change verbally because the owner requested it.', 'Freeze all design work without evaluating alternatives.'], 'A material program change propagates across disciplines. A traceable change process protects intent, safety, cost, schedule, and responsibility.', 'change control', 'REQUIRED:architecture-technical-integration', false, 'program-change-propagation', 'controlled change', true, ['single-sheet revision']);
$Q($cPractice, 3, 'PROFESSIONAL', 'Which item is most useful in a decision record for a disputed design assumption?', 'The assumption, supporting evidence, alternatives considered, responsible parties, consequence, and authorization status.', ['Only the final preferred sketch.', 'Only the date the dispute was noticed.', 'A statement that the team “agreed” without naming the issue.', 'A screenshot with no source or project context.'], 'A record must allow a later reviewer to reconstruct the reasoning and authority. A conclusion without assumptions and consequences is not traceable.', 'decision record', 'PREREQUISITE_FREE', false, 'decision-record-fields', 'traceability', false, ['conclusion without evidence']);
$Q($cPractice, 4, 'PROFESSIONAL', 'A project schedule pressures the architect to approve a shop drawing that changes a fire-rated wall assembly but omits test information. What is the best response?', 'Withhold approval of the unresolved change, identify the required evidence, and coordinate the impact before authorization.', ['Approve it to protect the schedule.', 'Assume any thicker material has the same tested rating.', 'Ask the installer to conceal the change.', 'Treat the shop drawing as a code approval.'], 'A fire-rated assembly is a high-risk interface. Missing evidence prevents a defensible approval, and schedule pressure does not replace technical or regulatory verification.', 'submittal review', 'REQUIRED:architecture-technical-integration', false, 'unverified-rated-assembly', 'fire-rated change', true, ['thickness equals rating']);
$Q($cPractice, 3, 'PROFESSIONAL', 'A client asks that a known drainage conflict be omitted from the meeting minutes until a preferred solution is found. What should the architect do?', 'Record the material conflict and its current uncertainty while distinguishing proposed options from an approved resolution.', ['Omit it to preserve confidence.', 'Record only the preferred option as a fact.', 'Blame the plumbing consultant without checking the plans.', 'Wait until construction to reveal the conflict.'], 'A material unresolved conflict must remain visible so responsible parties can evaluate it. Recording uncertainty is not the same as declaring failure.', 'professional communication', 'PREREQUISITE_FREE', false, 'transparent-risk-record', 'risk communication', true, ['omission as risk control']);
$Q($cPractice, 4, 'REGULATORY', 'An owner proposes reducing a circulation route because the furniture layout appears to fit. Which question must control the next review?', 'Whether the current applicable accessibility, egress, and operational requirements remain satisfied after the reduction.', ['Whether the route still looks wide in a rendering.', 'Whether the furniture can be moved after approval.', 'Whether the contractor prefers the shorter route.', 'Whether the room label remains unchanged.'], 'A circulation reduction can affect regulated access and life safety. The proposal must be tested against current requirements and actual operation.', 'regulatory design review', 'REQUIRED:architecture-spatial-integration', false, 'access-egress-reduction', 'route compliance', true, ['furniture fit as compliance']);
$Q($cPractice, 3, 'PROFESSIONAL', 'A specialist engineer gives a structural concept that conflicts with the client’s desired open plan. What is the architect’s best role?', 'Clarify the performance need, coordinate alternatives with the engineer, and explain spatial, cost, schedule, and risk consequences to the client.', ['Redesign the structural system independently.', 'Reject the engineer without testing alternatives.', 'Choose the largest beam because it is visibly safe.', 'Hide the conflict until permit submission.'], 'Architectural responsibility includes integrating the spatial brief with specialist input and communicating trade-offs, not practicing outside competence or concealing a conflict.', 'interdisciplinary judgment', 'REQUIRED:architecture-technical-integration', false, 'open-plan-structure-tradeoff', 'specialist coordination', true, ['uncoordinated redesign']);
$Q($cPractice, 3, 'PROFESSIONAL', 'A project record contains two different “current” ceiling plans. Which action best protects downstream coordination?', 'Identify the controlled revision, reconcile affected disciplines, and clearly supersede or retain the other record.', ['Use the plan with the newest file name.', 'Send both plans and let trades decide.', 'Delete one without recording the reason.', 'Choose the plan with the more attractive reflected ceiling.'], 'Version control requires a verified status and an explicit effect on related information. File names and appearance are weak evidence.', 'document control', 'PREREQUISITE_FREE', false, 'revision-control', 'information status', false, ['file name as revision status']);
$Q($cPractice, 4, 'PROFESSIONAL', 'A proposed value-engineering change replaces a durable facade material with a cheaper one but increases maintenance access and moisture risk. Which evaluation is appropriate?', 'Compare first cost, life-cycle maintenance, enclosure performance, constructability, appearance, and risk before recommending the change.', ['Approve it because first cost is the only objective.', 'Reject all substitutions regardless of performance.', 'Compare only the supplier’s unit price.', 'Ignore maintenance because it occurs after completion.'], 'Value engineering is a system decision. A lower initial price can be a worse value when it raises maintenance, moisture, or replacement risk.', 'value engineering', 'REQUIRED:architecture-technical-integration', false, 'first-cost-only', 'life-cycle comparison', true, ['unit price as value']);
$Q($cPractice, 3, 'PROFESSIONAL', 'A client supplies an incomplete site survey and asks for a final grading decision. What should the architect communicate?', 'Identify the missing information, state the decision limits, and request verification before finalizing work that depends on it.', ['Infer contours from the site photograph.', 'Issue a final grade and label it approximate only in private notes.', 'Treat the incomplete survey as sufficient because the site is small.', 'Avoid mentioning uncertainty to keep the schedule.'], 'A final decision based on missing survey data can create drainage, access, and construction risk. Clear limits and a verification request are professional controls.', 'information sufficiency', 'REQUIRED:architecture-spatial-integration', false, 'incomplete-survey', 'site evidence', true, ['photograph substitutes for survey']);
$Q($cPractice, 3, 'REGULATORY', 'A permit reviewer asks which current regulation supports an accessibility detail, but the project team cites an older summary page. What is the best response?', 'Trace the requirement to the current official source and version, then revise the detail if the applicable rule differs.', ['Cite the summary because its wording is familiar.', 'Use a code number remembered from a prior project.', 'Avoid answering by removing the accessible feature.', 'Treat the reviewer’s question as a design preference.'], 'Regulatory content is version-sensitive. A current official source and applicability check are necessary before defending or revising the detail.', 'regulatory source verification', 'REQUIRED:architecture-spatial-integration', false, 'stale-regulation', 'current-source check', true, ['summary treated as current']);
$Q($cPractice, 4, 'PROFESSIONAL', 'A contractor proposes moving a vertical shaft into a tenant room to avoid a beam. Which response best reflects architectural coordination?', 'Check program, fire and acoustic separation, access, maintenance, structure, services, and approvals before evaluating the relocation.', ['Accept the move because the shaft footprint is unchanged.', 'Move it on the architectural plan only.', 'Reject every shaft relocation without examining consequences.', 'Leave the decision to the tenant after rough-in.'], 'A shaft is an integrated spatial and technical element. Its relocation changes multiple performance and responsibility relationships.', 'utility coordination', 'REQUIRED:architecture-technical-integration', false, 'shaft-relocation', 'integrated impact review', true, ['footprint-only reasoning']);
$Q($cPractice, 3, 'PROFESSIONAL', 'Which action best demonstrates impartial professional judgment when a supplier offers an incentive tied to a product recommendation?', 'Disclose the potential conflict and base the recommendation on documented project performance and client interests.', ['Accept it if the product is attractive.', 'Hide the incentive and use the supplier’s literature as the only evidence.', 'Reject all supplier information automatically.', 'Recommend the product first and document the conflict later.'], 'Impartiality requires disclosure and evidence-based evaluation. Supplier information can be considered, but the recommendation cannot be concealed or self-serving.', 'ethical judgment', 'PREREQUISITE_FREE', false, 'conflict-disclosure', 'impartial recommendation', true, ['supplier incentive hidden']);
$Q($cPractice, 4, 'PROFESSIONAL', 'A community project has a tight budget and an unverified fire-safety concern. Which priority is most defensible?', 'Resolve the life-safety concern with qualified input before optimizing noncritical finishes or accepting budget reductions.', ['Prioritize finishes because they are visible to donors.', 'Defer the concern until after occupancy.', 'Choose the cheapest assembly without checking performance.', 'Treat the concern as a communication issue only.'], 'Life safety is a material public-interest obligation. Budget decisions should follow a defensible safety resolution, not conceal the risk.', 'public-interest prioritization', 'REQUIRED:architecture-technical-integration', false, 'safety-before-finish', 'life-safety priority', true, ['visibility over safety']);
$Q($cPractice, 3, 'PROFESSIONAL', 'An architect receives a field instruction request that changes a door location but lacks a current plan reference. What should be checked before responding?', 'The existing condition, current documents, responsible designer, affected systems, and authorization path.', ['Only the requested door swing.', 'Only whether the change is easy to draw.', 'Whether a similar door exists elsewhere.', 'Whether the request was typed in capital letters.'], 'A door move can affect access, egress, structure, utilities, fire separation, and wayfinding. The request needs context and authorization.', 'field instruction', 'REQUIRED:architecture-technical-integration', false, 'field-request-context', 'field change review', true, ['local geometry only']);
$Q($cPractice, 4, 'PROFESSIONAL', 'A design team discovers that a proposed equipment room has no route for replacement of the largest component. Which judgment is strongest?', 'Treat equipment replacement and maintenance access as part of the room’s functional performance and revise the layout or strategy.', ['Ignore it because the equipment fits on day one.', 'Assume it can be dismantled without checking the specification.', 'Reduce the access route to gain floor area.', 'Hide the issue in the operations manual.'], 'Maintainability is a life-cycle requirement. A room that cannot receive or service its equipment is not functionally complete.', 'maintainability review', 'REQUIRED:architecture-technical-integration', false, 'equipment-replacement-path', 'service access', false, ['day-one fit']);
$Q($cPractice, 3, 'NEUTRAL', 'Which distinction is most useful when reviewing a concept diagram?', 'A diagram can communicate a relationship or hypothesis without proving final dimensions, code compliance, or constructability.', ['Every concept bubble is already a construction document.', 'A diagram is useless until every fastener is shown.', 'Concept diagrams automatically satisfy accessibility.', 'A diagram’s graphic quality proves the design works.'], 'Concept diagrams are powerful for relationships but have limits. The reviewer must identify what evidence is still required before implementation.', 'representation limits', 'PREREQUISITE_FREE', false, 'diagram-evidence-boundary', 'concept representation', false, ['diagram equals final design']);
$Q($cPractice, 4, 'PROFESSIONAL', 'A client’s preferred layout conflicts with the project’s documented accessibility goals. How should the architect frame the discussion?', 'Explain the conflict, affected users, governing requirements, alternatives, and consequences before seeking an informed decision.', ['Treat accessibility as optional decoration.', 'Hide the conflict by changing the project goals.', 'Use a generic moral statement without testing alternatives.', 'Accept the preference because the client funds the project.'], 'Professional judgment makes the users, requirements, and consequences explicit. The architect should seek a lawful, informed path rather than conceal the conflict.', 'accessibility communication', 'REQUIRED:architecture-spatial-integration', false, 'accessibility-goal-conflict', 'informed decision', true, ['client preference overrides users']);
$Q($cPractice, 3, 'REGULATORY', 'A proposed assembly is described as “fire safe” in a marketing sheet but no tested or official basis is supplied. What conclusion is justified?', 'The claim is insufficient; the applicable official requirement and verified assembly evidence must be identified.', ['The assembly is compliant because the adjective is strong.', 'The material is compliant if it is noncombustible-looking.', 'The claim can replace a fire-resistance evaluation.', 'A contractor’s confidence is equivalent to certification.'], 'Regulatory and life-safety decisions require traceable evidence. Marketing language alone does not establish the required performance.', 'fire evidence review', 'REQUIRED:architecture-technical-integration', false, 'marketing-claim-as-proof', 'rated assembly evidence', true, ['marketing claim']);
$Q($cPractice, 4, 'PROFESSIONAL', 'A project manager asks the architect to approve an unresolved clash verbally so the team can “keep moving.” What is the best answer?', 'State that the clash needs a documented resolution with affected disciplines and authorization before approval.', ['Approve verbally and reconstruct the decision later.', 'Let the trade with the earliest start date decide.', 'Ignore it because clashes are normal.', 'Remove the conflicting element from the coordination model.'], 'The production path needs a controlled decision, especially when the clash affects safety, cost, or responsibility. Speed does not make an undocumented approval defensible.', 'coordination governance', 'REQUIRED:architecture-technical-integration', false, 'verbal-approval', 'clash resolution', true, ['speed over traceability']);
$Q($cPractice, 3, 'PROFESSIONAL', 'A specialist asks the architect to sign a calculation outside the architect’s demonstrated competence. What should the architect do?', 'Decline to certify the calculation, obtain appropriate qualified review, and coordinate the architectural consequences.', ['Sign it because the project needs a fast answer.', 'Copy a similar calculation from another project.', 'Change the title block and sign as coordinator.', 'Ignore the calculation and proceed with the layout.'], 'Competence and responsibility boundaries require qualified authorship and review. Coordination does not convert an unfamiliar calculation into the architect’s competent certification.', 'competence boundary', 'PREREQUISITE_FREE', false, 'unqualified-certification', 'professional competence', true, ['coordination equals certification']);
$Q($cPractice, 4, 'REGULATORY', 'A proposed exit route is visually direct but passes through a locked tenant-controlled space during likely emergency use. What should the review conclude?', 'The route is not established as a reliable egress path until access control, occupants, and the applicable life-safety requirements are resolved.', ['It is acceptable because the geometric distance is short.', 'It is acceptable if the tenant promises to unlock it.', 'It is not an issue because emergency routes need no signs.', 'It is automatically compliant because it is indoors.'], 'Egress is an operational and regulatory system, not only a line on plan. Reliability under emergency conditions must be verified.', 'life-safety review', 'REQUIRED:architecture-spatial-integration', false, 'egress-access-control', 'egress reliability', true, ['distance-only egress']);
$Q($cPractice, 3, 'PROFESSIONAL', 'Which change-control record best distinguishes a client preference from an approved project change?', 'It identifies the request, affected documents, cost/schedule/performance effects, responsible review, and approval status.', ['A text message saying “looks good.”', 'A revised rendering with no revision cloud or note.', 'A verbal comment repeated by a subcontractor.', 'A file saved under a new name with no comparison.'], 'Approval is traceable when the request, consequences, controlled information, and authority are visible. Appearance or informal repetition is not enough.', 'change documentation', 'PREREQUISITE_FREE', false, 'approved-change-record', 'approval traceability', false, ['informal approval']);
$Q($cPractice, 4, 'PROFESSIONAL', 'A consultant’s system reduces energy use but creates a condensate discharge through a historic interior. What is the strongest architectural response?', 'Coordinate the environmental benefit with drainage, fabric protection, maintenance, and reversible routing before selecting the system.', ['Accept it because energy savings outweigh all other effects.', 'Reject the system without evaluating another condensate path.', 'Discharge into the historic wall cavity.', 'Hide the discharge in a finish layer without access.'], 'A system benefit does not remove the need to coordinate moisture, fabric, access, and maintenance. The best answer integrates the competing requirements.', 'historic systems coordination', 'REQUIRED:architecture-technical-integration', false, 'condensate-and-fabric', 'integrated retrofit', true, ['single-benefit optimization']);
$Q($cPractice, 3, 'NEUTRAL', 'What is the most useful purpose of an assumptions register?', 'To make uncertain inputs visible, assign responsibility for verification, and prevent them from silently becoming design facts.', ['To replace all surveys and investigations.', 'To justify every preferred option automatically.', 'To keep assumptions confidential from the client.', 'To prove that a design is already compliant.'], 'An assumptions register manages uncertainty. It does not replace evidence or convert an assumption into a verified requirement.', 'risk management', 'PREREQUISITE_FREE', false, 'assumptions-register', 'uncertainty management', false, ['assumption as fact']);
$Q($cPractice, 4, 'REGULATORY', 'A renovation team wants to retain an existing ramp but has no record of its current slope, landings, handrails, or surface condition. What is the proper conclusion?', 'The ramp cannot be treated as compliant until the existing conditions are measured and checked against the current applicable accessibility requirements.', ['Retention proves compliance.', 'A ramp is accessible regardless of slope or landings.', 'Only the finish color needs verification.', 'A photograph replaces measurement.'], 'Existing construction must be verified against the current applicable rules and actual condition. A label such as “ramp” is not enough.', 'accessibility existing-condition review', 'REQUIRED:architecture-spatial-integration', false, 'existing-ramp-verification', 'existing accessibility', true, ['feature name as compliance']);
$Q($cPractice, 3, 'PROFESSIONAL', 'A design review identifies a high-risk unresolved interface but the meeting agenda has no responsible owner. What should happen next?', 'Assign responsibility, define the evidence and decision deadline, record the risk, and track closure through the controlled process.', ['Leave it in general discussion until someone notices.', 'Close it as “noted” without an owner.', 'Assign it to the newest team member without context.', 'Remove it from the risk register to simplify reporting.'], 'A risk without ownership is unlikely to close. The action must be traceable to evidence, responsibility, and a deadline.', 'risk coordination', 'PREREQUISITE_FREE', false, 'unowned-interface-risk', 'risk ownership', false, ['noted equals managed']);
$Q($cPractice, 4, 'PROFESSIONAL', 'A client asks for a durable material substitution after bidding, but the substitution changes the approved appearance and maintenance plan. What should be evaluated?', 'The substitution’s design intent, contract/document effect, performance, maintenance, cost, schedule, and approval path.', ['Only whether the supplier has stock.', 'Only the material sample color.', 'Nothing because substitutions are always minor.', 'Only whether the contractor can install it quickly.'], 'A post-bid substitution can affect several project obligations. It must be reviewed as a controlled change rather than an informal procurement choice.', 'material substitution', 'REQUIRED:architecture-technical-integration', false, 'post-bid-substitution', 'substitution review', true, ['procurement-only review']);
$Q($cPractice, 3, 'PROFESSIONAL', 'Which communication best describes a design limitation to a client?', 'State what is known, what is uncertain, why the limit matters, what additional evidence is needed, and what decisions remain open.', ['Use technical jargon without naming the consequence.', 'Hide uncertainty until the client asks a precise question.', 'State a definite answer from an unverified assumption.', 'Transfer the issue to the contractor without explanation.'], 'Useful communication connects evidence and uncertainty to decisions. It neither overwhelms the client with jargon nor creates false certainty.', 'client communication', 'PREREQUISITE_FREE', false, 'limitation-communication', 'risk explanation', false, ['false certainty']);
$Q($cPractice, 4, 'REGULATORY', 'A project brief uses a generic phrase “accessible toilet” but provides no user group, current requirement, room layout, or fixture information. What is the right design move?', 'Clarify the applicable users and requirements, then test a complete usable layout rather than relying on the room label.', ['Use the smallest room that fits a fixture symbol.', 'Assume the phrase means every requirement is satisfied.', 'Copy a plan from a different jurisdiction.', 'Remove the room label and proceed.'], 'Accessibility depends on a usable route, space, fixtures, clearances, and current requirements. A label does not substitute for a coordinated layout.', 'accessible facility programming', 'REQUIRED:architecture-spatial-integration', false, 'label-as-accessibility', 'usable facility', true, ['symbolic compliance']);
$Q($cPractice, 3, 'PROFESSIONAL', 'A design team disagrees about whether a field condition is a defect or an approved deviation. What evidence should resolve the issue first?', 'The current controlled documents, approved submittals, field records, and documented change decisions.', ['The loudest person’s recollection.', 'The oldest drawing in the file.', 'A new sketch made after the dispute.', 'A supplier’s marketing photograph.'], 'Status depends on the project record. Controlled information and approved changes provide stronger evidence than memory or a newly created sketch.', 'field record review', 'PREREQUISITE_FREE', false, 'field-status-evidence', 'record reconciliation', false, ['memory as record']);
$Q($cPractice, 4, 'PROFESSIONAL', 'A contractor requests an architect’s interpretation of an ambiguous detail that affects water entry, but the detail’s adjacent layers are not shown. What should the architect do?', 'Request the missing interface information, inspect the likely water path, and issue a coordinated interpretation or revision.', ['Interpret the detail from the visible finish only.', 'Choose the cheapest sealant and close the issue.', 'Ask the installer to guarantee the result without documentation.', 'Ignore the ambiguity because the detail is small.'], 'Water performance depends on continuous layers and interfaces. Missing adjacent information prevents a reliable interpretation.', 'enclosure interpretation', 'REQUIRED:architecture-technical-integration', false, 'incomplete-enclosure-detail', 'water-control interface', true, ['finish-only reasoning']);
$Q($cPractice, 3, 'NEUTRAL', 'What makes a project criterion useful for comparing two design alternatives?', 'It is stated before selection, relates to the brief or evidence, and can be traced to consequences of each option.', ['It changes after the preferred option is chosen.', 'It is based only on which image looks better.', 'It is kept implicit so the review stays flexible.', 'It rewards the option with more features regardless of need.'], 'A criterion makes comparison explicit and reviewable. Changing it after selection creates confirmation bias.', 'alternative evaluation', 'PREREQUISITE_FREE', false, 'criterion-before-choice', 'decision criterion', false, ['post hoc criterion']);
$Q($cPractice, 4, 'PROFESSIONAL', 'A proposed public space is technically accessible but has a steeply exposed approach with no shade or rest opportunity. Which judgment is strongest?', 'Review usability and dignity in operation, not only the existence of a nominal accessible route.', ['Declare success because the route is drawn.', 'Remove all shade to preserve the view.', 'Assume every user has the same stamina.', 'Treat comfort as unrelated to access.'], 'Accessibility is experienced through the whole route and environment. Usability, rest, exposure, and dignity can materially affect whether the route works.', 'inclusive design judgment', 'REQUIRED:architecture-spatial-integration', false, 'nominal-route-only', 'route usability', true, ['route existence as full access']);
$Q($cPractice, 3, 'PROFESSIONAL', 'A client wants a visually minimal roof edge, but the proposed detail eliminates the flashing and drainage continuity shown in the enclosure strategy. What should control?', 'The roof edge must preserve the required water-management and maintenance performance; appearance can be refined within that boundary.', ['The minimalist image always controls.', 'Flashing can be omitted if sealant is added.', 'The detail can be left unresolved until leaks occur.', 'Maintenance access is irrelevant at the roof edge.'], 'Aesthetic intent is important but cannot erase a demonstrated control layer. The design should seek a compatible expression of the water and maintenance requirements.', 'design intent versus performance', 'REQUIRED:architecture-technical-integration', false, 'minimal-edge-water-control', 'roof-edge decision', true, ['sealant as substitute for drainage']);
$Q($cPractice, 4, 'PROFESSIONAL', 'A project team receives a late request to conceal a known egress conflict from a public presentation. What is the proper professional response?', 'Do not misrepresent the design; disclose the unresolved conflict internally and resolve or clearly qualify it before presentation.', ['Conceal it because the presentation is preliminary.', 'Move the exit symbol temporarily.', 'Present the conflict as solved without evidence.', 'Delete the route and let users discover the change.'], 'A preliminary presentation must not create a materially false impression about life safety. The conflict should be documented and resolved or explicitly qualified.', 'public-interest communication', 'REQUIRED:architecture-spatial-integration', false, 'concealed-egress-conflict', 'honest representation', true, ['preliminary equals exempt']);
$Q($cPractice, 3, 'PROFESSIONAL', 'Which action best protects coordination when a structural opening is added after utilities have been routed?', 'Update the coordinated model/documents, check affected services and fire/acoustic conditions, and issue the controlled change.', ['Cut the opening in the nearest clear bay.', 'Move utilities in the field without checking systems.', 'Leave the documents unchanged because the opening is structural.', 'Ask each trade to solve its own portion independently.'], 'An opening is an interface event. Its effects propagate to structure, utilities, enclosure, fire, acoustics, and records.', 'opening coordination', 'REQUIRED:architecture-technical-integration', false, 'late-opening-propagation', 'interface update', true, ['discipline silo']);
$Q($cPractice, 4, 'REGULATORY', 'A proposed assembly meets a project’s aesthetic brief but conflicts with the current fire-separation strategy. Which priority is justified?', 'Resolve the current life-safety requirement first, then seek an aesthetic alternative that preserves the required performance.', ['Keep the appearance and omit the separation.', 'Treat the aesthetic brief as a waiver.', 'Assume the fire strategy can be changed by a rendering.', 'Ask occupants to accept the risk.'], 'Current life-safety requirements are not optional design decoration. A compliant alternative can be developed after the performance boundary is clear.', 'fire separation decision', 'REQUIRED:architecture-technical-integration', false, 'aesthetic-over-life-safety', 'life-safety priority', true, ['appearance as waiver']);
$Q($cPractice, 3, 'NEUTRAL', 'A design option adds a feature that is not in the brief and creates additional maintenance. What should the review ask?', 'Whether the feature provides a documented project benefit that justifies its cost, risk, and life-cycle obligation.', ['Whether it makes the presentation board busier.', 'Whether it can be drawn in a brighter color.', 'Whether extra maintenance is always acceptable.', 'Whether the feature is fashionable in another project.'], 'Unrequested complexity should be justified by performance or user value, not by image. Maintenance is part of the design consequence.', 'brief alignment', 'PREREQUISITE_FREE', false, 'unrequested-complexity', 'design value', false, ['feature count as quality']);
$Q($cPractice, 4, 'PROFESSIONAL', 'A client asks the architect to certify that construction matches the design, but the architect has not inspected concealed work. What is the defensible response?', 'State the limits of the observation and certify only what the available records and inspection support.', ['Certify everything because the visible work looks complete.', 'Sign and rely on the contractor’s verbal assurance.', 'Refuse to review any visible work.', 'Use a standard certificate without qualifying the scope.'], 'Certification must match evidence and scope. Concealed work not observed or documented cannot be represented as personally verified without a proper basis.', 'certification boundary', 'PREREQUISITE_FREE', false, 'concealed-work-certification', 'evidence-limited certification', true, ['visible work proves concealed work']);
$Q($cPractice, 3, 'PROFESSIONAL', 'A project has a recurring coordination meeting but no agenda or action log. What improvement gives the meeting the greatest control value?', 'Track decisions, responsible parties, due dates, affected documents, and unresolved risks in a controlled record.', ['Increase the number of attendees only.', 'Replace the meeting with informal messages.', 'Discuss only completed work.', 'Avoid recording disagreements.'], 'Coordination becomes actionable when decisions and open items have ownership and follow-up. Attendance alone does not close interfaces.', 'meeting control', 'PREREQUISITE_FREE', false, 'coordination-action-log', 'action tracking', false, ['attendance as control']);
$Q($cPractice, 4, 'PROFESSIONAL', 'A proposed accessible entrance uses a lift that reaches the lobby but has no clear maintenance or emergency access strategy. What is the appropriate conclusion?', 'The access solution requires operational, maintenance, emergency, and regulatory review before it can be accepted as usable.', ['Accept it because the lift reaches the level.', 'Reject all lifts as inaccessible.', 'Hide the maintenance route from the plan.', 'Assume emergency access will be improvised.'], 'A usable access system includes operation, maintenance, emergency response, and applicable requirements—not only vertical reach.', 'accessible-system review', 'REQUIRED:architecture-technical-integration', false, 'lift-operation-incomplete', 'access system', true, ['reach equals usability']);
$Q($cPractice, 3, 'PROFESSIONAL', 'What is the best way to handle a client decision that is authorized but based on a stated cost assumption that has not yet been verified?', 'Record the authorization together with the assumption, its verification owner, and the consequence if it changes.', ['Record only the authorization.', 'Hide the assumption so the decision looks final.', 'Treat the estimate as a guaranteed cost.', 'Reject the decision until every uncertainty is eliminated.'], 'Decisions can proceed conditionally when the uncertainty and follow-up are explicit. That preserves informed authorization without pretending the assumption is fact.', 'conditional decision', 'PREREQUISITE_FREE', false, 'conditional-authorization', 'assumption tracking', false, ['authorization erases uncertainty']);
$Q($cPractice, 4, 'REGULATORY', 'A building plan places an accessible route through a room that may be locked after hours. Which design review is necessary?', 'Test the route under the actual operating schedule and access-control condition against the current accessibility and life-safety requirements.', ['Check only the route width during business hours.', 'Assume a security policy can override accessibility.', 'Remove the route from the plan.', 'Use a sign telling users to ask for help.'], 'A route must remain usable under the conditions when it is required. Access control and operation can materially defeat a geometrically adequate route.', 'operational accessibility', 'REQUIRED:architecture-spatial-integration', false, 'locked-route', 'access operation', true, ['nominal route']);
$Q($cPractice, 3, 'PROFESSIONAL', 'A consultant drawing uses a different project datum from the architectural drawing. What should happen before dimensions are coordinated?', 'Confirm the datums, establish a common reference, and identify any dimensions already affected.', ['Average the two datums.', 'Use the consultant’s datum only because it is technical.', 'Ignore the difference if the drawings look aligned.', 'Correct the title blocks without checking geometry.'], 'A datum mismatch can propagate through levels, utilities, structure, and site work. It must be resolved as a coordination issue, not a graphic edit.', 'datum coordination', 'REQUIRED:architecture-technical-integration', false, 'inconsistent-datum', 'common reference', true, ['graphic alignment']);
$Q($cPractice, 4, 'PROFESSIONAL', 'A team’s risk register labels a flood-sensitive basement as “low” because no flood has occurred during the last year. What is the better assessment?', 'Use site evidence, hazard information, drainage, exposure, consequence, and uncertainty rather than one short observation period.', ['Keep low risk because recent history proves safety.', 'Raise it automatically to the highest risk without evidence.', 'Remove the basement from the risk register.', 'Use the client’s preferred risk label.'], 'Risk is probability and consequence under relevant evidence and uncertainty. One year without an event does not establish negligible exposure.', 'site risk assessment', 'REQUIRED:architecture-spatial-integration', false, 'short-history-risk', 'hazard assessment', true, ['recent absence as proof']);
$Q($cPractice, 3, 'PROFESSIONAL', 'Which project record best supports later explanation of why a design alternative was rejected?', 'A dated comparison showing the criteria, evidence, trade-offs, decision authority, and unresolved assumptions.', ['A final rendering with no alternatives.', 'A verbal recollection from one participant.', 'A cost number without design consequences.', 'A list of all ideas with no evaluation.'], 'The record must show how the decision was made, not just that other ideas existed. Criteria and evidence make the rejection defensible.', 'decision documentation', 'PREREQUISITE_FREE', false, 'alternative-rejection-record', 'design rationale', false, ['idea list as reasoning']);
$Q($cPractice, 4, 'PROFESSIONAL', 'A contractor suggests omitting a roof access hatch because maintenance can be performed through an adjacent room. What should be tested?', 'Whether the alternate route is safe, dimensionally usable, weather-protected, maintainable, and consistent with the equipment and project requirements.', ['Accept it because the equipment remains reachable in theory.', 'Omit all access because roofs need no maintenance.', 'Choose the smallest opening that appears on plan.', 'Leave access to future operators without documentation.'], 'Maintenance access is an operational path with safety and weather consequences. A theoretical route is not enough.', 'maintenance access', 'REQUIRED:architecture-technical-integration', false, 'roof-maintenance-route', 'serviceability', true, ['theoretical access']);
$Q($cPractice, 3, 'PROFESSIONAL', 'A client asks which design is “more sustainable” without stating operational assumptions or performance criteria. What should the architect do?', 'Define the relevant goals and assumptions, then compare energy, water, materials, comfort, durability, and life-cycle consequences as applicable.', ['Choose the option with more vegetation in the rendering.', 'Declare the newest technology sustainable by default.', 'Use a single product label as the entire analysis.', 'Avoid discussing sustainability because it is subjective.'], 'Sustainability claims require criteria and assumptions. A balanced comparison avoids replacing performance with imagery or marketing.', 'sustainability comparison', 'REQUIRED:architecture-technical-integration', false, 'sustainability-label', 'performance criteria', false, ['green image as evidence']);
$Q($cPractice, 4, 'REGULATORY', 'A permit submission includes a code note copied from a prior jurisdiction but the project is in a different local authority. What is the proper action?', 'Verify the governing local requirements and approval process before retaining or revising the note.', ['Keep it because code language is universal.', 'Delete all code notes to avoid error.', 'Use whichever note has the most dimensions.', 'Ask the renderer to make the note less visible.'], 'Regulatory applicability depends on jurisdiction and current source. A prior note is not automatically portable.', 'jurisdiction verification', 'PREREQUISITE_FREE', false, 'jurisdiction-copy', 'regulatory applicability', true, ['code portability']);
$Q($cPractice, 3, 'PROFESSIONAL', 'A design coordination issue affects a ceiling, a sprinkler route, lighting, acoustics, and access panels. Why is a one-discipline fix inadequate?', 'The interface is a shared performance zone, so the resolution must preserve all affected systems and their maintenance requirements.', ['Because every discipline must use identical materials.', 'Because ceilings are only architectural.', 'Because moving one object never changes another.', 'Because coordination should be done after finishes.'], 'The ceiling zone is an integrated interface. A local fix can create a new conflict or remove access elsewhere.', 'ceiling coordination', 'REQUIRED:architecture-technical-integration', false, 'shared-ceiling-zone', 'multi-system interface', true, ['discipline silo']);
$Q($cPractice, 4, 'PROFESSIONAL', 'A project’s accessibility route is compliant on paper but directs users through a loading area during deliveries. Which review is required?', 'Evaluate the route under real operating conditions and provide a safe, dignified alternative or controlled separation.', ['Accept it because the route is dimensionally correct.', 'Tell users to wait until deliveries end.', 'Remove all loading activity from the schedule without evidence.', 'Mark the loading area as decorative.'], 'Operational conflicts can make a nominal route unsafe or undignified. Access, service, and time-based use must be coordinated.', 'operational route design', 'REQUIRED:architecture-spatial-integration', false, 'loading-access-conflict', 'route operation', true, ['paper compliance']);
$Q($cPractice, 3, 'PROFESSIONAL', 'A design review comment says “coordinate utilities” without identifying the system or interface. How should the comment be improved?', 'Name the affected systems, location, decision needed, responsible parties, evidence, and due action.', ['Leave it broad so every team can interpret it.', 'Close it because coordination was mentioned.', 'Assign it to architecture without a location.', 'Replace it with a color change on the plan.'], 'Actionable comments identify what must be coordinated and who must resolve it. Vague language creates false closure.', 'review comment', 'PREREQUISITE_FREE', false, 'actionable-coordination-comment', 'review control', false, ['vague closure']);
$Q($cPractice, 4, 'PROFESSIONAL', 'A renovation discovers asbestos-like material during demolition, but the project has no verified hazardous-material survey. What is the appropriate professional response?', 'Stop the affected work, follow the qualified assessment and regulatory procedure, and revise the plan before disturbing the material.', ['Continue carefully because the material is only in one room.', 'Ask the laborer to identify it by appearance.', 'Encapsulate it without testing or authority.', 'Hide it behind new finishes.'], 'Potential hazardous material is a high-risk condition requiring qualified assessment and regulated handling. Visual guesswork is not a safe design decision.', 'hazardous-material response', 'REQUIRED:architecture-professional-judgment', false, 'hazardous-material-guess', 'work stoppage and assessment', true, ['appearance as identification']);
$Q($cPractice, 3, 'PROFESSIONAL', 'Which principle best describes a responsible architectural recommendation?', 'It connects the client brief and user needs to evidence, constraints, alternatives, consequences, and an explicit level of confidence.', ['It is the option with the most persuasive rendering.', 'It is whichever option the architect first imagined.', 'It avoids discussing constraints so the client stays optimistic.', 'It is always the cheapest option.'], 'A recommendation is professional when its reasoning and limits are visible. Confidence should follow evidence, not presentation strength.', 'recommendation quality', 'PREREQUISITE_FREE', false, 'evidence-based-recommendation', 'recommendation', false, ['rendering as evidence']);
$Q($cPractice, 4, 'REGULATORY', 'A fire strategy relies on a door being held open during normal operation, but the team has not checked the release behavior during alarm conditions. What should happen?', 'Verify the door, alarm, hardware, egress, and applicable fire requirements as one coordinated life-safety system.', ['Assume the hold-open device is safe because it improves circulation.', 'Remove all hold-open devices without checking use.', 'Treat the door as ordinary interior furniture.', 'Ask occupants to close it manually during an alarm.'], 'Door behavior is part of the fire and egress system. The release condition and current requirement must be verified, not inferred from normal circulation.', 'fire-door coordination', 'REQUIRED:architecture-technical-integration', false, 'hold-open-alarm', 'life-safety system', true, ['normal-operation bias']);
$Q($cPractice, 3, 'PROFESSIONAL', 'A project team wants to use a generic detail library for a coastal facade without checking exposure or maintenance. What is the most important objection?', 'The detail must be adapted and verified for the project’s climate, materials, water management, corrosion, movement, and access conditions.', ['Generic details are always invalid.', 'Library details require no project evidence.', 'Coastal exposure affects appearance only.', 'Maintenance can be left to the owner without design input.'], 'A detail library is a starting resource. Exposure and interfaces control durability, so the generic detail cannot be accepted without adaptation.', 'detail adaptation', 'REQUIRED:architecture-technical-integration', false, 'generic-detail-transfer', 'coastal durability', true, ['library detail as final']);
$Q($cPractice, 4, 'PROFESSIONAL', 'A client’s cost target can be met only by reducing a required accessible clear area. Which alternative is ethically and professionally strongest?', 'Preserve the required accessible function and seek savings in lower-risk scope through a transparent options review.', ['Reduce the clear area and call it value engineering.', 'Hide the reduction in furniture notation.', 'Shift the burden to users who need access.', 'Claim the target is more important than the requirement.'], 'A cost target does not justify removing a required public-interest function. Transparent trade-offs should protect accessibility while finding other savings.', 'public-interest value engineering', 'REQUIRED:architecture-spatial-integration', false, 'accessibility-cost-cut', 'cost and access', true, ['cost overrides access']);
$Q($cPractice, 3, 'PROFESSIONAL', 'What should a design team do when a consultant’s model and the architectural model disagree but both are marked current?', 'Compare revision histories and shared references, identify the authoritative status, and coordinate a controlled reconciliation.', ['Merge geometry automatically.', 'Choose the model with more objects.', 'Ignore the discrepancy until construction.', 'Delete the consultant model.'], 'Model coordination requires version, datum, and responsibility control. Object count or convenience is not evidence of authority.', 'model coordination', 'REQUIRED:architecture-technical-integration', false, 'current-model-conflict', 'digital coordination', false, ['object count as authority']);
$Q($cPractice, 4, 'PROFESSIONAL', 'A public client asks for a design change that improves security but creates a concealed corner and reduces passive supervision. What should be compared?', 'Security benefit, visibility, user experience, emergency response, accessibility, and operational consequences across alternatives.', ['Security always overrides visibility.', 'Visibility is cosmetic and can be ignored.', 'Choose the option with the tallest barrier.', 'Leave the conflict to future security staff.'], 'Security is a system objective with spatial and social consequences. A professional comparison tests competing effects rather than optimizing one label.', 'security and visibility', 'REQUIRED:architecture-spatial-integration', false, 'security-visibility-tradeoff', 'public-space safety', true, ['single-objective security']);
$Q($cPractice, 3, 'PROFESSIONAL', 'A drawing note says “provide as required” for an interface that affects firestopping and acoustic continuity. Why is this weak?', 'It leaves a material performance and responsibility boundary undefined at a high-risk interface.', ['Because every drawing note must contain a price.', 'Because performance cannot be specified.', 'Because firestopping is only a contractor issue.', 'Because acoustic continuity is unrelated to joints.'], 'A vague note transfers a critical requirement without defining the performance, location, evidence, or responsible coordination.', 'specification clarity', 'REQUIRED:architecture-technical-integration', false, 'as-required-interface', 'performance responsibility', true, ['critical interface vagueness']);
$Q($cPractice, 4, 'PROFESSIONAL', 'A client wants to reuse a school building as housing but provides no information about household size, privacy, daylight, services, or accessible use. What is the best next step?', 'Develop a brief and evidence plan for users, program, environmental performance, utilities, and accessibility before choosing the conversion layout.', ['Divide classrooms into equal bedrooms immediately.', 'Assume the school’s circulation fits housing.', 'Choose a facade treatment before programming.', 'Use a residential image as proof of feasibility.'], 'Adaptive reuse depends on the new use and its users. The missing brief and performance evidence control whether the conversion is viable.', 'adaptive reuse programming', 'REQUIRED:architecture-spatial-integration', false, 'reuse-program-gap', 'program evidence', false, ['old use equals new use']);
$Q($cPractice, 3, 'PROFESSIONAL', 'Which action is most appropriate when a design decision has a material effect on occupants but the affected user group has not been consulted?', 'Identify the affected users and obtain or document relevant input before closing the decision, subject to the project process.', ['Proceed because the design team represents everyone automatically.', 'Consult only the loudest stakeholder.', 'Avoid recording the gap.', 'Treat consultation as a cosmetic exercise after construction.'], 'User impact is part of design evidence. The process should identify whose needs matter and how input affects the decision.', 'user-centered practice', 'REQUIRED:architecture-spatial-integration', false, 'missing-user-input', 'stakeholder evidence', false, ['designer proxy assumption']);
$Q($cPractice, 4, 'REGULATORY', 'A project team discovers that an old accessibility detail was copied into a new drawing set after the governing requirement changed. What is the correct production action?', 'Flag the affected details, verify the current official requirement, revise the set, and document the review before submission.', ['Leave it because it was previously approved elsewhere.', 'Change the date only.', 'Wait for the reviewer to identify every occurrence.', 'Remove accessibility details from the set.'], 'A changed requirement creates a traceability and production risk. A controlled sweep and current-source verification are needed.', 'regulatory document update', 'REQUIRED:architecture-spatial-integration', false, 'stale-detail-sweep', 'document revision', true, ['prior approval portability']);
$Q($cPractice, 3, 'PROFESSIONAL', 'A proposed design has a compelling public image but no clear maintenance access to planted roofs and water features. Which review is needed?', 'Test operations, inspection, replacement, safety, drainage, and access before treating the image as a complete design.', ['Accept it because landscape features improve the rendering.', 'Assume maintenance will not affect design.', 'Remove all planting without studying alternatives.', 'Hide equipment behind inaccessible planting.'], 'Public features need life-cycle support. Maintenance and safety are design requirements, not post-occupancy surprises.', 'landscape maintenance', 'REQUIRED:architecture-spatial-integration', false, 'amenity-maintenance-gap', 'life-cycle operation', true, ['rendering as completion']);
$Q($cPractice, 4, 'PROFESSIONAL', 'A design change would save construction time but reduce future flexibility for a tenant whose program is not yet fixed. How should it be evaluated?', 'Compare schedule benefit with reversibility, adaptability, future cost, user uncertainty, and the consequences of locking the layout.', ['Choose the fastest option automatically.', 'Ignore future flexibility because it is uncertain.', 'Preserve every possible option regardless of cost.', 'Let the contractor decide the tenant program.'], 'Early decisions should account for uncertainty and reversibility. A fast irreversible choice may create greater future cost or loss of function.', 'adaptability decision', 'REQUIRED:architecture-spatial-integration', false, 'speed-versus-flexibility', 'future adaptability', false, ['schedule-only optimization']);
$Q($cPractice, 3, 'PROFESSIONAL', 'A meeting note records “approved” but does not identify who approved a change or which drawing it affects. What defect remains?', 'The authority, scope, and controlled information are unclear, so downstream teams cannot reliably implement the decision.', ['None; the word approved is sufficient.', 'Only the font size is defective.', 'The design is invalid because all notes need a sketch.', 'The contractor can infer the affected drawing.'], 'Approval must be attributable and connected to affected documents. Otherwise the note cannot control production reliably.', 'approval record', 'PREREQUISITE_FREE', false, 'approval-without-scope', 'authorization traceability', false, ['approval word as complete record']);
$Q($cPractice, 4, 'PROFESSIONAL', 'A design team proposes a public stair as the only route to a raised platform and labels an elevator “future.” What should the architect examine?', 'Whether the current accessible route, required functions, egress, program timing, and applicable rules are satisfied without relying on an uncertain future phase.', ['Accept it because a future elevator is shown.', 'Treat the stair as accessible for everyone.', 'Remove the platform from the program record.', 'Assume users can request temporary lifting assistance.'], 'A future promise does not make present access or life safety work. Phasing must preserve required function in the actual occupied phase.', 'phased access', 'REQUIRED:architecture-spatial-integration', false, 'future-access-placeholder', 'phasing and access', true, ['future provision as present compliance']);
$Q($cPractice, 3, 'PROFESSIONAL', 'Which statement best describes the architect’s responsibility when coordinating specialist design?', 'Integrate the specialist work with architectural intent and project requirements, identify conflicts, and avoid certifying work outside verified competence.', ['The architect owns every specialist calculation.', 'The architect has no responsibility for interfaces.', 'Specialists remove the need for architectural coordination.', 'Coordination means accepting every specialist recommendation unchanged.'], 'Specialists provide expertise, but architecture still coordinates interfaces and project consequences. Responsibility is neither total ownership nor zero involvement.', 'specialist coordination', 'REQUIRED:architecture-technical-integration', false, 'specialist-boundary', 'architectural integration', false, ['all-or-nothing responsibility']);
$Q($cPractice, 4, 'REGULATORY', 'A proposed occupancy change is assumed to require no review because the building envelope is unchanged. What should the architect verify?', 'The effect of the new use on occupancy, egress, accessibility, fire protection, utilities, and applicable approvals.', ['Only the facade color.', 'Nothing because the envelope is unchanged.', 'Only the owner’s intended furniture.', 'Whether the new use has the same name as the old use.'], 'Occupancy and use can change life-safety, access, load, and service requirements even when the envelope remains. Regulatory applicability must be checked.', 'occupancy-change review', 'REQUIRED:architecture-technical-integration', false, 'use-change-no-review', 'occupancy and approvals', true, ['envelope-only review']);
$Q($cPractice, 3, 'PROFESSIONAL', 'A proposal uses a new material with limited local installation experience. What evidence should inform the recommendation?', 'Supplier data, relevant tested or documented performance, detailing, installer competence, availability, maintenance, and project-specific risks.', ['Only a glossy sample.', 'Only the material’s environmental slogan.', 'The architect’s familiarity with another product.', 'A promise that training will happen later.'], 'Novelty raises evidence and implementation questions. A sample cannot establish durability, installation, maintenance, or interface performance.', 'material selection', 'REQUIRED:architecture-technical-integration', false, 'novel-material-evidence', 'material risk', false, ['sample as performance proof']);
$Q($cPractice, 4, 'PROFESSIONAL', 'A client asks the architect to remove a design note warning of a flood-sensitive basement because it may affect financing. What is the proper response?', 'Retain and communicate the material risk with evidence and mitigation options rather than suppressing it.', ['Remove the note and tell the contractor privately.', 'Change “flood-sensitive” to “premium basement.”', 'Delete the basement from the risk discussion.', 'Wait until financing is complete to disclose it.'], 'A material foreseeable risk should be communicated accurately. Financing pressure does not justify concealing evidence that affects public or client decisions.', 'risk disclosure', 'REQUIRED:architecture-spatial-integration', false, 'risk-suppression', 'material risk communication', true, ['financial pressure as excuse']);
$Q($cPractice, 3, 'PROFESSIONAL', 'What should an architect do when an owner’s verbal direction conflicts with the written project brief?', 'Clarify the change, identify the current governing instruction, and document the owner’s authorized decision before revising the work.', ['Follow whichever instruction is newer by memory.', 'Revise the drawings silently.', 'Ask the contractor to resolve the conflict.', 'Ignore the verbal direction permanently.'], 'Conflicting instructions need a controlled clarification so scope, authorization, and affected documents remain clear.', 'brief reconciliation', 'PREREQUISITE_FREE', false, 'verbal-written-conflict', 'instruction control', false, ['verbal direction as self-proving']);
$Q($cPractice, 4, 'REGULATORY', 'A proposed fire exit discharge crosses a landscaped area that becomes slippery and obstructed during heavy rain. What should be assessed?', 'The route’s year-round safety, drainage, surface, maintenance, illumination, capacity, and applicable egress requirements.', ['Accept it because landscaping is a softer surface.', 'Assess only the dry-season plan.', 'Assume emergency users can choose another route.', 'Replace the landscape with paving without checking drainage.'], 'Egress is a real operational route. Seasonal surface and maintenance conditions can defeat a nominal plan and must be coordinated with requirements.', 'exit discharge assessment', 'REQUIRED:architecture-spatial-integration', false, 'seasonal-egress', 'egress operation', true, ['dry-condition assumption']);
$Q($cPractice, 3, 'PROFESSIONAL', 'Which revision practice best protects a drawing set after a major coordination decision?', 'Identify the revision, affected sheets, reason, date, responsible review, and related documents that must change.', ['Update only the title block.', 'Replace the file without a revision record.', 'Cloud every object whether affected or not.', 'Rely on the project email subject line.'], 'Controlled revisions make the extent and reason of change visible. A title block or email alone is insufficient.', 'drawing revision', 'PREREQUISITE_FREE', false, 'revision-traceability', 'document control', false, ['title-block-only revision']);
$Q($cPractice, 4, 'PROFESSIONAL', 'A proposed public facility has an attractive main entrance but the service entrance shares the only accessible route during deliveries. Which design approach is stronger?', 'Separate or schedule service movement so the accessible public route remains safe, legible, and dignified during operation.', ['Keep the shared route because it is shortest.', 'Tell accessible users to wait for deliveries.', 'Move the main entrance without studying wayfinding.', 'Treat deliveries as outside the design scope.'], 'Public and service movement can conflict. The design should protect access under real use rather than relying on a nominal path.', 'public-service separation', 'REQUIRED:architecture-spatial-integration', false, 'service-route-conflict', 'operational separation', true, ['shortest route bias']);

// Utilities, structural conceptualization, materials, and construction: 70
// questions. Numerical items use stated assumptions; regulatory items avoid
// unsupported remembered thresholds.
$Q($cTechnical, 3, 'NEUTRAL', 'A wall section shows insulation interrupted at a concrete balcony slab. What is the principal technical concern?', 'The slab creates a thermal bridge that can increase heat flow and local condensation risk.', ['The slab automatically improves acoustic isolation everywhere.', 'The interruption has no effect if the wall is painted.', 'The bridge changes only the facade color.', 'The slab eliminates the need for drainage detailing.'], 'A conductive bridge bypasses part of the insulation and can create a colder interior surface. Its thermal and moisture consequences must be detailed and assessed.', 'failure/error identification', 'PREREQUISITE_FREE', false, 'thermal-bridge', 'thermal continuity', false, ['insulation continuity assumed']);
$Q($cTechnical, 4, 'PROFESSIONAL', 'A rainscreen wall has a sealed outer finish but no visible drainage path behind it. Which review is most important?', 'Verify that water entering at joints can drain and that the air, water, and flashing layers remain continuous at openings and transitions.', ['Add more sealant to the outer face without checking the cavity.', 'Treat the finish as the complete water-control system.', 'Close the cavity because drainage is only a maintenance issue.', 'Replace the wall with a heavier finish without tracing water.'], 'A drained enclosure manages incidental water through a deliberate path. Sealant alone is not a substitute for cavity drainage and continuous transitions.', 'diagnosis', 'PREREQUISITE_FREE', false, 'rainscreen-drainage', 'water management', true, ['sealant-only water control']);
$Q($cTechnical, 3, 'NEUTRAL', 'Which layer should be traced continuously when an architect checks a roof-to-wall enclosure junction?', 'Water-shedding, drainage, air, vapor, thermal, and structural continuity as applicable to the assembly.', ['Only the visible finish layer.', 'Only the structural frame because finishes are independent.', 'Only the interior paint layer.', 'Only the roof membrane with no wall transition.'], 'Enclosure performance is a set of interacting control layers. The junction is a common failure location because continuity changes there.', 'process interpretation', 'PREREQUISITE_FREE', false, 'enclosure-control-layers', 'junction continuity', false, ['single-layer enclosure']);
$Q($cTechnical, 4, 'PROFESSIONAL', 'A cold roof deck lies below a humid interior and the air barrier is discontinuous at a service penetration. What mechanism most directly raises condensation risk?', 'Air leakage can carry moist indoor air to a cold surface where its temperature falls below the dew point.', ['Radiation makes all roof surfaces the same temperature.', 'The vapor drive disappears when a penetration is small.', 'Condensation requires liquid water to enter from outdoors.', 'A thicker interior finish always warms the deck.'], 'Moist air transported by leakage can reach a cold surface and condense. The risk depends on temperature, humidity, air movement, and layer continuity.', 'moisture diagnosis', 'PREREQUISITE_FREE', false, 'air-leakage-condensation', 'condensation mechanism', true, ['vapor and air movement conflated']);
$Q($cTechnical, 3, 'NEUTRAL', 'A partition meets its nominal acoustic rating, but sound travels around it through a suspended ceiling and unsealed penetrations. What is occurring?', 'Flanking transmission is bypassing the nominal partition path.', ['The partition rating guarantees whole-room isolation.', 'Sound can travel only through the door.', 'The ceiling automatically blocks all airborne sound.', 'Penetrations affect only thermal performance.'], 'An assembly rating does not eliminate alternate paths. Flanking through ceilings, floors, adjacent walls, and penetrations can dominate the room-to-room result.', 'diagnosis', 'PREREQUISITE_FREE', false, 'acoustic-flanking', 'sound path', false, ['rating equals field performance']);
$Q($cTechnical, 4, 'PROFESSIONAL', 'A facade detail uses a rigid panel over a flexible sealant joint with no movement allowance at the support. What should the architect investigate?', 'Differential movement, joint width, sealant compatibility, fasteners, tolerances, and the intended weather seal.', ['Increase panel thickness without checking movement.', 'Make the joint rigid so nothing can move.', 'Use paint to bridge the joint.', 'Ignore movement because the panels are light.'], 'Movement must be accommodated at the joint and support. A rigid detail can crack, debond, or admit water when materials move differently.', 'failure/error identification', 'REQUIRED:architecture-technical-integration', false, 'facade-movement-joint', 'movement accommodation', true, ['rigidity as durability']);
$Q($cTechnical, 3, 'NEUTRAL', 'A roof drain is placed at a local low point, but the roof falls away from it on two sides. What should be checked before construction?', 'The actual drainage geometry, overflow path, membrane falls, and tolerance at the drain and adjacent penetrations.', ['The drain diameter alone.', 'The roof color because color controls flow.', 'Whether the low point is visually centered.', 'The number of downspouts without checking falls.'], 'Drainage depends on connected slopes and overflow behavior. A symbol at a low point does not prove that water can reach it under tolerances.', 'drainage coordination', 'PREREQUISITE_FREE', false, 'roof-drain-falls', 'roof drainage', true, ['drain symbol as drainage proof']);
$Q($cTechnical, 3, 'NEUTRAL', 'A window opening is detailed without a sill pan or end dam. What failure mode is most plausible?', 'Water reaching the opening may bypass the sill drainage path and enter the wall or interior.', ['The opening automatically sheds all water outward.', 'The missing sill detail affects only daylight.', 'End dams are needed only on roofs.', 'A thicker glass unit prevents wall leakage.'], 'Openings interrupt continuous wall control layers. Sill flashing and end dams help direct water outward rather than into the assembly.', 'window moisture diagnosis', 'PREREQUISITE_FREE', false, 'window-sill-drainage', 'opening water control', true, ['glass as water barrier']);
$Q($cTechnical, 3, 'NEUTRAL', 'A concrete slab is 8 m long, 6 m wide, and 120 mm thick. What volume of concrete is required before waste allowance?', '5.76 m³', ['0.576 m³', '57.6 m³', '576 m³'], 'Convert 120 mm to 0.12 m, then volume = 8 × 6 × 0.12 = 5.76 m³.', 'calculation', 'PREREQUISITE_FREE', true, 'volume-area-times-thickness', 'concrete volume', false, ['millimetres treated as metres'], 'architecture-3-3-foundation');
$Q($cTechnical, 3, 'NEUTRAL', 'A rectangular wall is 12 m long and 3 m high. Openings occupy 10% of the gross wall area. What net wall area remains?', '32.4 m²', ['3.6 m²', '36 m²', '39.6 m²'], 'Gross area is 12 × 3 = 36 m²; net area is 0.90 × 36 = 32.4 m².', 'calculation', 'PREREQUISITE_FREE', true, 'wall-net-area', 'net wall area', false, ['subtracting openings twice'], 'architecture-3-3-foundation');
$Q($cTechnical, 4, 'PROFESSIONAL', 'A wall has U = 0.50 W/(m²·K), area 20 m², and indoor-outdoor temperature difference 10 K. What steady conductive heat-transfer rate follows from Q = UAΔT?', '100 W', ['10 W', '50 W', '1,000 W'], 'Q = U A ΔT = 0.50 × 20 × 10 = 100 W. The temperature difference is a difference, so kelvin and degrees Celsius have the same numerical increment.', 'calculation', 'PREREQUISITE:architecture-spatial-integration', true, 'U-A-delta-T', 'heat flow', true, ['omitting area', 'confusing W and kW'], 'architecture-3-1-foundation');
$Q($cTechnical, 4, 'PROFESSIONAL', 'A 100-mm-thick layer has k = 0.50 W/(m·K), area 10 m², and a 10 K temperature difference. What heat rate follows from one-dimensional conduction?', '500 W', ['5 W', '50 W', '5,000 W'], 'R = L/(kA) = 0.10/(0.50 × 10) = 0.02 K/W; Q = ΔT/R = 10/0.02 = 500 W.', 'calculation', 'PREREQUISITE:architecture-spatial-integration', true, 'L-over-kA-and-delta-T-over-R', 'conduction rate', true, ['millimetres not converted', 'inverting resistance'], 'architecture-3-1-foundation');
$Q($cTechnical, 3, 'NEUTRAL', 'A roof catchment is 150 m² and a preliminary design rainfall intensity is 0.10 L/(s·m²). What flow does the assumed outlet arrangement need to accommodate?', '15 L/s', ['1.5 L/s', '150 L/s', '1,500 L/s'], 'Using the supplied preliminary relation, flow = area × intensity = 150 × 0.10 = 15 L/s. The result is conditional on the stated intensity and does not replace code sizing.', 'calculation', 'PREREQUISITE_FREE', true, 'roof-area-times-rainfall-intensity', 'roof flow', true, ['decimal shift', 'confusing area with volume'], 'architecture-3-2-foundation');
$Q($cTechnical, 4, 'PROFESSIONAL', 'A duct section has area 0.010 m² and mean air velocity 2.0 m/s. What volumetric flow rate follows from Q = AV?', '0.020 m³/s', ['0.002 m³/s', '0.20 m³/s', '2.0 m³/s'], 'Q = A V = 0.010 × 2.0 = 0.020 m³/s. This is a preliminary continuity calculation and does not determine pressure loss or code compliance.', 'calculation', 'PREREQUISITE:architecture-spatial-integration', true, 'duct-area-times-velocity', 'airflow', true, ['decimal shift', 'confusing velocity with flow'], 'architecture-3-2-foundation');
$Q($cTechnical, 4, 'PROFESSIONAL', 'A simply supported beam carries a uniform load of 6 kN/m over 4 m. What vertical reaction occurs at each support for a symmetric load?', '12 kN', ['6 kN', '24 kN', '48 kN'], 'Total load is wL = 6 × 4 = 24 kN; symmetry gives each reaction 24/2 = 12 kN.', 'calculation', 'PREREQUISITE:architecture-spatial-integration', true, 'wL-over-2', 'structural reaction', true, ['using w as total load', 'forgetting two supports'], 'architecture-3-3-foundation');
$Q($cTechnical, 3, 'NEUTRAL', 'A column carries 120 kN over a 2,400 mm² gross section in a preliminary uniform-stress check. What average stress results?', '50 MPa', ['0.05 MPa', '5 MPa', '500 MPa'], 'Stress = P/A = 120,000 N/2,400 mm² = 50 N/mm² = 50 MPa. The result is an average conceptual check, not a complete capacity design.', 'calculation', 'PREREQUISITE:architecture-spatial-integration', true, 'P-over-A', 'structural stress', true, ['kN/mm² conversion'], 'architecture-3-3-foundation');
$Q($cTechnical, 4, 'PROFESSIONAL', 'A steel beam option reduces span by adding a column, but the column interrupts the accessible route and service corridor. What is the best architectural-technical evaluation?', 'Compare structural efficiency with circulation, accessibility, utilities, visibility, fire, and maintenance consequences before selecting the option.', ['Choose the shortest span automatically.', 'Reject the column because all columns are bad in plans.', 'Move the route around it without checking clearances.', 'Select the lighter beam without checking the structural concept.'], 'Structural decisions change spatial and system relationships. The architect should coordinate a complete alternative comparison rather than optimize span alone.', 'comparison', 'REQUIRED:architecture-spatial-integration', false, 'span-column-tradeoff', 'structural-spatial integration', true, ['span-only optimization']);
$Q($cTechnical, 3, 'NEUTRAL', 'Why are movement joints placed in long building assemblies?', 'To accommodate expected thermal, shrinkage, seismic, or differential movement without forcing uncontrolled cracking or distress.', ['To make every panel carry more load.', 'To eliminate the need for water control.', 'To guarantee that materials never move.', 'To replace all structural joints with sealant.'], 'Joints manage expected movement. Their location and detailing must also preserve water, air, fire, thermal, acoustic, and structural performance.', 'principle interpretation', 'PREREQUISITE_FREE', false, 'movement-joint-purpose', 'joint function', false, ['joint as cosmetic break']);
$Q($cTechnical, 4, 'PROFESSIONAL', 'A facade is supported from a frame that deflects more than the brittle cladding can tolerate. Which design question should be asked?', 'Whether the support, connections, joints, and cladding system can accommodate the predicted movement while retaining weather and safety performance.', ['Increase cladding thickness without checking deflection.', 'Make all joints rigid.', 'Ignore frame movement because the cladding is nonstructural.', 'Use a darker finish to hide cracking.'], 'Nonstructural cladding still has movement and safety requirements. Connections and joints must reconcile frame movement with brittle material limits.', 'failure/error identification', 'REQUIRED:architecture-spatial-integration', false, 'frame-cladding-movement', 'deflection compatibility', true, ['nonstructural equals no movement']);
$Q($cTechnical, 3, 'NEUTRAL', 'A material is strong in compression but porous and exposed at an unprotected base. Which additional property is critical before selection?', 'Moisture absorption, durability, freeze or wet-dry exposure as relevant, detailing, and maintenance.', ['Only compressive strength.', 'Only surface color.', 'Only nominal density with no exposure.', 'The material’s ability to hide a joint.'], 'Material selection is multi-property. Strength does not prevent moisture damage or poor durability at an exposed base.', 'material selection', 'PREREQUISITE_FREE', false, 'material-property-balance', 'material durability', false, ['strength-only selection'], 'architecture-3-3-foundation');
$Q($cTechnical, 4, 'PROFESSIONAL', 'A floor finish is specified continuously across a movement joint. What risk should be evaluated?', 'The finish may crack or debond if the joint movement is not carried through with a compatible detail.', ['The finish will stop the structure from moving.', 'The joint becomes unnecessary under a finish.', 'Color variation is the only likely issue.', 'A thicker adhesive always solves movement.'], 'The joint must remain functional through the finish. A rigid continuous finish can transfer movement into cracking or debonding.', 'failure/error identification', 'REQUIRED:architecture-spatial-integration', false, 'finish-over-movement-joint', 'finish movement', true, ['finish bridges joint']);
$Q($cTechnical, 3, 'NEUTRAL', 'A construction sequence places insulation after a membrane that must be inspected and repaired before concealment. What sequence principle applies?', 'Inspect and test concealed critical layers before covering them with subsequent work.', ['Conceal the membrane first to protect schedule.', 'Inspect only the final finish.', 'Allow every trade to cover another layer without records.', 'Use photographs instead of testing all required work.'], 'Concealed work needs a hold point or documented inspection before access is lost. Sequence protects quality and accountability.', 'process interpretation', 'PREREQUISITE_FREE', false, 'concealed-layer-inspection', 'construction sequence', false, ['finish-before-inspection'], 'architecture-3-3-foundation');
$Q($cTechnical, 4, 'PROFESSIONAL', 'A wall assembly changes from a vapor-open interior finish to a low-permeance layer without revisiting the climate or drying path. What should be analyzed?', 'Temperature and humidity conditions, vapor movement, air leakage, condensation risk, and the assembly’s ability to dry.', ['Permeance can be changed without any performance effect.', 'Only the finish color matters.', 'A low-permeance layer always improves every wall.', 'Drying is irrelevant once insulation is installed.'], 'Moisture performance depends on climate, layer location, air movement, and drying potential. One material property cannot establish the result.', 'diagnosis', 'REQUIRED:architecture-spatial-integration', false, 'vapor-layer-change', 'moisture risk', true, ['low permeance always better']);
$Q($cTechnical, 3, 'REGULATORY', 'A fire compartment line is drawn through an unprotected shaft penetration. What is the most important coordination question?', 'How the penetration is protected and detailed so the required separation remains continuous under the applicable fire requirements.', ['Whether the penetration is visually centered.', 'Whether the shaft is painted the same color.', 'Whether fire separation ends at the room label.', 'Whether sealant is used somewhere in the shaft.'], 'A penetration interrupts a fire separation. The required tested or approved protection and continuity must be coordinated; a symbol or generic sealant note is not proof.', 'regulatory coordination', 'REQUIRED:architecture-technical-integration', false, 'fire-compartment-penetration', 'fire continuity', true, ['penetration ignored']);
$Q($cTechnical, 3, 'REGULATORY', 'A stair is used as part of an egress strategy, but the drawings do not show how smoke, doors, handrails, or discharge are coordinated. What is the correct conclusion?', 'The stair cannot be treated as a complete egress solution until the whole route and applicable life-safety requirements are coordinated.', ['The stair is compliant because its treads are drawn.', 'Only the top landing matters.', 'Egress ends at the stair enclosure door.', 'A rendering can replace the missing life-safety information.'], 'Egress performance includes the complete route, enclosure, doors, smoke conditions, handrails, and discharge. A partial plan cannot prove compliance.', 'regulatory review', 'REQUIRED:architecture-spatial-integration', false, 'egress-stair-system', 'egress system', true, ['stair geometry only']);
$Q($cTechnical, 4, 'PROFESSIONAL', 'A mechanical room is placed above a quiet library. The equipment schedule omits vibration isolation and service access. What should guide the layout review?', 'Equipment vibration, structure-borne sound, loads, access, replacement path, drainage, and adjacent occupancy sensitivity.', ['Select the room only by shortest duct length.', 'Assume a heavier slab eliminates all vibration.', 'Hide equipment above the library without isolation.', 'Ignore maintenance because equipment is concealed.'], 'A plant room affects structure, acoustics, maintenance, and users. Its location is an integrated building decision.', 'equipment placement', 'REQUIRED:architecture-technical-integration', false, 'plant-room-vibration', 'equipment-room coordination', true, ['duct length only']);
$Q($cTechnical, 3, 'NEUTRAL', 'Which statement best distinguishes a structural concept from a final structural design?', 'A structural concept explains load path, system behavior, span, support, and coordination assumptions but does not replace verified member design.', ['A concept must include every connection calculation.', 'A concept has no relationship to architectural planning.', 'A final design can ignore load path if the form looks stable.', 'Both terms mean exactly the same deliverable.'], 'Architects need structural conceptualization to organize space and coordinate systems; final design requires qualified analysis, code checks, and detailed documentation.', 'concept boundary', 'PREREQUISITE_FREE', false, 'structural-concept-boundary', 'structural conceptualization', false, ['concept equals final design']);
$Q($cTechnical, 4, 'PROFESSIONAL', 'A long-span hall is proposed with a deep truss, but the truss conflicts with daylight clerestories and fire-service zones. What should be compared?', 'Alternative structural depth and support strategies against daylight, volume, fire, utilities, construction, cost, and maintenance.', ['Choose the truss because it spans farthest.', 'Remove the clerestories without checking the brief.', 'Hide the truss inside the fire zone.', 'Choose the shallowest member without verifying strength.'], 'Long-span structure shapes section, services, fire strategy, and environmental response. It must be compared as a building system.', 'comparison', 'REQUIRED:architecture-spatial-integration', false, 'long-span-section-tradeoff', 'long-span integration', true, ['span-only comparison']);
$Q($cTechnical, 3, 'NEUTRAL', 'A construction drawing dimensions a masonry opening from a nominal grid but does not state the required tolerance. What risk is most direct?', 'The installed opening may not fit the frame, seal, or finish because nominal geometry does not define allowable variation.', ['Tolerance affects only the drawing title.', 'A nominal grid guarantees field accuracy.', 'Sealants remove all dimensional risk.', 'The frame can always be resized in place.'], 'Tolerances connect design dimensions to fabrication and installation. Without them, the interface may fail even when nominal dimensions match.', 'construction quality', 'PREREQUISITE_FREE', false, 'masonry-opening-tolerance', 'tolerance coordination', false, ['nominal equals installed']);
$Q($cTechnical, 4, 'PROFESSIONAL', 'A roof membrane is continuous but terminates below a parapet cap whose joints shed water toward the wall. What should be investigated?', 'The cap, membrane termination, flashing, laps, fasteners, drainage direction, and movement at the parapet as one water-control assembly.', ['Add interior paint to absorb the water.', 'Treat the membrane as sufficient regardless of the cap.', 'Move the drain without checking the parapet.', 'Use a taller parapet without tracing the layers.'], 'Water control depends on the termination and cap interface, not only membrane continuity in the field.', 'enclosure diagnosis', 'PREREQUISITE_FREE', false, 'parapet-termination', 'parapet water control', true, ['field membrane only']);
$Q($cTechnical, 3, 'NEUTRAL', 'A floor assembly must separate a wet service area from an occupied room below. Which combined design concern is appropriate?', 'Water containment and drainage, penetrations, structural deflection, acoustics, fire, and maintainable access.', ['Only the floor finish color.', 'Only the thickness of the slab.', 'Drainage and acoustics are unrelated.', 'A waterproof coating removes every interface concern.'], 'Wet areas impose multiple performance demands. The assembly and penetrations must be coordinated across structure, water, sound, fire, and maintenance.', 'assembly coordination', 'REQUIRED:architecture-technical-integration', false, 'wet-area-multi-performance', 'wet area assembly', true, ['coating as complete solution']);
$Q($cTechnical, 4, 'PROFESSIONAL', 'A facade bracket passes through an air barrier and insulation at every floor. Which design response is strongest?', 'Detail a repeatable, inspectable penetration with thermal-bridge control, air/water continuity, structural attachment, and maintenance access.', ['Treat each bracket as a small exception with no standard detail.', 'Add interior caulk only.', 'Move the air barrier arbitrarily to avoid all brackets.', 'Ignore the bridge because the bracket is structural.'], 'Repeated penetrations are a system detail. The attachment must carry load while maintaining enclosure control layers and inspection access.', 'facade attachment', 'REQUIRED:architecture-spatial-integration', false, 'repeated-bracket-penetration', 'enclosure-structure interface', true, ['structural versus enclosure silo']);
$Q($cTechnical, 3, 'NEUTRAL', 'A specification calls for two dissimilar metals in direct wet contact without isolation. What risk should be considered?', 'Galvanic corrosion where the materials and electrolyte permit an electrochemical couple.', ['The metals become thermally identical.', 'Direct contact prevents all corrosion.', 'Only the visible color can change.', 'Corrosion is impossible if both metals are strong.'], 'Dissimilar metals in a conductive wet environment can corrode galvanically. Isolation, compatible materials, and drainage are possible controls.', 'material compatibility', 'PREREQUISITE_FREE', false, 'galvanic-contact', 'corrosion risk', false, ['strength prevents corrosion'], 'architecture-3-3-foundation');
$Q($cTechnical, 4, 'PROFESSIONAL', 'A timber roof is proposed over a humid interior, but the design leaves no inspection route for concealed leakage. What should the architect require?', 'A drainage and inspection strategy that makes likely leak paths detectable, repairable, and separated from vulnerable timber where practical.', ['Assume the roof never leaks if the membrane is new.', 'Close the cavity permanently to improve appearance.', 'Rely on occupant complaints as inspection.', 'Add paint to the timber and omit access.'], 'Durability includes detection and maintenance. Concealed moisture can cause damage before a visible symptom appears.', 'durability strategy', 'PREREQUISITE_FREE', false, 'concealed-leak-detection', 'timber roof durability', true, ['new membrane as guarantee']);
$Q($cTechnical, 4, 'PROFESSIONAL', 'A building services riser is sized to fit ducts but has no room for insulation, fire stopping, valves, or future access. What should be revised?', 'The riser should be coordinated for the complete services envelope, separation, clearances, installation tolerances, and maintenance.', ['Keep the riser because the ducts fit geometrically.', 'Reduce insulation to preserve the room area.', 'Put valves inside inaccessible shafts.', 'Assume fire stopping can be added later without space.'], 'A riser is a service and maintenance space, not just a duct outline. Installation and regulatory interfaces need room from the beginning.', 'riser coordination', 'REQUIRED:architecture-technical-integration', false, 'riser-space-claim', 'services coordination', true, ['geometry-only fit']);
$Q($cTechnical, 3, 'NEUTRAL', 'A construction team proposes installing fragile glazing before overhead wet work is complete. Which sequence concern is most direct?', 'The glazing may be damaged or contaminated, and adjacent seals and finishes may be compromised before protection and curing are complete.', ['Early glazing always improves quality.', 'Wet work cannot affect glass or seals.', 'Protection is unnecessary if the glass is transparent.', 'Sequence affects only labor cost.'], 'Construction sequence protects completed work and interfaces. Fragile materials should be installed when the surrounding operations and protection strategy support them.', 'construction sequence', 'PREREQUISITE_FREE', false, 'glazing-before-wet-work', 'installation sequence', false, ['early installation as progress']);
$Q($cTechnical, 4, 'PROFESSIONAL', 'A roof insulation layer is specified above the deck, but fastener layout creates repeated thermal bridges and the membrane is not continuous at penetrations. What is the proper analysis?', 'Review the complete thermal, air, water, structural attachment, and membrane-penetration strategy rather than accepting the insulation value alone.', ['Use the nominal insulation R-value as the whole result.', 'Ignore penetrations because the roof is flat.', 'Add more insulation without checking continuity.', 'Replace fasteners with longer ones without recalculating.'], 'Whole-assembly performance depends on bridges and penetrations as well as nominal insulation. The interfaces require coordinated evidence.', 'enclosure performance', 'REQUIRED:architecture-spatial-integration', false, 'roof-thermal-penetrations', 'whole-assembly review', true, ['nominal R-only']);
$Q($cTechnical, 3, 'REGULATORY', 'A building service route passes through a required fire separation, but the drawings say only “seal penetration.” What information is missing?', 'The applicable performance requirement, tested or approved protection system, installation limits, inspection, and responsibility.', ['Nothing; the word seal is sufficient.', 'Only the paint color of the sealant.', 'The exact brand regardless of rating.', 'The penetration can remain unprotected if small.'], 'Firestopping is a regulated performance and installation interface. A generic word does not establish an acceptable system.', 'regulatory detail review', 'REQUIRED:architecture-technical-integration', false, 'generic-firestop-note', 'firestopping evidence', true, ['generic sealant note']);
$Q($cTechnical, 4, 'PROFESSIONAL', 'A building has a large glazed west facade, low interior thermal mass, and limited exterior shading. Which design analysis is most important?', 'Evaluate solar gains, glare, cooling load, occupant comfort, shading alternatives, and orientation before treating glazing as a daylight solution.', ['Increase glazing because daylight is always beneficial.', 'Add interior curtains only after construction.', 'Ignore west exposure because glass is transparent.', 'Use a darker interior finish as the sole control.'], 'Glazing affects daylight, heat, glare, and energy together. West exposure and shading require a system comparison.', 'environmental systems analysis', 'REQUIRED:architecture-spatial-integration', false, 'west-glazing-solar-gain', 'solar and comfort', true, ['daylight-only glazing']);
$Q($cTechnical, 3, 'NEUTRAL', 'A room has a low-emitting finish but poor ventilation and high occupancy. Which conclusion is best?', 'Material selection alone does not establish indoor air quality; source control, ventilation, occupancy, and operation must be considered.', ['Low-emitting material guarantees good air.', 'Ventilation becomes unnecessary.', 'Occupancy has no environmental effect.', 'Only wall color controls air quality.'], 'Indoor environmental performance is a system result. A favorable material property cannot compensate for inadequate ventilation or high source loads.', 'environmental performance', 'PREREQUISITE_FREE', false, 'low-emitting-not-sufficient', 'indoor air quality', false, ['single-material guarantee']);
$Q($cTechnical, 4, 'PROFESSIONAL', 'A natural-ventilation concept relies on cross-flow, but the plan has deep rooms, few opposite openings, and doors often closed for privacy. What should be tested?', 'Actual airflow paths, opening control, room depth, privacy operation, wind conditions, and backup or mixed-mode requirements.', ['Declare natural ventilation from one operable window.', 'Add more plants without checking airflow.', 'Assume doors remain open regardless of use.', 'Ignore room depth because openings are large.'], 'Natural ventilation depends on connected paths and operation. Privacy and room depth can defeat the conceptual diagram.', 'environmental diagnosis', 'REQUIRED:architecture-spatial-integration', false, 'cross-ventilation-path', 'ventilation feasibility', true, ['one-opening ventilation']);
$Q($cTechnical, 3, 'NEUTRAL', 'A slab edge has a continuous thermal break but the balcony door threshold remains exposed to wind-driven rain. What does the detail still need?', 'A coordinated sill, flashing, drainage, seal, and threshold strategy that manages water while preserving movement and access.', ['The thermal break solves all door performance.', 'Only a thicker door leaf is needed.', 'Drainage can be omitted at a threshold.', 'Wind-driven rain is unrelated to openings.'], 'Thermal continuity does not provide water management. Door thresholds are interfaces among access, movement, air, and water control.', 'opening detail', 'REQUIRED:architecture-spatial-integration', false, 'door-threshold-interface', 'threshold performance', true, ['thermal break as complete detail']);
$Q($cTechnical, 3, 'NEUTRAL', 'A concrete wall is cast against a construction joint that is not shown in the waterproofing strategy. What risk should be reviewed?', 'The joint may become a water path unless joint geometry, reinforcement, waterstop, membrane, and drainage are coordinated.', ['Concrete is automatically watertight at every joint.', 'The joint affects only appearance.', 'Waterproofing is needed only on roofs.', 'Adding paint later proves water resistance.'], 'Joints are discontinuities that require a deliberate water-control strategy. Material name alone does not establish watertightness.', 'concrete joint', 'PREREQUISITE_FREE', false, 'concrete-joint-water', 'below-grade water control', true, ['concrete as waterproofing']);
$Q($cTechnical, 4, 'PROFESSIONAL', 'A stair landing is reduced to make room for a structural brace, but the stair is part of the accessible and emergency circulation strategy. What should be done?', 'Coordinate structural alternatives and recheck landing function, route geometry, handrails, doors, and applicable requirements before accepting the change.', ['Accept the reduced landing because the brace is structural.', 'Move the landing symbol without changing geometry.', 'Treat emergency circulation as separate from design.', 'Ask users to step around the brace.'], 'The change affects structure, access, egress, and user safety. A structural need does not automatically authorize degrading the route.', 'structural-circulation interface', 'REQUIRED:architecture-spatial-integration', false, 'brace-landing-conflict', 'circulation and structure', true, ['structural priority without route check']);
$Q($cTechnical, 3, 'NEUTRAL', 'A finish schedule lists a material but no substrate, joint, adhesive, moisture limit, or maintenance condition. What is the technical weakness?', 'The material is not a complete assembly specification, so compatibility and installation performance remain undefined.', ['Material names always define the assembly.', 'Joint design is irrelevant to finishes.', 'Maintenance never belongs in specifications.', 'Substrates affect only the color result.'], 'Material behavior depends on substrate, joint, moisture, attachment, and maintenance. A product name alone cannot coordinate the assembly.', 'specification completeness', 'PREREQUISITE_FREE', false, 'finish-assembly-gap', 'material specification', false, ['product name as complete detail'], 'architecture-3-3-foundation');
$Q($cTechnical, 4, 'PROFESSIONAL', 'A suspended ceiling is selected to conceal services but removes access to dampers, valves, fire devices, and filters. What is the better design response?', 'Coordinate a ceiling module and access strategy that preserves serviceability, performance, appearance, and future change.', ['Close all access panels for a cleaner ceiling.', 'Place access panels randomly after installation.', 'Move all services above occupied spaces without access.', 'Assume maintenance can remove the ceiling.'], 'Concealment and access must be balanced. Planned access protects operations and reduces destructive maintenance.', 'ceiling serviceability', 'REQUIRED:architecture-technical-integration', false, 'ceiling-access-panels', 'maintenance coordination', true, ['concealment-only design']);
$Q($cTechnical, 3, 'REGULATORY', 'An emergency lighting layout is shown, but the power source, test method, route coverage, and current applicable requirements are not identified. What is the correct review finding?', 'The drawing is incomplete evidence of a life-safety system and requires coordinated verification of source, coverage, testing, and requirements.', ['The symbols prove the system works.', 'Only the fixture style needs checking.', 'Emergency power is optional if daylight exists.', 'The contractor can invent the test method.'], 'Life-safety systems need reliable power, coverage, testing, and regulatory evidence. Symbols alone do not establish operation.', 'life-safety systems', 'REQUIRED:architecture-technical-integration', false, 'emergency-lighting-evidence', 'emergency system', true, ['symbolic system']);
$Q($cTechnical, 4, 'PROFESSIONAL', 'A heavy rooftop garden is added after the structural concept was set. Which first coordination question is most important?', 'How the added dead load, saturated soil, water retention, drainage, maintenance, and waterproofing affect the structure and enclosure.', ['Assume soil is light because it is planted.', 'Check only the landscape appearance.', 'Add waterproofing without checking load.', 'Treat the roof as unchanged because the footprint is unchanged.'], 'Rooftop landscapes change load and water behavior. Structural and enclosure consequences must be coordinated before the design is accepted.', 'roof garden coordination', 'REQUIRED:architecture-spatial-integration', false, 'rooftop-garden-load', 'roof system change', true, ['dry-soil assumption']);
$Q($cTechnical, 3, 'NEUTRAL', 'A room’s lighting concept relies on daylight from a north-facing opening, but the adjacent building can reflect glare into the room. What should be evaluated?', 'Daylight distribution, glare, reflectance, view, shading, and the changing context rather than orientation alone.', ['North orientation guarantees no glare.', 'A larger opening always improves visual comfort.', 'Reflectance has no effect on glare.', 'Artificial light can be omitted because daylight exists.'], 'Orientation is one input. Adjacent reflectance and time-varying sky and sun conditions affect glare and comfort.', 'daylight analysis', 'REQUIRED:architecture-spatial-integration', false, 'daylight-glare-context', 'daylight performance', true, ['orientation guarantee']);
$Q($cTechnical, 4, 'PROFESSIONAL', 'A ventilation fan is placed adjacent to a bedroom wall, and the schedule gives airflow but no sound or vibration criterion. What should the architect ask?', 'Coordinate sound transmission, vibration isolation, equipment support, duct attenuation, operating schedule, and occupant sensitivity.', ['Airflow alone establishes acceptability.', 'Move the fan anywhere outside the room without checking structure.', 'Treat sound as a furniture issue.', 'Use a louder fan so it finishes faster.'], 'Building systems affect acoustic and structural performance. A flow rate does not describe the full occupant experience.', 'mechanical-acoustic coordination', 'REQUIRED:architecture-technical-integration', false, 'fan-vibration-noise', 'equipment acoustics', true, ['airflow-only design']);
$Q($cTechnical, 3, 'NEUTRAL', 'Which construction sequence best protects a new exterior coating over a masonry wall?', 'Allow substrate preparation and drying, complete compatible joints and repairs, then apply and protect the coating under suitable conditions.', ['Apply over wet unrepaired masonry to save time.', 'Coat before resolving movement joints.', 'Ignore weather because coatings are thin.', 'Apply the finish before inspection of repairs.'], 'Coatings depend on substrate condition, moisture, joints, weather, and preparation. Sequence controls adhesion and durability.', 'construction sequence', 'PREREQUISITE_FREE', false, 'coating-substrate-sequence', 'finish installation', false, ['coating hides substrate defects']);
$Q($cTechnical, 4, 'PROFESSIONAL', 'A foundation waterproofing detail directs drainage toward a neighboring property. What must the site and technical review address?', 'The water path, collection, discharge authority, soil and foundation protection, maintenance, and downstream consequences.', ['Proceed because the basement stays dry.', 'Discharge toward the neighbor during storms.', 'Hide the outlet below landscaping.', 'Solve only the membrane without tracing the outlet.'], 'Below-grade water management includes collection and discharge. A local waterproofing success can create a downstream problem.', 'site drainage coordination', 'REQUIRED:architecture-spatial-integration', false, 'foundation-drain-discharge', 'drainage consequence', true, ['local success only']);
$Q($cTechnical, 3, 'REGULATORY', 'A stair guard is shown as a graphic line but the drawings do not identify load, openings, height, attachment, or current code basis. What is the correct conclusion?', 'The graphic indicates intent but does not establish a verified guard design or regulatory compliance.', ['The line itself proves the guard is safe.', 'Only the guard color needs to be selected.', 'A guard has no structural or life-safety role.', 'The contractor can choose any attachment.'], 'Guard design involves geometry, strength, openings, attachment, and applicable requirements. Graphic intent is not complete evidence.', 'regulatory guard review', 'REQUIRED:architecture-spatial-integration', false, 'guard-graphic-only', 'guard safety', true, ['symbol equals design']);
$Q($cTechnical, 4, 'PROFESSIONAL', 'A building uses a raised access floor for future cabling, but the proposed partitions and heavy equipment block panel removal. What should be coordinated?', 'Panel access, structural loading, service zones, partition layout, fire/acoustic continuity, and future change sequence.', ['Raised floors eliminate all coordination.', 'Put the heaviest equipment over removable panels without support.', 'Close panels permanently beneath partitions.', 'Treat future cabling as an owner-only issue.'], 'Flexibility depends on access and load strategy. A raised floor is not useful where the intended changes cannot be reached or supported.', 'flexible systems', 'REQUIRED:architecture-technical-integration', false, 'raised-floor-access', 'future change', true, ['flexibility label']);
$Q($cTechnical, 3, 'NEUTRAL', 'A masonry wall and a concrete frame have different shrinkage and thermal movement. Which detail is most important at their interface?', 'A compatible joint or reinforcement and finish strategy that accommodates differential movement and controls cracking and water.', ['Rigidly bond them without movement consideration.', 'Use a different paint color at the interface.', 'Ignore movement because both are mineral materials.', 'Add mass without detailing the joint.'], 'Similar appearance does not mean identical movement. The interface needs a deliberate joint and control strategy.', 'masonry-frame interface', 'PREREQUISITE_FREE', false, 'differential-movement', 'interface movement', false, ['same family equals same movement']);
$Q($cTechnical, 4, 'PROFESSIONAL', 'A building envelope uses a continuous air barrier on paper, but every floor slab edge has unsealed service penetrations. What should the review conclude?', 'The air-control strategy is discontinuous until the penetrations and transitions are detailed, installed, inspected, and tested as required.', ['The nominal air-barrier product solves the issue.', 'Only the exterior finish can close the leakage.', 'Penetrations are too small to matter by definition.', 'Air leakage is unrelated to moisture or energy.'], 'Continuity is a property of the installed system, not just the named product. Repeated penetrations can dominate enclosure performance.', 'air barrier continuity', 'PREREQUISITE_FREE', false, 'air-barrier-penetrations', 'air control', true, ['product name as continuity']);
$Q($cTechnical, 3, 'NEUTRAL', 'A material has high recycled content but requires frequent replacement in the project’s exposure. Which evaluation is more complete?', 'Compare durability, maintenance, replacement impact, performance, availability, and life-cycle consequences alongside recycled content.', ['Choose it because one metric is high.', 'Reject recycled content as irrelevant.', 'Ignore exposure because the product is sustainable.', 'Use the shortest specification with no maintenance plan.'], 'Material decisions are multi-criteria. A favorable attribute does not cancel durability and life-cycle effects.', 'material comparison', 'PREREQUISITE_FREE', false, 'single-sustainability-metric', 'life-cycle material choice', false, ['one metric optimization'], 'architecture-3-3-foundation');
$Q($cTechnical, 4, 'PROFESSIONAL', 'A construction joint is moved to simplify formwork but now intersects a waterproofing transition and a high-stress opening corner. What should happen?', 'Reassess structural, water, reinforcement, sequence, and inspection consequences before accepting the new joint location.', ['Accept it because formwork is cheaper.', 'Move only the waterproofing line.', 'Assume reinforcement will resolve everything.', 'Hide the joint behind a finish.'], 'Joint location is a system decision. Simplifying one trade can create structural and moisture failures at a sensitive interface.', 'construction joint change', 'REQUIRED:architecture-spatial-integration', false, 'joint-relocation', 'joint coordination', true, ['trade-only optimization']);
$Q($cTechnical, 3, 'NEUTRAL', 'A roof surface is shaded by nearby trees, but leaves block gutters and increase biological growth. What design response is most defensible?', 'Retain the environmental benefit only with a drainage, maintenance, access, and roof durability strategy.', ['Remove all trees because shade is always harmful.', 'Ignore leaves because the roof slope is sufficient.', 'Use more sealant at the gutter.', 'Treat vegetation as outside building performance.'], 'Site vegetation changes shade, moisture, maintenance, and drainage. The response should balance the benefits and operational risks.', 'site-building interface', 'REQUIRED:architecture-spatial-integration', false, 'vegetation-roof-maintenance', 'vegetation and drainage', false, ['single-effect vegetation']);
$Q($cTechnical, 4, 'PROFESSIONAL', 'A structural frame is regular, but the architectural partitions create a large open first story and heavy upper walls. What conceptual issue should be checked?', 'Load path continuity, stiffness distribution, lateral behavior, transfer conditions, and the interaction of partitions with the structural concept.', ['Regular frame above guarantees regular behavior below.', 'Partitions never affect structural planning.', 'Only the facade needs structural review.', 'A larger open space automatically improves stability.'], 'Changes in stiffness, mass, and support can create a conceptual irregularity even when the upper grid looks regular. Qualified structural analysis is required.', 'structural conceptualization', 'PREREQUISITE:architecture-spatial-integration', false, 'vertical-irregularity', 'load path and stiffness', true, ['grid regularity as proof']);
$Q($cTechnical, 3, 'NEUTRAL', 'A door is located at the end of a corridor, but the closer, latch, wall return, and nearby fixture leave no maneuvering space. What is the design issue?', 'The door and adjacent elements must be coordinated as a usable approach and maneuvering zone, not as isolated symbols.', ['The door is acceptable because its leaf is drawn.', 'Only the wall thickness matters.', 'A fixture can overlap the approach if it is small.', 'Maneuvering space is unrelated to accessibility.'], 'Doors require approach, swing, hardware, clearances, and adjacent conditions to work. A plan symbol does not prove usability.', 'door coordination', 'REQUIRED:architecture-spatial-integration', false, 'door-maneuvering-zone', 'door usability', true, ['door symbol as access']);
$Q($cTechnical, 4, 'PROFESSIONAL', 'A plant room has sufficient equipment footprint but no route for a future chiller replacement without removing a facade panel. Which decision is strongest?', 'Coordinate a planned replacement route or a maintainable removable panel with weather, fire, structure, and security consequences resolved.', ['Accept it because the initial installation fits.', 'Assume future equipment will always be smaller.', 'Remove the facade panel permanently.', 'Ignore replacement because it is an owner issue.'], 'Replacement access is part of life-cycle design. A removable panel can be valid only when its enclosure and operational consequences are designed.', 'equipment replacement', 'REQUIRED:architecture-technical-integration', false, 'replacement-route', 'life-cycle access', true, ['initial-fit-only']);

// Architectural design and site planning: 88 questions.  The block mixes
// spatial reasoning, environmental response, capacity, phasing, and bounded
// accessibility/life-safety application.
$Q($cSpatial, 3, 'NEUTRAL', 'Before placing a building on an irregular site, which information should be mapped first?', 'Contours, drainage, sun, wind, access, vegetation, views, noise, adjacent uses, and existing services.', ['Only the property boundary and north arrow.', 'Only the most attractive view.', 'Only the location of the proposed entrance.', 'Only the site area stated in the title block.'], 'A site strategy depends on physical, environmental, movement, and service relationships. A boundary alone cannot support placement.', 'site analysis', 'PREREQUISITE_FREE', false, 'site-evidence-map', 'site evidence', false, ['boundary-only mapping']);
$Q($cSpatial, 4, 'PROFESSIONAL', 'A building scheme places the main public entrance at the visually central point, but the strongest pedestrian arrival occurs along the shaded east edge. Which alternative is better supported?', 'Test an entrance and public sequence that acknowledge the actual pedestrian desire line, shade, visibility, and program hierarchy.', ['Keep the geometric center regardless of arrival evidence.', 'Place the entrance at the service edge because it is shortest to utilities.', 'Rotate the building only to improve the rendering.', 'Use multiple entrances without assigning public, service, or emergency roles.'], 'The entrance should respond to users and site conditions, not geometry alone. Arrival, climate, visibility, and functional hierarchy must be compared.', 'design alternative', 'PREREQUISITE_FREE', false, 'arrival-and-center', 'entrance placement', true, ['geometric center bias']);
$Q($cSpatial, 3, 'NEUTRAL', 'A site plan puts a children’s play area beside a busy service road because the area is flat. What should be evaluated before accepting the location?', 'Noise, safety, air quality, separation, visibility, access, shade, and the possibility of a safer flat zone.', ['Flatness alone is sufficient.', 'Service traffic has no effect outside delivery hours.', 'Move the play area to the steepest slope automatically.', 'Use a taller fence without checking supervision or access.'], 'A flat site attribute is useful but not decisive. Children’s use requires environmental and operational safety evaluation.', 'site suitability', 'PREREQUISITE_FREE', false, 'play-area-service-road', 'user safety and site', true, ['single-attribute siting']);
$Q($cSpatial, 4, 'PROFESSIONAL', 'A sloping site can be served by a long accessible route following contours or a shorter route with repeated steep changes. Which strategy is generally stronger?', 'Follow a legible, continuous route with manageable grades, landings, drainage, rest, and clear connections to destinations.', ['Choose the shortest route regardless of grade.', 'Use stairs only and provide a sign for assistance.', 'Flatten the whole site without checking cut, fill, or drainage.', 'Hide the accessible route behind service areas.'], 'Accessible circulation is a complete experience. Contour-following can reduce abrupt grade changes, but the chosen route still requires current requirement and operational checks.', 'site circulation', 'PREREQUISITE_FREE', false, 'contour-accessible-route', 'accessible site route', true, ['shortest-route bias']);
$Q($cSpatial, 3, 'NEUTRAL', 'A 2,000 m² site has an 800 m² ground footprint. What preliminary site coverage does the footprint represent?', '40%', ['4%', '25%', '250%'], 'Site coverage = footprint/site area = 800/2,000 = 0.40 = 40%. This is a preliminary ratio and does not replace the applicable regulatory definition.', 'calculation', 'PREREQUISITE_FREE', true, 'footprint-over-site-area', 'site coverage', false, ['percent decimal shift', 'reversing numerator and denominator']);
$Q($cSpatial, 3, 'NEUTRAL', 'A two-story building has 600 m² on each floor. Ignoring wall-thickness and exclusions, what gross floor area is represented?', '1,200 m²', ['300 m²', '600 m²', '3,600 m²'], 'Gross floor area across the two stated levels is 600 + 600 = 1,200 m². The result follows only the supplied simplifying assumptions.', 'calculation', 'PREREQUISITE_FREE', true, 'sum-of-floor-areas', 'gross floor area', false, ['using footprint only']);
$Q($cSpatial, 4, 'PROFESSIONAL', 'A program requires 800 m² of net rooms and a preliminary circulation/service allowance of 20% of net area. What gross programmed area follows from that allowance?', '960 m²', ['820 m²', '1,000 m²', '1,600 m²'], 'Allowance = 0.20 × 800 = 160 m²; gross programmed area = 800 + 160 = 960 m². The project must define how the allowance is measured before final budgeting.', 'calculation', 'PREREQUISITE_FREE', true, 'net-plus-percentage-allowance', 'program area', false, ['percentage applied to gross area'], 'architecture-4-2-foundation');
$Q($cSpatial, 3, 'NEUTRAL', 'A site plan at 1:500 measures a path as 4 cm. What ground length does the drawing represent?', '20 m', ['0.8 m', '2 m', '200 m'], 'At 1:500, 4 cm × 500 = 2,000 cm = 20 m.', 'calculation', 'PREREQUISITE_FREE', true, 'scale-drawing-length', 'site dimension', false, ['scale inversion', 'centimetres not converted']);
$Q($cSpatial, 3, 'NEUTRAL', 'A 24-m path rises 1.2 m from bottom to top. What average slope follows from rise divided by horizontal run?', '5%', ['0.5%', '20%', '50%'], 'Slope = 1.2/24 = 0.05 = 5%. This is an average preliminary value; the route still needs landings, surface, drainage, and applicable accessibility checks.', 'calculation', 'PREREQUISITE_FREE', true, 'rise-over-run', 'site slope', true, ['percent conversion', 'rise-run reversal'], 'architecture-4-2-foundation');
$Q($cSpatial, 4, 'PROFESSIONAL', 'A compact courtyard scheme preserves more landscape than a dispersed scheme but concentrates pedestrian traffic and service access. What should guide selection?', 'Compare landscape, microclimate, movement, servicing, privacy, fire/access, and future change against the project priorities.', ['Choose compactness because it always wins.', 'Choose dispersion because more buildings are always better.', 'Ignore service access because courtyards are public.', 'Decide from the footprint diagram alone.'], 'Site alternatives redistribute benefits and burdens. A reasoned choice makes the criteria and consequences explicit.', 'comparison', 'PREREQUISITE_FREE', false, 'compact-versus-dispersed', 'site alternative', true, ['single-metric compactness']);
$Q($cSpatial, 3, 'NEUTRAL', 'A building’s long facades face low-angle morning and afternoon sun. Which response can reduce unwanted solar gain without eliminating all daylight?', 'Use orientation-sensitive shading, controlled openings, glazing selection, and interior daylight analysis.', ['Increase unshaded glazing everywhere.', 'Close every opening permanently.', 'Use interior paint as the only solar control.', 'Rotate the building without checking access and wind.'], 'Solar control is a coordinated facade and site decision. Shading and openings should respond to orientation, sun angle, glare, and daylight needs.', 'environmental response', 'PREREQUISITE_FREE', false, 'low-angle-sun-control', 'solar shading', false, ['daylight versus heat false choice']);
$Q($cSpatial, 4, 'PROFESSIONAL', 'A wind study indicates strong seasonal winds from the public arrival side. Which design response should be tested?', 'Use massing, landscape, thresholds, windbreaks, and entrance placement to moderate exposure while preserving wayfinding and access.', ['Block all wind with a solid wall regardless of egress.', 'Move the entrance to the least visible edge without studying users.', 'Ignore wind because the entrance is covered.', 'Add decorative screens without checking pressure or maintenance.'], 'Wind response is a site and building relationship. A protected threshold can improve comfort, but the strategy must preserve routes, visibility, and operation.', 'environmental response', 'PREREQUISITE_FREE', false, 'wind-at-arrival', 'wind and entrance', true, ['covered equals protected']);
$Q($cSpatial, 3, 'NEUTRAL', 'A quiet reading room is planned next to a loading dock because both need ground-level access. Which zoning move is best?', 'Separate the uses with a buffer or locate the loading function where noise and vehicle movement have less effect on the reading room.', ['Treat all ground-floor uses as equivalent.', 'Place the quietest room beside the busiest dock.', 'Use a sign asking trucks to be quiet.', 'Remove the reading room’s windows only.'], 'Adjacency should reflect noise, vibration, access, and service patterns. A buffer or changed relationship can reduce conflict.', 'functional zoning', 'PREREQUISITE_FREE', false, 'quiet-space-loading', 'noise zoning', false, ['ground-floor equivalence']);
$Q($cSpatial, 4, 'PROFESSIONAL', 'A hospital-like program has public, staff, sterile/service, and emergency movements. Which planning method best limits conflict?', 'Map each user and service flow, identify shared and separated segments, then test adjacency, control points, and emergency continuity.', ['Use one central corridor for every movement without testing conflicts.', 'Separate all routes so no system can share space.', 'Place corridors after rooms are finalized.', 'Use color coding alone as the circulation solution.'], 'Complex programs require flow analysis. Shared paths can be efficient when compatible, but conflicts need separation, control, and emergency review.', 'circulation analysis', 'PREREQUISITE_FREE', false, 'multi-flow-circulation', 'user and service flows', true, ['one-corridor simplification']);
$Q($cSpatial, 3, 'NEUTRAL', 'A site has mature trees on its southern edge and an existing drainage swale through the center. Which first design response is most responsible?', 'Treat the trees and swale as site evidence and test building placement, access, grading, and water strategy around them.', ['Clear both before developing the plan.', 'Place the building on the swale because it is visually central.', 'Ignore them until landscape documentation.', 'Preserve the trees but fill the swale without studying drainage.'], 'Existing ecological and hydrologic features constrain the site strategy. Preservation must include their functional relationships, not only their visible objects.', 'site systems', 'PREREQUISITE_FREE', false, 'trees-and-swale', 'existing site systems', false, ['landscape as decoration']);
$Q($cSpatial, 4, 'PROFESSIONAL', 'A scheme maximizes building footprint and leaves only a narrow strip for stormwater. What should be compared before approval?', 'Runoff volume and path, soil infiltration, landscape function, downstream effect, maintenance, access, and required site capacity.', ['Approve because floor area is the main objective.', 'Assume planting absorbs all runoff.', 'Pave the strip to simplify maintenance.', 'Direct water to the property edge without checking consequence.'], 'Site capacity includes water and operations. A narrow residual landscape strip may not perform the needed hydrologic function.', 'site capacity', 'PREREQUISITE_FREE', false, 'footprint-stormwater-tradeoff', 'stormwater and coverage', true, ['floor-area-only']);
$Q($cSpatial, 3, 'NEUTRAL', 'A campus plan uses identical building orientations on every parcel even though one parcel is shaded by a taller neighbor. What is the design weakness?', 'The plan ignores parcel-specific solar, wind, view, and microclimate evidence.', ['Identical orientation always improves campus order.', 'Neighboring buildings have no environmental effect.', 'Only interior furniture should respond to shade.', 'A consistent grid eliminates site analysis.'], 'A campus may have an ordering system, but each placement still needs environmental and program testing. Uniformity is not evidence of performance.', 'campus planning', 'PREREQUISITE_FREE', false, 'orientation-context', 'context-sensitive order', false, ['uniformity as performance']);
$Q($cSpatial, 4, 'PROFESSIONAL', 'A proposed public plaza is visually open but has no shaded rest, seating, drainage, or accessible connection to the main building. What should be improved first?', 'Develop the plaza as a usable environmental and circulation system with shade, rest, water management, and continuous access.', ['Add more paving to emphasize openness.', 'Treat seating as furniture to be added later.', 'Use a rendering to imply shade.', 'Move the accessible connection to a service route.'], 'Public space performance includes comfort, rest, water, and access. Visual openness alone does not make a plaza usable.', 'public realm design', 'PREREQUISITE_FREE', false, 'plaza-usability', 'public space performance', true, ['image over operation']);
$Q($cSpatial, 3, 'NEUTRAL', 'A building entry is visible from the street but not from the parking drop-off. Which issue should the plan address?', 'Wayfinding and arrival sequence should connect the major approaches to the same legible entrance hierarchy.', ['Add a larger sign without studying movement.', 'Make every door equally prominent.', 'Move the entry to the rear automatically.', 'Ignore the drop-off because it is vehicular.'], 'Legibility is relational. Users arriving by different modes need a coherent sequence and visible destination.', 'wayfinding', 'PREREQUISITE_FREE', false, 'multi-modal-arrival', 'arrival legibility', false, ['sign-only wayfinding']);
$Q($cSpatial, 4, 'PROFESSIONAL', 'A school expansion preserves the existing play court but blocks the only route for emergency vehicles and service deliveries. Which planning principle controls?', 'Maintain reliable emergency and service access while testing alternative phasing, edges, and shared-use schedules.', ['Preserve the court regardless of access.', 'Remove the court without evaluating program value.', 'Assume emergency access can cross a locked gate.', 'Use a painted route that cannot carry or reach vehicles.'], 'Existing amenities and access both matter. A phased or shared solution is valid only when safety, schedule, and operations are reliable.', 'phasing and access', 'PREREQUISITE_FREE', false, 'school-expansion-access', 'site phasing', true, ['single-use preservation']);
$Q($cSpatial, 3, 'NEUTRAL', 'A site diagram places vehicle circulation through the main pedestrian court because it is the shortest route. What should be tested?', 'Separate or carefully manage pedestrian and vehicle movement using safety, service, visibility, and arrival criteria.', ['Shortest route always controls.', 'Pedestrians can adapt to vehicles automatically.', 'Use bollards without checking turning or emergency paths.', 'Remove the court from the program.'], 'Circulation routes must be compared by safety and user experience as well as length. Shared space can work only with evidence and control.', 'site circulation', 'PREREQUISITE_FREE', false, 'vehicle-pedestrian-conflict', 'movement separation', true, ['shortest path optimization']);
$Q($cSpatial, 4, 'PROFESSIONAL', 'A building is oriented for a favorable view but the orientation exposes major occupied rooms to afternoon glare and heat. What is the correct design process?', 'Balance view value with solar control, comfort, energy, glazing, shading, and room-use sensitivity through comparative alternatives.', ['Preserve the view at any environmental cost.', 'Eliminate all windows to remove glare.', 'Use a darker interior finish as the only remedy.', 'Rotate the building without checking access or program.'], 'Views and climate are both site inputs. An architectural decision makes the trade-off explicit and tests the complete facade response.', 'site-view comparison', 'PREREQUISITE_FREE', false, 'view-solar-tradeoff', 'view and comfort', true, ['view-only design']);
$Q($cSpatial, 3, 'NEUTRAL', 'Which adjacency is generally strongest for a community kitchen?', 'Near receiving and service access while remaining connected to dining or community space and separated from incompatible noise or hazards.', ['At the farthest point from deliveries and users.', 'Inside the quietest private office zone.', 'Directly in the emergency exit discharge path.', 'Adjacent to sensitive rooms without ventilation review.'], 'Kitchen planning combines service, users, waste, ventilation, fire, and noise. Adjacency should support the whole operation.', 'program adjacency', 'PREREQUISITE_FREE', false, 'community-kitchen-adjacency', 'service and public adjacency', false, ['single-adjacency criterion']);
$Q($cSpatial, 4, 'PROFESSIONAL', 'A site alternative retains mature trees but requires a longer utility run and more complex maintenance. Which comparison is appropriate?', 'Compare ecological value, utility cost, construction impact, maintenance, shade, drainage, and long-term site performance.', ['Preserve trees without considering utilities.', 'Remove trees because utility length is the only cost.', 'Choose from the landscape image alone.', 'Assume maintenance is unrelated to site layout.'], 'Tree retention is not automatically best or worst. A professional comparison includes both ecological and infrastructure consequences.', 'site alternative', 'PREREQUISITE_FREE', false, 'tree-utility-tradeoff', 'site systems comparison', true, ['single-factor preservation']);
$Q($cSpatial, 3, 'NEUTRAL', 'A narrow site has a public street on one side and a service lane on the other. Which zoning move often improves operation?', 'Place public arrival and identity toward the public street and organize servicing toward the service lane while maintaining safe connections.', ['Put all functions on the public street regardless of use.', 'Place service loading through the primary lobby.', 'Hide all entrances on the narrowest edge.', 'Use one route for all users without testing conflict.'], 'Edges can provide different roles. The arrangement is a hypothesis to test against access, safety, security, and program.', 'edge zoning', 'PREREQUISITE_FREE', false, 'public-service-edges', 'edge roles', false, ['all-edges-equivalent']);
$Q($cSpatial, 4, 'PROFESSIONAL', 'A proposed mixed-use block has active ground-floor uses but a blank wall along the safest pedestrian route. What should the design analysis consider?', 'Visibility, entrances, passive supervision, service conflicts, privacy, access, and the public realm along the route.', ['Add windows everywhere without checking privacy.', 'Keep the blank wall because it is efficient.', 'Move pedestrians to the service lane.', 'Treat the ground edge as unrelated to safety.'], 'Edges affect orientation, activity, supervision, privacy, and service. The design should balance them rather than maximize openings blindly.', 'public edge analysis', 'PREREQUISITE_FREE', false, 'active-edge-safety', 'public realm edge', true, ['blank edge as neutral']);
$Q($cSpatial, 3, 'NEUTRAL', 'A site has a steep north slope and a level south terrace. Which placement question should be answered before choosing the terrace for the building?', 'How the terrace relates to solar exposure, drainage, access, views, cut/fill, retaining, and the program’s environmental needs.', ['Level ground is always best.', 'North and south have no site consequence.', 'Place the building at the highest point for status.', 'Choose the terrace solely because it reduces excavation.'], 'A level terrace may reduce earthwork but introduce other environmental and access effects. Placement is a multi-criteria site decision.', 'terrain placement', 'PREREQUISITE_FREE', false, 'terrace-placement', 'topography and orientation', false, ['level-only siting']);
$Q($cSpatial, 4, 'PROFESSIONAL', 'A site plan uses a central lawn for stormwater detention, but it is also the only accessible shortcut between buildings. What should be explored?', 'Separate or integrate water storage and circulation so the route remains safe, legible, and usable during ordinary and storm conditions.', ['Keep the shortcut through standing water.', 'Eliminate the lawn without evaluating capacity.', 'Assume stormwater storage is temporary and irrelevant.', 'Move access to a steep edge.'], 'Water and movement can compete. A resilient plan designs both functions and their timing rather than assuming one disappears when the other is needed.', 'stormwater and circulation', 'PREREQUISITE_FREE', false, 'detention-access-conflict', 'dual-use site space', true, ['temporary-water assumption']);
$Q($cSpatial, 3, 'NEUTRAL', 'A plan places a noisy communal room between two quiet rooms as a buffer to the street. What additional issue should be checked?', 'Whether the communal room’s own operating hours, sound isolation, access, and adjacency remain compatible with the quiet rooms.', ['A buffer is automatically successful.', 'Noise never crosses a room boundary.', 'Only the street noise matters.', 'Make the communal room louder to mask traffic.'], 'A buffer can introduce a new noise source. Its operation and acoustic separation must be tested, not assumed.', 'acoustic zoning', 'PREREQUISITE_FREE', false, 'buffer-room-operation', 'buffer performance', false, ['buffer as automatic solution']);
$Q($cSpatial, 4, 'PROFESSIONAL', 'A design places bedrooms along the best view but locates kitchens and services on the hot west side without shade or ventilation. What should be reconsidered?', 'Balance view, solar exposure, service buffering, ventilation, privacy, and room sensitivity rather than assigning value from view alone.', ['Keep bedrooms in the view zone regardless of comfort.', 'Put all services on the west edge without environmental testing.', 'Remove the view to simplify planning.', 'Assume orientation affects only the facade.'], 'Room placement should connect value, exposure, use, and environmental response. A view benefit can coexist with a poor thermal decision.', 'program-environment integration', 'PREREQUISITE_FREE', false, 'view-and-west-exposure', 'room placement', true, ['view-only zoning']);
$Q($cSpatial, 3, 'NEUTRAL', 'A campus path network has many intersecting routes but no visible destination or hierarchy. What design move would improve legibility?', 'Establish a readable primary route, landmarks, nodes, and views while retaining secondary paths for local movement.', ['Make every path equally wide and prominent.', 'Remove all secondary paths.', 'Add signs at random intersections.', 'Hide destinations to encourage exploration.'], 'Wayfinding is supported by hierarchy, landmarks, and visual connection. Equal treatment can make a network harder to read.', 'wayfinding network', 'PREREQUISITE_FREE', false, 'path-hierarchy', 'circulation legibility', false, ['equal prominence']);
$Q($cSpatial, 4, 'PROFESSIONAL', 'A community center expansion can either extend the existing public hall or create a separate building across a parking lot. Which comparison is needed?', 'Compare shared identity, accessible connection, phasing, service access, landscape, safety, cost, and future flexibility.', ['Extend automatically because it is closer.', 'Build separately because new buildings are more flexible.', 'Choose from the perspective rendering only.', 'Ignore the parking lot because it is not occupied space.'], 'Both options change public movement and site performance. The decision requires a criterion-based comparison.', 'expansion alternative', 'PREREQUISITE_FREE', false, 'hall-versus-separate-building', 'campus expansion', true, ['distance-only alternative']);
$Q($cSpatial, 3, 'NEUTRAL', 'A sloped roof directs rainwater toward an entry canopy. What site-building relationship should be checked?', 'The roof discharge, canopy drainage, entry safety, overflow, pedestrian movement, and downstream site path.', ['Assume the canopy catches all flow.', 'Move the entry sign instead of the outlet.', 'Ignore discharge because it is outside the wall.', 'Direct water onto the accessible approach.'], 'Roof and site drainage interact at entries. The route must remain safe and the overflow path must be deliberate.', 'entry drainage', 'PREREQUISITE_FREE', false, 'roof-discharge-entry', 'water and arrival', true, ['roof-only drainage']);
$Q($cSpatial, 4, 'PROFESSIONAL', 'A plan uses a large central atrium to orient users, but it increases heat gain, smoke movement, and acoustic transfer. What is the design response?', 'Retain the orientation value only after coordinated environmental, fire, acoustic, and maintenance strategies are developed.', ['Keep the atrium because orientation outweighs performance.', 'Close the atrium with an arbitrary roof.', 'Ignore smoke and sound because the atrium is public.', 'Remove all visual connections.'], 'An atrium is a spatial and technical system. Its benefits must be reconciled with heat, smoke, sound, structure, and operation.', 'atrium systems integration', 'PREREQUISITE_FREE', false, 'atrium-tradeoffs', 'central orientation', true, ['single-benefit atrium']);
$Q($cSpatial, 3, 'NEUTRAL', 'A site analysis finds a desirable view across a neighboring parcel that may be developed later. How should the view affect planning?', 'Treat the view as valuable but uncertain, and test robust alternatives that still work if the neighboring context changes.', ['Assume the view is permanent.', 'Ignore the view because it is uncertain.', 'Orient all rooms to it without other analysis.', 'Build a tall wall to guarantee the view.'], 'Future context is an uncertainty. Robust planning avoids making the entire design depend on an unprotected view.', 'view uncertainty', 'PREREQUISITE_FREE', false, 'unprotected-view', 'future context', false, ['view permanence']);
$Q($cSpatial, 4, 'PROFESSIONAL', 'A proposed courtyard is shaded most of the day by a tall wing, but the program expects outdoor gathering. Which analysis should determine whether the courtyard remains?', 'Test seasonal sun, wind, thermal comfort, rain, use schedule, landscape, and alternative massing before deciding.', ['Keep it because all courtyards are beneficial.', 'Remove it because shade is always bad.', 'Choose from plan geometry without climate analysis.', 'Add artificial lighting as the only outdoor response.'], 'Courtyard performance varies by climate and use. A design decision should test actual environmental and program conditions.', 'courtyard performance', 'PREREQUISITE_FREE', false, 'courtyard-shade-use', 'outdoor comfort', true, ['courtyard universalism']);
$Q($cSpatial, 3, 'NEUTRAL', 'A housing plan groups bedrooms around a noisy shared stair and places living rooms at the private end. What planning issue is most direct?', 'Privacy, noise, circulation, and time-of-use relationships are misaligned and should be re-evaluated.', ['The plan is efficient because rooms are adjacent.', 'Noise is irrelevant inside housing.', 'Living rooms must always be near the entry.', 'Bedrooms can be placed on any circulation edge.'], 'Program adjacency should reflect privacy and noise as well as distance. A shared stair can be a social asset or a conflict depending on treatment.', 'residential zoning', 'PREREQUISITE_FREE', false, 'bedroom-stair-noise', 'privacy zoning', false, ['adjacency distance only']);
$Q($cSpatial, 4, 'PROFESSIONAL', 'A site option places a building on a ridge to capture views but requires major cut and fill and exposes the building to wind. What should guide the choice?', 'Compare view value with earthwork, drainage, erosion, wind, access, structure, landscape, and long-term maintenance.', ['Choose the ridge because views dominate.', 'Reject all ridge placement without studying alternatives.', 'Ignore cut and fill because it is construction scope.', 'Add a wind screen without checking erosion or views.'], 'Ridge placement changes several site systems. The architect should make the trade-offs explicit and test mitigation rather than assume a single value controls.', 'ridge siting', 'PREREQUISITE_FREE', false, 'ridge-view-earthwork', 'ridge alternative', true, ['view-only siting']);
$Q($cSpatial, 3, 'NEUTRAL', 'A service yard is screened from the public street but blocks daylight to adjacent workspaces. Which response is most appropriate?', 'Test screen height, material, openings, orientation, service timing, and workspace daylight together.', ['Make the screen solid and as high as possible.', 'Remove all screening regardless of service needs.', 'Ignore daylight because the yard is separate.', 'Add artificial light without testing the site edge.'], 'Screening trades privacy and service concealment against daylight, airflow, and visual safety. It needs a coordinated solution.', 'service-yard edge', 'PREREQUISITE_FREE', false, 'screening-daylight', 'service and daylight', false, ['screen-only design']);
$Q($cSpatial, 4, 'PROFESSIONAL', 'A master plan reserves an expansion zone but places a permanent utility loop through its center. What should be reconsidered?', 'Reserve the expansion zone and utility strategy together so future construction can connect without unsafe, costly, or disruptive relocation.', ['Keep the loop because future work is uncertain.', 'Remove all utilities from the site.', 'Assume future buildings can bridge the loop.', 'Treat expansion as a rendering note only.'], 'Phasing depends on infrastructure and access. A reserved area is not flexible if essential utilities make it impractical to build.', 'growth planning', 'PREREQUISITE_FREE', false, 'expansion-utility-loop', 'future capacity', true, ['reserved-zone illusion']);
$Q($cSpatial, 3, 'NEUTRAL', 'A public entrance faces a busy street but the lobby has no visual connection to reception or the main vertical route. Which design issue should be addressed?', 'Arrival hierarchy, orientation, visibility, security, and the relationship between entry, reception, and circulation.', ['Add more decorative signage only.', 'Hide reception to reduce visual clutter.', 'Make every route equally prominent.', 'Move the lobby to the service side automatically.'], 'Entry design is a sequence from approach to destination. Users need a legible and safe relationship among threshold, reception, and movement.', 'entry sequence', 'PREREQUISITE_FREE', false, 'lobby-wayfinding', 'arrival sequence', false, ['sign-only solution']);
$Q($cSpatial, 4, 'PROFESSIONAL', 'A renovation removes a corridor to create larger rooms but eliminates the only continuous accessible route between the entry and public spaces. What should be done?', 'Rework the plan to preserve a continuous usable route or provide an equivalent compliant strategy before accepting the area gain.', ['Accept the rooms because area is more valuable.', 'Add a ramp only at the entrance.', 'Assume staff can carry users between rooms.', 'Move the accessible route through storage.'], 'Area gain cannot justify removing a required route. Accessibility is a connected spatial system and must be maintained through the renovation.', 'renovation planning', 'PREREQUISITE_FREE', false, 'corridor-removal-access', 'continuous access', true, ['area over route']);
$Q($cSpatial, 3, 'NEUTRAL', 'A plan separates a public plaza from the building with a level change and a narrow side ramp. What should the designer test?', 'Whether the accessible route is equally legible, direct, safe, comfortable, and connected to the same public destination.', ['The ramp is sufficient because it exists.', 'The stairs can remain the only visible route.', 'The ramp should be hidden to preserve the plaza image.', 'Users can request assistance at the door.'], 'An accessible route should not be an afterthought or a segregated service path. Its experience and connection matter as well as dimensions.', 'inclusive site design', 'PREREQUISITE_FREE', false, 'side-ramp-segregation', 'equitable route', true, ['route exists equals inclusion']);
$Q($cSpatial, 4, 'PROFESSIONAL', 'A campus plan uses a beautiful central axis but the axis crosses a service turning area. What is the best resolution process?', 'Map ceremonial, pedestrian, service, emergency, and delivery movements and revise the axis or timing so critical conflicts are resolved.', ['Keep the axis and let deliveries interrupt events.', 'Move pedestrians to an unmarked route.', 'Remove service access without checking operations.', 'Treat the axis as a graphic line only.'], 'A ceremonial axis is also a working movement system. Its meaning and operation need to be coordinated rather than separated into drawing and reality.', 'campus movement', 'PREREQUISITE_FREE', false, 'axis-service-conflict', 'ceremonial and service movement', true, ['diagram-reality split']);
$Q($cSpatial, 3, 'NEUTRAL', 'A site has a noisy mechanical plant on the prevailing-wind side of an outdoor classroom. Which mitigation should be studied?', 'Source location, distance, barriers, wind, equipment noise, classroom orientation, and operating schedule.', ['Planting alone always blocks noise.', 'Move the classroom without checking wind or views.', 'Ignore equipment because it is outside the classroom.', 'Make the classroom louder to mask the plant.'], 'Noise reaches users through source, path, and receiver. The site strategy should address all three and the time of use.', 'outdoor acoustics', 'PREREQUISITE_FREE', false, 'plant-outdoor-classroom', 'noise source-path-receiver', false, ['planting as universal barrier']);
$Q($cSpatial, 4, 'PROFESSIONAL', 'A compact building plan creates a deep interior with no daylight to shared work areas. Which design alternative should be tested?', 'Compare courtyards, light wells, perimeter reorganization, clerestories, or reduced depth against daylight, heat, structure, and program.', ['Add more artificial lighting and stop analysis.', 'Increase depth because compactness always saves energy.', 'Put windows only in private rooms.', 'Use reflective paint as the complete solution.'], 'Compactness can reduce envelope but worsen daylight and environmental quality. Alternatives should be compared as integrated building strategies.', 'daylight planning', 'PREREQUISITE_FREE', false, 'deep-plan-daylight', 'building depth', true, ['compactness-only optimization']);
$Q($cSpatial, 3, 'NEUTRAL', 'A site entry sequence passes from a public street to a compressed threshold, then opens into a shaded court. What spatial effect is being used?', 'Compression and release to mark arrival and create a legible transition.', ['A random change with no relation to movement.', 'A structural failure caused by a wider court.', 'A code dimension that proves accessibility.', 'A service route that should be hidden.'], 'Changing scale, shade, and view can choreograph arrival. The route still requires independent access and safety checks.', 'spatial sequence', 'PREREQUISITE_FREE', false, 'threshold-compression-release', 'arrival sequence', false, ['sequence as decoration']);
$Q($cSpatial, 4, 'PROFESSIONAL', 'A proposed high-rise site has a narrow public sidewalk, a deep tower setback, and a large private plaza behind a security gate. What should be investigated?', 'How the edge, setback, gate, access, shade, visibility, and public realm connect rather than treating the plaza as isolated private surplus.', ['Accept the private plaza because it increases open area.', 'Maximize the gate and remove sidewalk activity.', 'Move all public movement underground automatically.', 'Ignore the sidewalk because it is outside the lot.'], 'Public experience is shaped by the site edge and the route to the building. Area calculations alone do not establish public benefit.', 'urban edge', 'PREREQUISITE_FREE', false, 'tower-public-edge', 'public realm continuity', true, ['open-area-only']);
$Q($cSpatial, 3, 'NEUTRAL', 'A building’s service spaces are placed on the west side to buffer occupied rooms, but the service equipment produces heat and exhaust there. What should be checked?', 'Whether the buffer remains effective after equipment heat, exhaust, maintenance, wind, and neighboring openings are considered.', ['Service spaces always improve the west facade.', 'Heat and exhaust cannot affect adjacent rooms.', 'The buffer works without ventilation analysis.', 'Move all occupied rooms west to simplify the plan.'], 'A zoning strategy can produce new effects. Equipment and exhaust must be integrated with orientation and adjacent openings.', 'environmental zoning', 'PREREQUISITE_FREE', false, 'service-buffer-exhaust', 'buffer performance', true, ['buffer assumption']);
$Q($cSpatial, 4, 'PROFESSIONAL', 'A site program has more required area than the buildable envelope can hold at one level. Which planning process is most defensible?', 'Compare vertical stacking, phasing, shared-use schedules, reduced scope, and site alternatives against access, egress, services, and user experience.', ['Stack spaces arbitrarily until the area fits.', 'Expand outside the envelope without checking constraints.', 'Reduce accessible rooms first.', 'Choose the tallest form because it holds most area.'], 'Capacity is a program and site problem. A defensible solution balances area with movement, services, safety, phasing, and the brief.', 'capacity planning', 'PREREQUISITE_FREE', false, 'program-over-capacity', 'capacity alternatives', true, ['area-only stacking']);
$Q($cSpatial, 3, 'NEUTRAL', 'A pedestrian route crosses a planted bioswale at a site low point. What design detail should coordinate both functions?', 'A safe crossing with stable surface, overflow behavior, maintenance access, planting tolerance, and continuous route legibility.', ['Pave the whole bioswale and remove its function.', 'Assume pedestrians will avoid water during storms.', 'Use a bridge with no edge or maintenance review.', 'Move the route to the property boundary without checking grade.'], 'Water and movement can coexist through a designed crossing, but the crossing must handle ordinary and storm conditions and remain maintainable.', 'bioswale crossing', 'PREREQUISITE_FREE', false, 'bioswale-pedestrian', 'water and circulation', true, ['single-function landscape']);
$Q($cSpatial, 4, 'PROFESSIONAL', 'A public facility’s main route is direct but passes through a secure staff zone; a longer route follows a public gallery. Which should be selected?', 'Compare security, wayfinding, dignity, accessibility, program, staffing, and route reliability rather than distance alone.', ['Always choose the direct route.', 'Always choose the gallery because it is public.', 'Use the staff route and rely on signs.', 'Separate all circulation even if the facility becomes unusable.'], 'Route selection is a systems decision. The best route satisfies the users and operational constraints under actual conditions.', 'circulation alternative', 'PREREQUISITE_FREE', false, 'direct-versus-gallery', 'route selection', true, ['distance-only selection']);
$Q($cSpatial, 3, 'NEUTRAL', 'A building’s main windows face a beautiful view but overlook a private neighboring yard. What design response is appropriate?', 'Balance view with privacy through sill height, screening, orientation, openings, and the affected users’ expectations.', ['Maximize transparency because views always control.', 'Use opaque walls on every side.', 'Ignore the neighbor because the view is attractive.', 'Use reflective glass without checking glare or privacy.'], 'Views are relational and can impose privacy or glare consequences. Design should mediate both sides of the boundary.', 'view and privacy', 'PREREQUISITE_FREE', false, 'view-privacy-edge', 'view boundary', false, ['view-only design']);
$Q($cSpatial, 4, 'PROFESSIONAL', 'A site plan preserves a historic tree but locates a new foundation where roots and drainage are likely to be disturbed. What should happen?', 'Coordinate arboricultural, structural, excavation, drainage, and construction-protection evidence before finalizing placement.', ['The tree is preserved because it remains visible.', 'Remove roots without assessment.', 'Move drainage into the root zone to shorten pipe length.', 'Ignore construction protection until site work.'], 'Preservation includes the tree’s functional root and water environment. A visible trunk is not proof of protection.', 'site conservation', 'PREREQUISITE_FREE', false, 'tree-root-foundation', 'existing landscape protection', true, ['visible-preservation only']);
$Q($cSpatial, 3, 'NEUTRAL', 'Which site diagram best supports an early design decision?', 'One that overlays constraints, opportunities, users, movement, environmental data, and the relationships being tested.', ['A polished perspective with no site evidence.', 'A property outline with a centered rectangle.', 'A collage of materials unrelated to site conditions.', 'A single north arrow with no scale or use.'], 'Early diagrams should reveal relationships and assumptions. Graphic polish without evidence does not support a defensible placement.', 'site diagram quality', 'PREREQUISITE_FREE', false, 'evidence-based-site-diagram', 'site analysis representation', false, ['rendering as analysis']);
$Q($cSpatial, 4, 'PROFESSIONAL', 'A site has two possible building footprints: one preserves a continuous accessible route but reduces the best view; the other maximizes the view but creates a steep route. What should guide the decision?', 'Compare view value with continuous access, user dignity, grading, cost, and the project’s stated priorities before selecting a footprint.', ['Maximize the view because it is memorable.', 'Choose the route only because access is a technical issue.', 'Ignore both and center the footprint.', 'Use a sign to compensate for the steep route.'], 'The alternatives affect both experience and inclusion. The choice should make the criteria and consequences explicit rather than treating access as secondary.', 'footprint comparison', 'PREREQUISITE_FREE', false, 'view-versus-access', 'site trade-off', true, ['access treated as technical afterthought']);
$Q($cSpatial, 3, 'NEUTRAL', 'A building is placed at the lowest point of a site because the ground is level there. What additional analysis is essential?', 'Surface and subsurface drainage, flood exposure, discharge, foundation protection, access, and long-term maintenance.', ['Level terrain eliminates water risk.', 'Move the drain after construction.', 'Use a deeper basement to solve surface flow.', 'Ignore low points if the roof drains away.'], 'Low points collect water. Levelness is not a substitute for a water and foundation strategy.', 'low-point siting', 'PREREQUISITE_FREE', false, 'low-point-drainage', 'water risk', true, ['level equals safe']);
$Q($cSpatial, 4, 'PROFESSIONAL', 'A design proposal puts public rooms on upper floors to obtain daylight and views but leaves the only large accessible gathering room below grade. What should be reconsidered?', 'Rebalance program, access, daylight, wayfinding, egress, and public identity so the important gathering function is genuinely usable.', ['Accept the arrangement because upper floors have better views.', 'Treat the below-grade room as equivalent without environmental review.', 'Provide access only for staff.', 'Move the room without checking egress or ventilation.'], 'Program hierarchy and environmental quality should not create an inaccessible or inferior public function. The whole route and room use must be tested.', 'public program placement', 'PREREQUISITE_FREE', false, 'public-room-below-grade', 'public accessibility and identity', true, ['view-only programing']);
$Q($cSpatial, 3, 'NEUTRAL', 'A plan uses a courtyard to separate public and private functions. Which additional relationship should be checked?', 'Whether the courtyard supports privacy, visibility, daylight, ventilation, access, maintenance, and the desired degree of social connection.', ['A courtyard always creates privacy.', 'Public and private zones need no visual relationship.', 'Only the courtyard paving matters.', 'Maintenance access can cross every private zone.'], 'A courtyard can buffer or connect depending on its edges and operation. Its performance must be read as a relationship.', 'courtyard zoning', 'PREREQUISITE_FREE', false, 'courtyard-public-private', 'public-private gradient', false, ['courtyard as automatic buffer']);
$Q($cSpatial, 4, 'PROFESSIONAL', 'A site’s prevailing wind supports cross-ventilation in one orientation but drives rain into the primary entrance. Which strategy is most defensible?', 'Separate or mediate entry protection and ventilation openings through massing, thresholds, operable controls, and seasonal operation.', ['Orient everything to the wind regardless of rain.', 'Close all openings permanently.', 'Ignore the entry because ventilation is more important.', 'Use a decorative canopy without tracing wind-driven rain.'], 'Environmental strategies can conflict. A coordinated response protects arrival while preserving useful airflow under actual conditions.', 'wind and rain response', 'PREREQUISITE_FREE', false, 'wind-rain-conflict', 'seasonal environmental response', true, ['single-climate strategy']);
$Q($cSpatial, 3, 'NEUTRAL', 'A site program includes waste collection, deliveries, pedestrians, bicycles, and emergency access. What planning representation is most useful?', 'A time-aware movement diagram showing users, vehicles, conflict points, control, and required clear routes.', ['A single arrow labeled circulation.', 'Only a parking count.', 'A perspective with no movement paths.', 'A diagram that excludes emergency access to keep it simple.'], 'Different movements can share or conflict at different times. Mapping flows and constraints reveals where the site needs separation or management.', 'site movement analysis', 'PREREQUISITE_FREE', false, 'multi-modal-site-flow', 'site circulation map', true, ['single-arrow circulation']);
$Q($cSpatial, 4, 'PROFESSIONAL', 'A proposed civic plaza is surrounded by blank walls and has one narrow entry. Which design question should be answered before adding furniture?', 'Whether the edges, entrances, visibility, program, shade, and routes make the plaza inviting and safe for its intended users.', ['Furniture will fix every edge problem.', 'Add more chairs without checking access.', 'Keep blank walls because they reduce maintenance.', 'Move the entry behind service spaces.'], 'Furniture cannot compensate for poor edge, access, and visibility relationships. Public-space design begins with the spatial system.', 'public plaza analysis', 'PREREQUISITE_FREE', false, 'plaza-edge-activation', 'public realm', true, ['furniture as complete solution']);
$Q($cSpatial, 3, 'NEUTRAL', 'A site’s existing road is at a grade that would require a steep driveway to reach a proposed basement garage. What should the designer compare?', 'Garage level, entry location, grading, pedestrian separation, drainage, retaining, structure, and alternative mobility strategies.', ['Use the steepest driveway because it is shortest.', 'Ignore pedestrian movement because the garage is vehicular.', 'Cut the road without checking the authority or drainage.', 'Put all site circulation on the driveway.'], 'Vehicle access is part of site grading and safety. The best solution balances the garage program with people, water, and construction consequences.', 'site access', 'PREREQUISITE_FREE', false, 'basement-driveway-grade', 'vehicle and pedestrian access', true, ['vehicle-only analysis']);
$Q($cSpatial, 4, 'PROFESSIONAL', 'A building’s main public rooms face an internal service court because the street edge has poor solar exposure. What alternative should be tested?', 'Use the street edge with shading, glazing, threshold, and program adjustments if it improves public identity and access without unacceptable environmental cost.', ['Put public rooms at the street regardless of performance.', 'Keep the service court because service is always more important.', 'Ignore public identity in site planning.', 'Use reflective glazing as the only remedy.'], 'Public identity and environmental response can be reconciled through design alternatives. The plan should not treat one edge attribute as absolute.', 'street edge comparison', 'PREREQUISITE_FREE', false, 'public-service-frontage', 'public edge and climate', true, ['single-edge attribute']);
$Q($cSpatial, 3, 'NEUTRAL', 'A site is in a hot climate with frequent intense rain. Which combination is most likely to need coordinated study?', 'Shade, roof and ground drainage, protected openings, ventilation, material durability, and outdoor route comfort.', ['Only wall color and interior furniture.', 'Only mechanical cooling with no site response.', 'Only rainfall because heat is unrelated.', 'Only open windows because rain is temporary.'], 'Heat and rain interact with shade, openings, drainage, material, and comfort. A climate response is a coordinated system.', 'climate synthesis', 'PREREQUISITE_FREE', false, 'hot-wet-site-response', 'climate integration', false, ['single-hazard design']);
$Q($cSpatial, 4, 'PROFESSIONAL', 'A master plan phases three buildings around a future pedestrian spine, but phase one forces utilities and deliveries through the future spine. What should be revised?', 'Define a workable interim route and utility strategy that protects future construction, access, safety, and public experience.', ['Ignore phase one because the final plan is attractive.', 'Build the future spine first without checking operations.', 'Place temporary utilities permanently.', 'Remove the pedestrian spine from the plan.'], 'Phasing is a sequence of real conditions. Interim work must not make the intended later system unsafe or prohibitively disruptive.', 'phasing strategy', 'PREREQUISITE_FREE', false, 'interim-spine-conflict', 'phased site operation', true, ['final-state-only planning']);
$Q($cSpatial, 3, 'NEUTRAL', 'A site has a view corridor to a mountain but a utility easement crosses the corridor. Which design response is appropriate?', 'Map the easement and view together, then test building mass, landscape, access, and infrastructure alternatives.', ['Build through the easement because views are more important.', 'Ignore the view because utilities always control.', 'Treat the easement as an invisible line with no design effect.', 'Move all utilities without checking authority or maintenance.'], 'Views and infrastructure both shape the buildable and experiential site. Their relationship must be resolved with evidence.', 'view and easement', 'PREREQUISITE_FREE', false, 'view-utility-easement', 'view corridor', true, ['single-layer site analysis']);
$Q($cSpatial, 4, 'PROFESSIONAL', 'A design uses a sunken courtyard to provide quiet outdoor space, but the courtyard is below the site’s drainage path. What must be solved first?', 'Provide a robust water, overflow, waterproofing, access, and maintenance strategy before relying on the courtyard for use.', ['Plant the courtyard and assume soil absorbs stormwater.', 'Treat the low point as an advantage without drainage.', 'Add a pump without backup or maintenance access.', 'Block all site drainage toward the courtyard with an unverified curb.'], 'A sunken space can collect water. Its use depends on a complete drainage and operational strategy, not only on its spatial enclosure.', 'sunken courtyard', 'PREREQUISITE_FREE', false, 'sunken-courtyard-water', 'courtyard drainage', true, ['low point as amenity only']);
$Q($cSpatial, 3, 'NEUTRAL', 'A public building uses a monumental stair as the visual focus, but the accessible route begins around a service corner. What design principle is at issue?', 'Accessibility should be integrated into the primary arrival experience rather than relegated to a hidden secondary path.', ['A visible stair automatically makes the building inclusive.', 'A service corner is acceptable for every user.', 'Access is only a technical annotation.', 'Move the main stair to the service side.'], 'An equitable entrance sequence treats accessible movement as part of the architecture and public identity, subject to current requirements.', 'inclusive arrival', 'PREREQUISITE_FREE', false, 'monumental-stair-route', 'equitable entry', true, ['secondary access segregation']);
$Q($cSpatial, 4, 'PROFESSIONAL', 'A housing courtyard is visually open to the street but bedrooms face the public edge with no privacy gradient. What should be adjusted?', 'Use thresholds, landscape, level, openings, and program zoning to create a calibrated public-to-private transition.', ['Make every edge fully transparent.', 'Place all bedrooms at the most exposed edge.', 'Close the courtyard entirely.', 'Use signs to define privacy.'], 'Privacy is spatial and operational. A gradient can preserve connection without exposing every private room directly.', 'privacy gradient', 'PREREQUISITE_FREE', false, 'housing-privacy-gradient', 'public-private transition', false, ['transparent equals connected']);
$Q($cSpatial, 3, 'NEUTRAL', 'A site diagram labels an area “green space” but does not show soil depth, shade, drainage, users, or maintenance. What is missing?', 'Evidence that the area can perform the intended ecological, social, hydrologic, and operational functions.', ['Nothing; a green label is enough.', 'Only a brighter green graphic.', 'A building footprint inside the area.', 'A decorative plant list with no site data.'], 'Landscape function is not established by color or label. The site diagram should make the intended performance and constraints visible.', 'landscape planning', 'PREREQUISITE_FREE', false, 'green-space-evidence', 'landscape performance', false, ['green label as function']);
$Q($cSpatial, 4, 'PROFESSIONAL', 'A site alternative minimizes cut and fill but creates a long, indirect accessible route and removes a shaded gathering area. How should it be evaluated?', 'Compare earthwork and cost with route dignity, shade, program, drainage, landscape, and user experience.', ['Choose it because cut and fill is the only objective.', 'Reject it because indirect routes are always bad.', 'Ignore the gathering area as nontechnical.', 'Use a vehicle route as the accessible route.'], 'Earthwork is one criterion among several. A site alternative should be judged against the project’s users and environmental systems.', 'site alternative', 'PREREQUISITE_FREE', false, 'cut-fill-access-shade', 'earthwork trade-off', true, ['construction-only optimization']);
$Q($cSpatial, 3, 'NEUTRAL', 'A building lobby receives afternoon sun and has a polished floor. Which design concern should be checked?', 'Glare, reflected heat, visual comfort, slip risk if wet, shading, finishes, and the arrival sequence.', ['Polished floors are always appropriate at entrances.', 'Sunlight affects only energy use.', 'A darker floor removes all glare and slip risk.', 'Entry finishes need no weather or maintenance review.'], 'Arrival surfaces and light interact with comfort, visibility, safety, and maintenance. The response should address the whole threshold.', 'lobby environmental response', 'PREREQUISITE_FREE', false, 'lobby-glare-slip', 'arrival comfort and safety', true, ['finish-only decision']);
$Q($cSpatial, 4, 'PROFESSIONAL', 'A campus expansion can share a central dining hall or build smaller dining spaces near each residence. What comparison is most useful?', 'Compare travel, social interaction, service logistics, capacity, phasing, accessibility, schedule, and future flexibility.', ['Choose centralization because it is always efficient.', 'Choose distributed spaces because distance never matters.', 'Compare only gross floor area.', 'Ignore service deliveries because dining is social.'], 'Central and distributed models produce different user and operational effects. A criterion-based comparison should make those visible.', 'campus program comparison', 'PREREQUISITE_FREE', false, 'central-versus-distributed-dining', 'program distribution', true, ['area-only distribution']);
$Q($cSpatial, 3, 'NEUTRAL', 'A proposed plaza has a strong axial view but the axis points directly into a service yard. Which move may preserve the spatial effect?', 'Frame or redirect the view toward a meaningful public destination while separating or screening service activity.', ['Keep the view because an axis cannot change.', 'Hide the entire plaza behind a wall.', 'Remove all service access without checking operations.', 'Use an ornamental graphic to conceal the conflict.'], 'An axis is a relationship of movement and view. It can be adjusted while preserving hierarchy and public legibility.', 'axis and site edge', 'PREREQUISITE_FREE', false, 'axis-service-view', 'view and service', false, ['axis as fixed line']);
$Q($cSpatial, 4, 'PROFESSIONAL', 'A building’s only daylight courtyard is also proposed for emergency assembly. What should be tested?', 'Daylight, occupancy, egress, fire access, landscape, drainage, everyday use, and emergency operation as coordinated conditions.', ['Assign the courtyard to assembly without checking capacity.', 'Remove daylight because emergency use is more important.', 'Assume everyday furniture can remain during an emergency.', 'Treat emergency assembly as outside architecture.'], 'A space can have multiple roles only when its ordinary and emergency conditions are compatible and supported by evidence.', 'multi-use courtyard', 'PREREQUISITE_FREE', false, 'courtyard-assembly', 'dual-use space', true, ['single-use assumption']);
$Q($cSpatial, 3, 'NEUTRAL', 'Which design response best handles a noisy urban edge beside a quiet interior court?', 'Place robust or service uses at the edge, use enclosure and landscape strategically, and protect the court’s acoustic and environmental function.', ['Open the quiet court directly to the noise source.', 'Put bedrooms at the street with no buffer.', 'Use a single wall without checking openings and flanking.', 'Assume interior planting absorbs all urban noise.'], 'Massing, program, enclosure, and landscape can work together, but no single layer guarantees quiet. The court’s intended use controls the target.', 'urban edge response', 'PREREQUISITE_FREE', false, 'noise-edge-court', 'urban acoustic buffer', false, ['single-wall guarantee']);
$Q($cSpatial, 4, 'PROFESSIONAL', 'A site master plan proposes a future pedestrian bridge but phase one has no accessible route across the existing grade change. What is the correct phasing response?', 'Provide a usable current route and design the future bridge so it connects without creating a second inaccessible dependency.', ['Wait for the bridge before opening phase one.', 'Use stairs now and promise the bridge later.', 'Make the future bridge decorative only.', 'Move the destination to avoid accessibility.'], 'Phasing must work in each occupied state. Future infrastructure cannot excuse present exclusion.', 'accessible phasing', 'PREREQUISITE_FREE', false, 'future-bridge-access', 'phase-by-phase access', true, ['future solution excuse']);
$Q($cSpatial, 3, 'NEUTRAL', 'A site plan uses a row of trees to shade a walkway but places the trees where roots will narrow the accessible clear path. What should be adjusted?', 'Coordinate tree species, soil volume, root barriers, canopy, clear path, drainage, and maintenance rather than deleting either function.', ['Keep the row and accept the narrowed route.', 'Remove all trees regardless of shade value.', 'Use any tree and trim it after installation.', 'Pave over roots to preserve width.'], 'Landscape and access are integrated. Planting design must anticipate growth and root effects on a usable route.', 'landscape-access coordination', 'PREREQUISITE_FREE', false, 'tree-root-clear-path', 'shade and access', true, ['planting afterthought']);
$Q($cSpatial, 4, 'PROFESSIONAL', 'A project’s best outdoor area is on a roof, but the roof has no clear accessible route, guard strategy, drainage overflow, or maintenance access. What should happen?', 'Treat the roof terrace as an integrated occupied space and resolve route, edge safety, water, structure, operation, and applicable requirements.', ['Advertise it as amenity immediately.', 'Add furniture and resolve safety later.', 'Use a staff-only route for public events.', 'Assume the roof is safe because it is flat.'], 'An occupied roof is not just leftover area. The complete route and life-cycle systems must support the intended use.', 'roof terrace', 'PREREQUISITE_FREE', false, 'roof-terrace-completeness', 'occupied roof', true, ['flat equals safe']);
$Q($cSpatial, 3, 'NEUTRAL', 'A plan uses a central stair to connect levels but places the lift in a remote service core. Which design question should be asked?', 'Whether vertical circulation hierarchy, accessibility, wayfinding, fire, and daily user routes are integrated rather than segregated.', ['The central stair is sufficient for every user.', 'A remote lift automatically satisfies inclusion.', 'Move the lift without checking structure or services.', 'Hide all vertical circulation to simplify the plan.'], 'Vertical circulation is a spatial system. The accessible route should be legible and connected to the same destinations, subject to current requirements.', 'vertical circulation', 'PREREQUISITE_FREE', false, 'stair-lift-separation', 'vertical access', true, ['remote lift as equivalent']);
$Q($cSpatial, 4, 'PROFESSIONAL', 'A site layout creates a continuous public promenade but requires pedestrians to cross three service driveways. What should be evaluated?', 'Crossing frequency, visibility, vehicle speed, timing, grades, route alternatives, emergency access, and user safety.', ['The promenade is successful because it is continuous.', 'Service driveways have no pedestrian effect.', 'Add a sign at each crossing and stop analysis.', 'Remove all service access without operational review.'], 'Continuity and conflict must be considered together. A route can be visually continuous yet operationally unsafe.', 'promenade safety', 'PREREQUISITE_FREE', false, 'promenade-service-crossings', 'pedestrian safety', true, ['continuity-only planning']);
$Q($cSpatial, 3, 'NEUTRAL', 'A site has a strong afternoon breeze but the proposed courtyard is enclosed by tall solid walls. What environmental effect should be tested?', 'Whether the walls improve shade and protection or instead prevent useful ventilation and trap heat.', ['Enclosure always improves comfort.', 'Wind has no effect in courtyards.', 'Remove all walls without checking privacy.', 'Add mechanical fans without studying massing.'], 'Courtyard microclimate depends on geometry, wind, shade, material, and use. Enclosure can both protect and reduce ventilation.', 'courtyard microclimate', 'PREREQUISITE_FREE', false, 'courtyard-wind-enclosure', 'microclimate', false, ['enclosure always beneficial']);
$Q($cSpatial, 4, 'PROFESSIONAL', 'A residential master plan maximizes unit count by minimizing shared open space, but the remaining paths are shaded poorly and lack places to rest. What should be reconsidered?', 'Balance unit yield with circulation, shade, rest, social use, drainage, landscape, and equitable everyday access.', ['Maximize count because open space is residual.', 'Add benches after construction without shade.', 'Remove paths to create more units.', 'Treat rest and shade as amenities outside planning.'], 'Repeat resistance and liveability depend on the common realm as well as unit count. The design should compare capacity and user performance.', 'housing site planning', 'PREREQUISITE_FREE', false, 'unit-yield-open-space', 'housing capacity', true, ['yield-only optimization']);
$Q($cSpatial, 3, 'NEUTRAL', 'A site boundary is adjacent to a future road widening shown in a planning document. What should the building placement consider?', 'The current and credible future right-of-way, access, setbacks or buffers, utilities, noise, and uncertainty in the planning information.', ['Ignore the future road because it is not built.', 'Set the building on the boundary without checking authority.', 'Treat the planning document as guaranteed construction.', 'Place all sensitive rooms at the future road edge.'], 'Future infrastructure can change site access and exposure. The design should verify status and make a robust allowance without overstating certainty.', 'future site context', 'PREREQUISITE_FREE', false, 'future-road-widening', 'right-of-way uncertainty', true, ['future plan as certainty']);
$Q($cSpatial, 4, 'PROFESSIONAL', 'A civic building’s public route is shaded by a canopy that blocks a fire-service sightline and traps smoke at the entrance. What should be coordinated?', 'Canopy geometry, fire access, smoke movement, weather protection, visibility, and pedestrian operation as one threshold system.', ['Keep the canopy because shade is always beneficial.', 'Remove it without checking heat and rain.', 'Treat smoke as an interior-only issue.', 'Use a decorative screen to hide the conflict.'], 'Thresholds have multiple performance roles. The response must preserve safety while retaining environmental and user benefits where possible.', 'entrance canopy', 'PREREQUISITE_FREE', false, 'canopy-fire-sightline', 'threshold integration', true, ['single-benefit canopy']);
$Q($cSpatial, 3, 'NEUTRAL', 'A plan places toilets far from a public assembly room to make the main plan symmetrical. What planning criterion has been neglected?', 'Functional adjacency and convenient, legible access for the users of the assembly room.', ['Symmetry is always the strongest criterion.', 'Toilets have no relationship to program.', 'Long routes improve every public plan.', 'Only the facade determines adjacency.'], 'Program planning begins with activities and user relationships. Symmetry can be a secondary ordering device, not a substitute for function.', 'functional adjacency', 'PREREQUISITE_FREE', false, 'toilet-assembly-adjacency', 'program relationship', false, ['symmetry over function']);
$Q($cSpatial, 4, 'PROFESSIONAL', 'A design relocates the service yard to preserve a public view but now requires waste carts to pass through the lobby. What is the proper evaluation?', 'Compare the view with service hygiene, timing, separation, odor, security, access, and alternate service routes.', ['Preserve the view regardless of service impact.', 'Accept lobby carts because the route is short.', 'Move the view to a rendering and stop analysis.', 'Assume waste operations can be improvised.'], 'A site decision can create operational conflicts. Public view and service performance should be compared as project criteria.', 'service and view', 'PREREQUISITE_FREE', false, 'service-yard-view', 'service operations', true, ['public view only']);
$Q($cSpatial, 3, 'NEUTRAL', 'A site plan shows a rain garden but no overflow route for storms that exceed its design assumption. What is missing?', 'A safe exceedance and maintenance strategy that prevents damage and protects adjacent routes and buildings.', ['The rain garden is complete because it is planted.', 'Overflow is unnecessary in a landscape.', 'Direct excess water to the foundation.', 'Use a sign to warn users instead of drainage.'], 'Water systems need a boundary condition for exceedance. The site must fail safely when the design assumption is exceeded.', 'stormwater resilience', 'PREREQUISITE_FREE', false, 'rain-garden-overflow', 'exceedance path', true, ['design-event-only']);
$Q($cSpatial, 4, 'PROFESSIONAL', 'A building massing option reduces facade area but creates a large shaded north court with poor winter use and limited views. What should be compared?', 'Envelope efficiency, daylight, solar access, wind, outdoor use, views, energy, and the program’s seasonal needs.', ['Choose the option with the least facade automatically.', 'Reject compactness because courtyards are always bad.', 'Ignore outdoor use because it is not enclosed.', 'Use brighter paving as the only environmental response.'], 'Massing affects several performance systems. Envelope efficiency is one criterion, not a complete decision.', 'massing comparison', 'PREREQUISITE_FREE', false, 'compact-massing-court', 'massing and microclimate', true, ['envelope-only metric']);
$Q($cSpatial, 3, 'NEUTRAL', 'A pedestrian route crosses a loading area only during a two-hour delivery window. Which design response is strongest?', 'Use reliable time separation or physical control with clear alternative routing and emergency conditions verified.', ['Assume users will notice trucks.', 'Keep the overlap because it is brief.', 'Close the pedestrian route without providing an alternative.', 'Remove delivery controls and rely on courtesy.'], 'Short duration does not eliminate conflict. Shared operation requires an explicit, reliable control and a safe route at all times.', 'time-based circulation', 'PREREQUISITE_FREE', false, 'delivery-window-route', 'time separation', true, ['brief equals safe']);
$Q($cSpatial, 4, 'PROFESSIONAL', 'A public library plan groups children’s rooms near the service/loading edge for easy deliveries, but the rooms have poor daylight and a noisy route. What should be tested?', 'Compare service efficiency with child safety, daylight, noise, supervision, access, and alternative receiving relationships.', ['Keep the rooms because deliveries are efficient.', 'Move loading into the reading room.', 'Ignore daylight because children are indoors.', 'Use a sign to separate children from trucks.'], 'Program placement needs both service and user evidence. A better receiving relationship may preserve operations without sacrificing the public rooms.', 'program and service', 'PREREQUISITE_FREE', false, 'children-loading-edge', 'user and service adjacency', true, ['service-only adjacency']);
$Q($cSpatial, 3, 'NEUTRAL', 'A design uses a covered arcade to provide shade, but the arcade is narrow at columns and conflicts with door swings. What should be checked?', 'The continuous clear route, door maneuvering, structural rhythm, shade performance, and usable width under actual operation.', ['The arcade is successful because it is covered.', 'Columns can overlap the route if they are decorative.', 'Door swings do not affect covered paths.', 'Only the roof projection matters.'], 'A covered route is a circulation and structure system. Its clear path and doors must remain usable, not just shaded.', 'arcade circulation', 'PREREQUISITE_FREE', false, 'arcade-clear-route', 'covered circulation', true, ['shade equals usability']);
$Q($cSpatial, 4, 'PROFESSIONAL', 'A new building is planned next to a historic facade, and the proposed height blocks the facade’s principal view from the public street. What should guide massing?', 'Document the view and significance, test height/setback alternatives, and balance program with the public and heritage consequence.', ['Use the maximum height because zoning permits it.', 'Ignore the view because the facade remains standing.', 'Copy the historic height without checking program.', 'Hide the conflict with landscaping only.'], 'Massing changes public perception and heritage context. A permitted envelope does not automatically settle the design judgment.', 'heritage context massing', 'PREREQUISITE_FREE', false, 'historic-view-massing', 'contextual massing', true, ['entitlement equals design']);
$Q($cSpatial, 3, 'NEUTRAL', 'A site plan locates a transformer beside an outdoor seating area because the electrical run is short. What additional effects should be considered?', 'Noise, heat, security, maintenance, clearances, visual impact, emergency access, and user comfort.', ['Short electrical distance is sufficient.', 'Transformers have no site effect.', 'Screen it with any hedge regardless of access.', 'Move seating after installation.'], 'Utility placement affects users and maintenance as well as cable length. A coordinated site decision considers the complete operational interface.', 'utility site placement', 'PREREQUISITE_FREE', false, 'transformer-seating', 'utility and public realm', true, ['shortest-run optimization']);
$Q($cSpatial, 4, 'PROFESSIONAL', 'A design places a rainwater storage tank under a public plaza, but access for inspection requires closing the plaza and no overflow is shown. What should be resolved?', 'Maintenance access, structural and waterproofing interfaces, safety, overflow, operation, and acceptable closure conditions.', ['Accept it because the tank is hidden.', 'Ignore inspection because storage is passive.', 'Discharge overflow into the plaza.', 'Move the tank without checking the water strategy.'], 'Concealment does not remove maintenance or failure conditions. Infrastructure under public space must be accessible and fail safely.', 'water infrastructure', 'PREREQUISITE_FREE', false, 'tank-under-plaza', 'hidden infrastructure', true, ['hidden equals resolved']);
$Q($cSpatial, 3, 'NEUTRAL', 'Which relationship should a bubble diagram show before room dimensions are fixed?', 'Adjacency, separation, sequence, privacy, service, user, and circulation relationships.', ['Exact wall thicknesses only.', 'Final furniture brands.', 'Finished material colors.', 'Construction tolerances for every joint.'], 'Early programming benefits from relationships before detailed dimensions. Later drawings resolve size, structure, materials, and code evidence.', 'programming method', 'PREREQUISITE_FREE', false, 'bubble-diagram-relations', 'program diagram', false, ['premature detail']);
$Q($cSpatial, 4, 'PROFESSIONAL', 'A design option gives every office an exterior window but places the most frequently used shared rooms in a dark interior. What should the program review ask?', 'Whether daylight, use frequency, privacy, ventilation, and shared-space value are balanced rather than allocated by room type alone.', ['Exterior windows always justify the layout.', 'Shared rooms need no environmental quality.', 'Move all shared rooms outside the building.', 'Use a skylight without checking glare or heat.'], 'Daylight and views should follow use and performance priorities. A room-by-room rule can create a poorer overall program.', 'program daylight allocation', 'PREREQUISITE_FREE', false, 'office-shared-space-daylight', 'daylight and program', true, ['window-count allocation']);
$Q($cSpatial, 3, 'NEUTRAL', 'A site is bordered by a busy road on one side and a quiet park on the other. Which planning response is most defensible?', 'Place noise-sensitive and public outdoor functions toward the park where appropriate, while preserving access, safety, and ecological constraints.', ['Put every function on the road edge for visibility.', 'Ignore the park because it is outside the lot.', 'Use the park edge for service without checking privacy.', 'Place bedrooms beside the road without acoustic strategy.'], 'Adjacent context can guide zoning, but the response must also consider access, views, security, and the park’s own constraints.', 'contextual zoning', 'PREREQUISITE_FREE', false, 'road-park-edge', 'adjacent context', false, ['visibility-only frontage']);
$Q($cSpatial, 4, 'PROFESSIONAL', 'A site alternative places all parking at grade, reducing building height but removing the only shaded public court. What should be compared?', 'Parking demand and access with shade, public space, heat, stormwater, landscape, and future mobility assumptions.', ['Choose surface parking because it is familiar.', 'Preserve the court without testing parking operation.', 'Ignore mobility because parking is separate.', 'Pave the entire site and add shade later.'], 'Parking is a site system with environmental and public-realm consequences. The alternative needs explicit criteria and future assumptions.', 'parking and public realm', 'PREREQUISITE_FREE', false, 'parking-court-tradeoff', 'site resource allocation', true, ['parking-only planning']);
$Q($cSpatial, 3, 'NEUTRAL', 'A public building’s entrance is visible but the approach crosses a dark, narrow passage at night. What should be improved?', 'Lighting, width, visibility, active edges, route choice, security, and maintenance should be coordinated along the approach.', ['Add a larger entry sign at the destination.', 'Assume users will use phone lights.', 'Move the entrance without studying the site.', 'Close the passage and provide no alternative.'], 'Arrival safety is a route condition, not only an entrance condition. Visibility and maintenance support wayfinding and public confidence.', 'night arrival', 'PREREQUISITE_FREE', false, 'dark-approach', 'route safety', true, ['destination-only safety']);
$Q($cSpatial, 4, 'PROFESSIONAL', 'A project wants a car-free plaza but needs emergency, maintenance, and accessible drop-off access. Which design strategy is strongest?', 'Define controlled access windows and routes that preserve a pedestrian public realm while maintaining reliable emergency and inclusive operation.', ['Ban every vehicle regardless of need.', 'Keep all vehicles in the plaza at all times.', 'Use removable barriers without an operating plan.', 'Move accessible drop-off to an unprotected service lane.'], 'Car-free public space requires an operational strategy for necessary access. Control and timing can reconcile competing uses when reliable.', 'car-free plaza', 'PREREQUISITE_FREE', false, 'car-free-emergency-access', 'managed access', true, ['absolute vehicle ban']);
$Q($cSpatial, 3, 'NEUTRAL', 'A site plan shows a building footprint but no place for construction staging. Why can this matter at design stage?', 'Staging affects access, neighbors, trees, drainage, safety, phasing, and the ability to build without damaging permanent work.', ['Construction staging is never an architectural concern.', 'Place staging on the future accessible route.', 'Assume the contractor can use any neighboring land.', 'Add staging only after the building is complete.'], 'Constructability and site operation can influence footprint and phasing. Early consideration prevents permanent design decisions from blocking safe work.', 'construction site planning', 'PREREQUISITE_FREE', false, 'construction-staging', 'site logistics', false, ['construction afterthought']);
$Q($cSpatial, 4, 'PROFESSIONAL', 'A dense site cannot accommodate both a broad planted setback and the required service turning path. What should the architect do?', 'Test shared or separated edge strategies, service timing, planting depth, turning geometry, safety, and the project’s priorities.', ['Remove planting automatically.', 'Keep planting and let trucks reverse through pedestrians.', 'Assume the turning path can be smaller without checking.', 'Treat service as a contractor problem.'], 'Site capacity is a conflict among functions. A coordinated alternative may use timing or a different edge rather than sacrificing one requirement blindly.', 'site capacity conflict', 'PREREQUISITE_FREE', false, 'setback-service-turning', 'edge capacity', true, ['function sacrificed blindly']);
$Q($cSpatial, 3, 'NEUTRAL', 'A campus uses a covered walkway between buildings, but the route becomes a wind tunnel at the corner. What should be tested?', 'Massing, opening, canopy, planting, wind, rain, shade, and route comfort at the connection.', ['Coverage guarantees comfort.', 'Close all openings regardless of fire and access.', 'Remove the walkway without checking rain exposure.', 'Ignore the corner because the route is short.'], 'Covered connections can intensify wind and weather at corners. Microclimate should be tested at the actual route, not inferred from coverage.', 'covered connection', 'PREREQUISITE_FREE', false, 'wind-tunnel-walkway', 'campus route comfort', true, ['coverage as comfort']);
$Q($cSpatial, 4, 'PROFESSIONAL', 'A public building’s landscape plan uses low planting along a security edge, but the planting will mature into blind spots. What should be addressed?', 'Mature height, sightlines, maintenance, lighting, access, biodiversity, and security operations together.', ['Choose planting from the nursery size only.', 'Remove all planting from security edges.', 'Let mature planting obscure the edge.', 'Add cameras without checking sightlines.'], 'Landscape changes over time and can affect supervision and security. The design should account for mature conditions and maintenance.', 'security landscape', 'PREREQUISITE_FREE', false, 'mature-planting-sightline', 'landscape and security', true, ['initial-size-only']);
$Q($cSpatial, 3, 'NEUTRAL', 'A plan makes a public lobby pass through a sequence of increasingly private spaces before reaching reception. What is the likely planning problem?', 'The arrival hierarchy is reversed, making orientation, welcome, and public access less legible.', ['Privacy always improves public arrival.', 'Reception should be hidden from visitors.', 'A longer route is always more ceremonial.', 'Public and private need no spatial gradient.'], 'A public entrance should make destination and access legible. A sequence can be rich without forcing users through private territory first.', 'arrival hierarchy', 'PREREQUISITE_FREE', false, 'public-private-reversed', 'public arrival', false, ['privacy over legibility']);
$Q($cSpatial, 4, 'PROFESSIONAL', 'A site plan preserves a watercourse but places a bridge where flood debris would likely accumulate. What should be evaluated?', 'Hydrology, debris, structural span, access, maintenance, ecology, flood behavior, and safe crossing conditions.', ['Keep the bridge because the crossing is shortest.', 'Assume a small bridge is outside flood analysis.', 'Remove the watercourse to simplify the site.', 'Add a railing without checking flow.'], 'Crossings interact with water and debris. The site strategy must respect the watercourse and provide a safe, maintainable connection.', 'watercourse crossing', 'PREREQUISITE_FREE', false, 'bridge-flood-debris', 'hydrologic crossing', true, ['shortest crossing bias']);
$Q($cSpatial, 3, 'NEUTRAL', 'A site plan locates a waste enclosure beside the main entrance because it is near the service lane. Which additional design criteria are needed?', 'Odor, hygiene, screening, ventilation, collection movement, user separation, maintenance, and public perception.', ['Proximity alone is sufficient.', 'Waste has no relation to entrance design.', 'Screen it with an unventilated solid box.', 'Move it into the accessible lobby route.'], 'Waste handling is an operational and public-realm interface. Service convenience must be balanced with health, access, and dignity.', 'waste enclosure', 'PREREQUISITE_FREE', false, 'waste-entrance', 'service and public edge', true, ['service proximity only']);
$Q($cSpatial, 4, 'PROFESSIONAL', 'A design option has a smaller footprint but creates a long shaded north-facing circulation spine with no active edges. What should be compared?', 'Footprint, daylight, wayfinding, activity, energy, social safety, program adjacency, and opportunities for borrowed light or active edges.', ['Select the smaller footprint automatically.', 'Accept the spine because circulation needs no quality.', 'Add signs without changing the spatial condition.', 'Make the spine longer to improve efficiency.'], 'A compact footprint can create an inferior internal realm. Circulation is an occupied architectural space with environmental and social performance.', 'compact plan analysis', 'PREREQUISITE_FREE', false, 'deep-circulation-spine', 'circulation quality', true, ['small footprint as complete success']);
$Q($cSpatial, 3, 'NEUTRAL', 'A site’s primary pedestrian route is separated from the building by a broad vehicle drop-off loop. Which design question should be asked?', 'Whether the drop-off supports safe, accessible, legible arrival without weakening the direct connection between people and building.', ['Vehicle movement should always dominate the forecourt.', 'Pedestrians can cross anywhere in the loop.', 'Move all pedestrian access to the rear.', 'Add a canopy without checking crossing conflicts.'], 'Drop-off geometry shapes the public threshold. The design should coordinate vehicles and people rather than treating them as independent diagrams.', 'drop-off planning', 'PREREQUISITE_FREE', false, 'dropoff-pedestrian', 'arrival and vehicles', true, ['vehicle forecourt bias']);
$Q($cSpatial, 4, 'PROFESSIONAL', 'A phased project will occupy the first building while later work occurs next to it. Which site-planning issue should be resolved before phase-one opening?', 'Safe separation, accessible routes, emergency access, utilities, noise, dust, wayfinding, and protection of occupied users during later work.', ['Open phase one because later work is temporary.', 'Use the occupied lobby for construction access.', 'Remove all signs so phasing is invisible.', 'Assume users can navigate construction barriers.'], 'Occupied construction changes the site and building operation. The phase plan must protect users and maintain required routes and systems.', 'occupied phasing', 'PREREQUISITE_FREE', false, 'occupied-phase-safety', 'construction and users', true, ['temporary equals harmless']);
$Q($cSpatial, 3, 'NEUTRAL', 'A building’s main common room opens to a shaded courtyard but has no visual connection to the entry. What could improve orientation?', 'Frame a view or route connection from arrival to the common room while preserving privacy and environmental control.', ['Remove all enclosure to make the room visible.', 'Add a sign only at the room door.', 'Move the common room to the street automatically.', 'Keep the disconnection because courtyards should be hidden.'], 'Wayfinding can use view, sequence, and thresholds. Visibility should be calibrated, not maximized without privacy or climate consideration.', 'common-space orientation', 'PREREQUISITE_FREE', false, 'courtyard-common-room-view', 'visual connection', false, ['sign-only orientation']);
$Q($cSpatial, 4, 'PROFESSIONAL', 'A site’s best solar exposure is also the location of an existing protected tree canopy. What should the design process do?', 'Study the tree’s seasonal shade, ecological value, building energy, outdoor comfort, root zone, and alternatives before deciding whether to retain or modify the relationship.', ['Remove the tree because solar access always controls.', 'Keep it without checking root and building effects.', 'Ignore seasonal change.', 'Treat the tree as a fixed shade device with no maintenance.'], 'Existing canopy can provide valuable shade but also changes solar access and construction constraints. The choice needs evidence and trade-offs.', 'tree and solar', 'PREREQUISITE_FREE', false, 'tree-solar-conflict', 'ecology and energy', true, ['single-benefit tree']);
$Q($cSpatial, 3, 'NEUTRAL', 'A site plan places a bus stop on the far side of a busy driveway from the accessible building entry. What should be improved?', 'Provide a safe, continuous, legible connection that coordinates transit, vehicles, crossings, shade, and access.', ['Keep the route because the bus stop is on the property.', 'Move the entry without checking transit users.', 'Ask users to cross between deliveries.', 'Use a sign to indicate the crossing without designing it.'], 'Transit access is part of the arrival system. The route must work for real users and vehicle operations.', 'transit access', 'PREREQUISITE_FREE', false, 'bus-stop-driveway', 'transit and entry', true, ['property-line-only access']);
$Q($cSpatial, 4, 'PROFESSIONAL', 'A design team wants to place a large sculpture at the center of a civic plaza, but it blocks the primary accessible route and emergency sightline. What is the best response?', 'Relocate or redesign the sculpture so the public-art goal remains while routes, visibility, and emergency operation are protected.', ['Keep it because public art is exempt from circulation.', 'Move the accessible route around the back.', 'Remove the art without considering alternatives.', 'Reduce route width to preserve the center.'], 'Public art participates in the space and must be coordinated with access and safety. A different placement can preserve both objectives.', 'public art coordination', 'PREREQUISITE_FREE', false, 'sculpture-route-conflict', 'public space interface', true, ['art over access']);
$Q($cSpatial, 3, 'NEUTRAL', 'A plan groups classrooms around a central courtyard but places the only service access through the student arrival route. Which planning improvement is most direct?', 'Separate service movement or schedule it so student arrival remains safe and legible.', ['Keep the shared route because it is central.', 'Move students to the loading edge.', 'Hide service vehicles behind a sign.', 'Remove the courtyard because service is necessary.'], 'Schools require clear user and service movement. The central courtyard does not justify an unsafe shared route.', 'school circulation', 'PREREQUISITE_FREE', false, 'school-service-arrival', 'student and service flows', true, ['centrality as solution']);
$Q($cSpatial, 4, 'PROFESSIONAL', 'A building’s future expansion zone is shaded by the existing wing and lies across the only emergency access path. What should the master plan test?', 'Expansion massing, solar access, emergency continuity, utilities, construction staging, and alternative growth directions.', ['Reserve the zone without checking access.', 'Build over the emergency path because the expansion is future.', 'Ignore shade because expansion is not occupied yet.', 'Remove emergency access until expansion is complete.'], 'Future capacity must remain buildable and safe. Expansion planning includes access and environmental consequences before the future phase arrives.', 'future expansion', 'PREREQUISITE_FREE', false, 'expansion-emergency-path', 'growth and access', true, ['future zone as empty area']);
$Q($cSpatial, 3, 'NEUTRAL', 'A courtyard is surrounded by reflective paving and glazing. Which environmental issue should be checked?', 'Glare, reflected heat, outdoor comfort, daylight balance, surface temperature, and shading.', ['Reflection always improves daylight.', 'Glazing and paving have no combined effect.', 'Shade is unnecessary around courtyards.', 'Use more reflective material to solve glare.'], 'Reflective surfaces can redistribute light and heat in ways that reduce comfort. Courtyard materials and geometry should be considered together.', 'courtyard materials', 'PREREQUISITE_FREE', false, 'courtyard-reflection', 'glare and heat', false, ['reflection as universal benefit']);
$Q($cSpatial, 4, 'PROFESSIONAL', 'A site is in a flood-prone area and the concept raises occupied floors, but the accessible route and service utilities remain at the lowest point. What should be integrated?', 'Flood-resilient placement, route continuity, utility protection, emergency operation, drainage, and accessible arrival as one site strategy.', ['Raising the occupied floor solves every flood issue.', 'Keep utilities low because they are replaceable.', 'Let the accessible route flood temporarily.', 'Move only the entrance sign upward.'], 'Flood resilience must include access and systems, not only occupied floor elevation. The site has to work during and after the hazard.', 'flood-resilient planning', 'PREREQUISITE_FREE', false, 'flood-route-utilities', 'hazard and access', true, ['raised-floor-only']);
$Q($cSpatial, 3, 'NEUTRAL', 'A plan places private offices along a public circulation spine with transparent doors and no acoustic buffer. Which issue should be evaluated?', 'Privacy, sound, visual exposure, security, wayfinding, and whether transparency serves or harms the program.', ['Transparency always improves collaboration.', 'Private offices need no separation from public routes.', 'Acoustics can be solved by door color.', 'Move every office away from circulation regardless of use.'], 'Transparency and adjacency can support orientation but create privacy and acoustic effects. The program should define the appropriate balance.', 'office adjacency', 'PREREQUISITE_FREE', false, 'transparent-office-spine', 'privacy and circulation', false, ['transparency as universal good']);
$Q($cSpatial, 4, 'PROFESSIONAL', 'A public housing site has limited land and must choose between a shared shaded court and small private yards. Which process is most defensible?', 'Compare household needs, social use, maintenance, access, shade, safety, stormwater, and equity across alternatives.', ['Choose shared space because it is more visible.', 'Choose private yards because public space is inefficient.', 'Compare only landscape area.', 'Let the first resident preference determine all units.'], 'Site planning should make distribution and user consequences explicit. There may be a hybrid or phased solution.', 'housing open-space choice', 'PREREQUISITE_FREE', false, 'shared-private-yard', 'equitable open space', true, ['one-user preference']);
